  function pad2(n) { return String(n).padStart(2, "0"); }
  // Returns the object-position value so the board card naturally shows
  // only the played face.  The full image contains both animals; cover+position
  // crops to the correct half without any distortion.
  // horizontal_cards (1-96): images are STACKED top/bottom — odd uid = top face (Up), even = bottom face (Down).
  // vertical_cards (101-188): images are SIDE-BY-SIDE left/right — odd uid = left face (Left), even = right face (Right).
  function cardHalfPos(faceUid) {
    let u = Number(faceUid);
    if (u >= 1000000) u = u % 1000;   // admin-minted copy → original art face (uid = serial*1000 + face)
    if (u >= 1   && u <= 96)  return u % 2 === 1 ? "top"    : "bottom";
    if (u >= 101 && u <= 188) return u % 2 === 1 ? "left"   : "right";
    return "center";
  }

  function imagePathForUid(uid) {
    let u = Number(uid);
    if (u >= 1000000) u = u % 1000;   // admin-minted copy → original art face (uid = serial*1000 + face)
    if (u >= 1   && u <= 96)  return `/horizontal_cards/page_${pad2(Math.floor((u+1)/2))}.png?v=${CARD_IMAGE_VERSION}`;
    if (u >= 101 && u <= 188) return `/vertical_cards/page_${pad2(Math.floor((u-101)/2)+1)}.png?v=${CARD_IMAGE_VERSION}`;
    if (u >= 201 && u <= 266) return `/oceans_cards/page_${pad2(u-200)}.png?v=${CARD_IMAGE_VERSION}`;
    return "";
  }

  // Current Controller (admin) — visual card tiles in the mod viewers.
  // Returns the sprite-sheet URL plus which half of the sheet holds this face,
  // so a tile can crop to the correct single card face.
  window.__ccCardImg = (faceUid) => ({ url: imagePathForUid(faceUid), pos: cardHalfPos(faceUid) });

  // Display-only cache-bust for LOCAL avatar PNGs: appends ?v=VERSION so a
  // refreshed avatar image (same /avatars/x.png path) is never served stale.
  // Only touches /avatars/ paths — external (Google) avatar URLs are left as-is.
  // Stored/compared paths stay clean; the server ignores the query (basename match).
  const _AVATAR_ART_VERSION = "ws12";
  function _avSrc(url) {
    const u = String(url || "");
    // Cache-bust both avatar AND background art so a version bump always refreshes
    // them (background tiles in the gallery pass through here too).
    if (u.includes("?") || !(u.startsWith("/avatars/") || u.startsWith("/backgrounds/"))) return u;
    return u + "?v=" + _AVATAR_ART_VERSION;
  }
  window.__fishAvSrc = _avSrc;

  // Cache-busted URL for an exclusive background path.
  function _bgSrc(url) {
    const u = String(url || "");
    if (!u.startsWith("/backgrounds/") || u.includes("?")) return u;
    return u + "?v=" + _AVATAR_ART_VERSION;
  }
  // Inline style string for an avatar wrapper built via innerHTML, so the
  // background shows behind a (transparent) avatar image. Empty when no bg.
  function _bgStyle(url) {
    const u = String(url || "");
    if (!u.startsWith("/backgrounds/")) return "";
    return `background-image:url('${_bgSrc(u)}');background-size:cover;background-position:center;`;
  }
  window.__fishBgStyle = _bgStyle;
  // Render (or clear) an exclusive background behind an avatar. `wrapEl` is the
  // circular/rounded avatar container that holds the avatar <img>. Passing a
  // falsy bgUrl removes any previously-applied background. The avatar <img> is
  // lifted above the background layer so transparent avatar art shows the scene.
  function _applyAvBg(wrapEl, bgUrl) {
    if (!wrapEl) return;
    let layer = wrapEl.querySelector(":scope > .cc-avbg");
    const clean = String(bgUrl || "");
    if (!clean || !clean.startsWith("/backgrounds/")) {
      if (layer) layer.remove();
      wrapEl.classList.remove("cc-has-bg");
      return;
    }
    // Force a positioning context so the absolute .cc-avbg can't escape the
    // wrap. getComputedStyle returns "" for detached elements (chat avatars are
    // built off-DOM), so a "=== static" check alone would miss them and let the
    // background bleed out to the nearest positioned ancestor (the whole chat).
    const _pos = getComputedStyle(wrapEl).position;
    if (_pos !== "relative" && _pos !== "absolute" && _pos !== "fixed" && _pos !== "sticky") {
      wrapEl.style.position = "relative";
    }
    if (!layer) {
      layer = document.createElement("div");
      layer.className = "cc-avbg";
      wrapEl.insertBefore(layer, wrapEl.firstChild);
    }
    layer.style.backgroundImage = `url("${_bgSrc(clean)}")`;
    wrapEl.classList.add("cc-has-bg");
  }
  window.__fishApplyAvBg = _applyAvBg;

  // ── URL / API utilities (identical to index.html) ──────────────
  function normalizeBaseUrl(raw) { return String(raw||"").trim().replace(/\/+$/,""); }
  function normalizeAbsoluteBaseUrl(raw) {
    const s = normalizeBaseUrl(raw);
    if (!s || !/^https?:\/\//i.test(s)) return "";
    try { const u = new URL(s); return u.host ? `${u.protocol}//${u.host}` : ""; } catch { return ""; }
  }
  function activeApiBaseUrl() {
    const fw = normalizeBaseUrl(window.__FISH_API_BASE__ || "");
    if (fw) return fw;
    const qs = new URLSearchParams(location.search);
    const fq = normalizeBaseUrl(qs.get("api_base") || "");
    if (fq) return fq;
    try { const s = normalizeBaseUrl(localStorage.getItem("fish_api_base_url")||""); if (s) return s; } catch {}
    return normalizeAbsoluteBaseUrl(location.origin) || "";
  }
  function apiUrl(path) {
    const base = activeApiBaseUrl();
    const p = String(path||"");
    if (!base) return p;
    return p.startsWith("/") ? `${base}${p}` : `${base}/${p}`;
  }

  // ── Room / token helpers (same localStorage keys as index.html) ─
  // Room codes are 4–12 uppercase letters/numbers. Public rooms get a random
  // 5-char code (used internally only — never shown). Private rooms use the
  // host's chosen code as both the join code AND the password.
  const ROOM_ID_RE = /^[A-Z0-9]{4,12}$/;
  function normalizeRoomId(raw) { const r = String(raw||"").trim().toUpperCase(); return ROOM_ID_RE.test(r)?r:""; }
  // Turn an arbitrary private "password" into a valid room code: strip to
  // letters/numbers, uppercase. Returns "" if the result isn't 4–12 chars.
  function normalizeRoomCode(raw) {
    const r = String(raw||"").toUpperCase().replace(/[^A-Z0-9]/g, "");
    return ROOM_ID_RE.test(r) ? r : "";
  }
  function seatTokenKey(id)  { return `fish_room_${id}_seat_token`; }
  function hostTokenKey(id)  { return `fish_room_${id}_host_token`; }
  function createKeyKey()    { return "fish_create_key"; }
  function rejoinKey(id)     { return `fish_rejoin_${id}`; }

  let roomId = null;
  // Visibility + private code of the room this client just created (host only),
  // used to drive the waiting-room display: public hides the code, private shows
  // the code (which is also the password). Cleared when not the creator.
  let _myRoomVisibility = "";
  let _myRoomCode = "";
  // sessionStorage is tab-isolated — each browser tab gets its own token so
  // multiple players on the same device don't overwrite each other's seat.
  function getSeatToken()  { if (!roomId) return ""; try { return sessionStorage.getItem(seatTokenKey(roomId))||""; } catch { return ""; } }
  function getHostToken()  { if (!roomId) return ""; try { return sessionStorage.getItem(hostTokenKey(roomId))||""; } catch { return ""; } }
  function setSeatToken(v) {
    if (!roomId) return;
    try { sessionStorage.setItem(seatTokenKey(roomId), v); } catch {}
    // Mirror to localStorage so the player can rejoin within 8 minutes of
    // closing the tab OR leaving the game.
    if (v) { try { localStorage.setItem(rejoinKey(roomId), JSON.stringify({ token: v, savedAt: Date.now() })); } catch {} }
  }
  function setHostToken(v) { if (!roomId) return; try { sessionStorage.setItem(hostTokenKey(roomId), v); } catch {} }
  function getCreateKey()  { try { return localStorage.getItem(createKeyKey())||""; } catch { return ""; } }

  const REJOIN_WINDOW_MS = 8 * 60 * 1000;  // matches server REJOIN_WINDOW_SEC
  // Returns a valid rejoin token for a room if it was saved within the window.
  function loadRejoinToken(id) {
    try {
      const raw = localStorage.getItem(rejoinKey(id));
      if (!raw) return null;
      const obj = JSON.parse(raw);
      if (!obj?.token || !obj?.savedAt) return null;
      if (Date.now() - obj.savedAt > REJOIN_WINDOW_MS) { localStorage.removeItem(rejoinKey(id)); return null; }
      return obj.token;
    } catch { return null; }
  }
  // Keep the rejoin timestamp fresh so the window is measured from the last active moment.
  function touchRejoinToken() {
    if (!roomId) return;
    try {
      const raw = localStorage.getItem(rejoinKey(roomId));
      if (!raw) return;
      const obj = JSON.parse(raw);
      if (!obj?.token) return;
      obj.savedAt = Date.now();
      localStorage.setItem(rejoinKey(roomId), JSON.stringify(obj));
    } catch {}
  }
  function clearRejoinToken(id) {
    const k = id || roomId;
    if (!k) return;
    try { localStorage.removeItem(rejoinKey(k)); } catch {}
  }
  function makeRequestId() { return `preq_${Date.now()}_${Math.random().toString(36).slice(2,7)}`; }

  // Reserved single-segment page names that must NEVER be treated as a room
  // ID. normalizeRoomId() uppercases and accepts 4–12 [A-Z0-9], so without this
  // guard "/game", "/preview", "/about" etc. would be misread as rooms "GAME",
  // "PREVIEW", "ABOUT" — breaking the launcher and the dedicated game window.
  const RESERVED_PATH_NAMES = new Set([
    "play","preview","classic","old","game","website","site","rules","about","leaderboard",
  ]);
  function roomFromUrl() {
    const parts = location.pathname.split("/").filter(Boolean);
    // /play/XXXXX or /preview/XXXXX or /classic/XXXXX
    if (parts.length >= 2) {
      const r = normalizeRoomId(parts[1]); if (r) return r;
    }
    // /XXXXX (bare room ID as path) — but never a reserved page name
    if (parts.length === 1 && !RESERVED_PATH_NAMES.has(parts[0].toLowerCase())) {
      const r = normalizeRoomId(parts[0]); if (r) return r;
    }
    const qs = new URLSearchParams(location.search);
    return normalizeRoomId(qs.get("room")||qs.get("roomId")||"");
  }

  // ── Fetch helpers ──────────────────────────────────────────────
  async function sleep(ms) { return new Promise(r => setTimeout(r, ms)); }

  function ccReport(kind, detail, level) {
    try {
      if (window.CCErrorLog && typeof window.CCErrorLog.report === "function") {
        window.CCErrorLog.report(kind, detail || {}, level || "warn");
      }
    } catch (_) {}
  }

  function ccErrDetail(err) {
    return {
      name: err && err.name,
      code: err && err.code,
      message: err && (err.message || err)
    };
  }

  async function apiFetch(path, opts = {}) {
    const url = apiUrl(path);
    const logPath = String(path || "").split("?")[0];
    const timeoutMs = opts.timeoutMs || 5000;
    const maxRetries = opts.retries ?? 1; // auto-retry once on 503/502 (Render waking up)
    let attempt = 0;
    while (true) {
      const ac = typeof AbortController !== "undefined" ? new AbortController() : null;
      const tid = ac ? setTimeout(() => ac.abort(), timeoutMs) : null;
      try {
        const res = await fetch(url, {
          cache: "no-store",
          signal: ac?.signal,
          ...(opts.method && { method: opts.method }),
          ...(opts.body !== undefined && { body: JSON.stringify(opts.body), headers: { "Content-Type": "application/json" } }),
        });
        const text = await res.text();
        let data; try { data = JSON.parse(text); } catch { data = {}; }
        // On 503/502 (server waking up), retry once after a short wait
        if ((res.status === 503 || res.status === 502) && attempt < maxRetries) {
          attempt++;
          await new Promise(r => setTimeout(r, 2500));
          continue;
        }
        if (!res.ok) {
          ccReport("api_http_error", {
            path: logPath,
            method: opts.method || "GET",
            status: res.status,
            error: data && data.error,
            attempt
          }, "warn");
        }
        return { ok: res.ok, status: res.status, data };
      } catch (err) {
        if (attempt < maxRetries && err?.name !== "AbortError") {
          attempt++;
          await new Promise(r => setTimeout(r, 2500));
          continue;
        }
        ccReport("api_fetch_failed", {
          path: logPath,
          method: opts.method || "GET",
          timeoutMs,
          attempt,
          error: err && (err.name || err.message || err)
        }, "error");
        throw err;
      } finally { if (tid) clearTimeout(tid); }
    }
  }
  async function apiPost(path, body, opts={}) { return apiFetch(path, { ...opts, method:"POST", body }); }

  // ── End-game cinematic ─────────────────────────────────────────
  let _egDismissTimer = null;
  function showEndGameCinematic(cardUid, triggerPlayerName, isTriggerPlayer) {
    const el = document.getElementById("endgame-cinematic");
    const img = document.getElementById("eg-card-img");
    const sub = document.getElementById("eg-sub-text");
    img.src = imagePathForUid(cardUid);
    if (isTriggerPlayer) {
      sub.textContent = "You revealed the END GAME card — you still get one final turn!";
    } else {
      sub.textContent = triggerPlayerName
        ? `${triggerPlayerName} revealed the END GAME card — each player gets one final turn!`
        : "The END GAME card has been revealed — each player gets one final turn!";
    }
    // re-trigger animations by cloning key elements
    el.classList.remove("active");
    void el.offsetWidth;
    el.classList.add("active");
    if (_egDismissTimer) clearTimeout(_egDismissTimer);
    // Dismiss faster for the trigger player so they can act immediately
    _egDismissTimer = setTimeout(() => dismissEndGameCinematic(), isTriggerPlayer ? 2000 : 5000);
  }
  function dismissEndGameCinematic() {
    document.getElementById("endgame-cinematic").classList.remove("active");
    if (_egDismissTimer) { clearTimeout(_egDismissTimer); _egDismissTimer = null; }
  }
  document.getElementById("eg-dismiss-btn").addEventListener("click", dismissEndGameCinematic);
  document.getElementById("endgame-cinematic").addEventListener("click", (e) => {
    if (e.target === document.getElementById("endgame-cinematic")) dismissEndGameCinematic();
  });

  // ── Toast system ───────────────────────────────────────────────
  function showToast(msg, type = "info", durationMs = 3200) {
    const container = document.getElementById("pv-toasts");
    const t = document.createElement("div");
    t.className = `pv-toast toast-${type}`;
    t.textContent = msg;
    container.appendChild(t);
    requestAnimationFrame(() => requestAnimationFrame(() => t.classList.add("show")));
    setTimeout(() => {
      t.classList.remove("show");
      setTimeout(() => { if (t.parentNode) t.parentNode.removeChild(t); }, 350);
    }, Math.max(1500, Number(durationMs) || 3200));
  }

  // ── Hidden invertebrate easter-egg: click 3× to reveal a digit ──────
  // Four critters hidden around the UI. Each: click → line 1; click again
  // within ~5s → line 2; again → line 3; then it fades and the digit appears
  // in its exact spot. Idle >5s resets to line 1. State is in-memory only, so
  // navigating/refreshing returns every critter to its original spot.
  const _SECRET_CRITTERS = {
    star:     { img:"/avatars/sea-star.png",     number:"7", size:52,
      lines:["Stop touching me","I gotta stay hidden","They can turn invisible. I have to stay ready."] },
    sponge:   { img:"/avatars/sea-sponge.png",   number:"3", size:46,
      lines:["I won’t speak to you","It wasn’t fair that he stayed behind","He entrusted this to me"] },
    urchin:   { img:"/avatars/sea-urchin.png",   number:"9", size:28,
      lines:["Go away","I can hide in plain sight","I gotta go check up on the others"] },
    cucumber: { img:"/avatars/sea-cucumber.png", number:"1", size:46,
      lines:["I don’t know where my friends are","I think one is gone","Put the digits together and save us"] },
  };
  const _secretState = {}; // key -> { stage, timer, revealed }

  function _hideSecretBubbles() {
    document.querySelectorAll(".secret-bubble").forEach(b => b.remove());
  }
  function _showSecretBubble(el, text) {
    _hideSecretBubbles();
    const b = document.createElement("div");
    b.className = "secret-bubble";
    b.textContent = text;
    document.body.appendChild(b);
    const r = el.getBoundingClientRect();
    b.style.left = Math.round(r.left + r.width / 2) + "px";
    b.style.top  = Math.round(r.top - 6) + "px";
    setTimeout(() => { if (b.parentNode) b.remove(); }, 4800);
  }
  // Restore a critter to its untouched state (clears reveal + bubble + timer).
  function _resetSecretCritter(key) {
    const st = _secretState[key];
    if (st && st.timer) clearTimeout(st.timer);
    _secretState[key] = { stage: 0, timer: null, revealed: false };
    document.querySelectorAll(`.secret-wrap[data-secret="${key}"]`).forEach(wrap => {
      const img = wrap.querySelector(".secret-critter");
      if (img) img.classList.remove("secret-fading");
      const num = wrap.querySelector(".secret-number");
      if (num) num.remove();
    });
    _hideSecretBubbles();
  }
  function _resetAllSecretCritters() { Object.keys(_SECRET_CRITTERS).forEach(_resetSecretCritter); }
  window.__fishResetSecrets = _resetAllSecretCritters;

  function _wireSecretCritter(img, key) {
    const cfg = _SECRET_CRITTERS[key];
    if (!img || !cfg || img.__secretWired) return;
    img.__secretWired = true;
    img.classList.add("secret-critter");
    img.draggable = false;
    const wrap = img.closest(".secret-wrap");
    if (wrap) wrap.dataset.secret = key;
    img.addEventListener("click", (ev) => {
      ev.preventDefault(); ev.stopPropagation();
      let st = _secretState[key];
      if (!st) st = _secretState[key] = { stage: 0, timer: null, revealed: false };
      if (st.revealed) return;
      if (st.timer) clearTimeout(st.timer);
      st.stage += 1;
      if (st.stage > 3) return;
      _showSecretBubble(img, cfg.lines[st.stage - 1]);
      if (st.stage === 3) {
        st.revealed = true;
        img.classList.add("secret-fading");
        setTimeout(() => {
          const w = img.closest(".secret-wrap");
          if (!w) return;
          if (!w.querySelector(".secret-number")) {
            const num = document.createElement("div");
            num.className = "secret-number";
            num.textContent = cfg.number;
            w.appendChild(num);
          }
        }, 1050);
        setTimeout(_hideSecretBubbles, 2600);
      } else {
        st.timer = setTimeout(() => { st.stage = 0; _hideSecretBubbles(); }, 5000);
      }
    }, true);
  }

  // Create a fresh critter <img> (wrapped) inside `container`, reset its state.
  // Used for the dynamically-rendered spots (leaderboard). Returns the wrap.
  function _placeSecretCritter(key, container) {
    if (!container) return null;
    const cfg = _SECRET_CRITTERS[key];
    if (!cfg) return null;
    _resetSecretCritter(key);
    const wrap = document.createElement("span");
    wrap.className = "secret-wrap";
    wrap.dataset.secret = key;
    const img = document.createElement("img");
    img.className = "secret-icon";
    img.src = cfg.img;
    img.alt = "";
    img.width = cfg.size; img.height = cfg.size;
    img.style.width = cfg.size + "px"; img.style.height = cfg.size + "px";
    wrap.appendChild(img);
    container.appendChild(wrap);
    _wireSecretCritter(img, key);
    return wrap;
  }
  window.__fishPlaceSecretCritter = _placeSecretCritter;

  // Wrap an EXISTING element (e.g. the daily-streak star img) as a critter.
  function _wrapExistingSecretCritter(img, key) {
    if (!img || img.__secretWired) return;
    if (!img.closest(".secret-wrap")) {
      const wrap = document.createElement("span");
      wrap.className = "secret-wrap";
      wrap.dataset.secret = key;
      img.parentNode.insertBefore(wrap, img);
      wrap.appendChild(img);
    }
    _wireSecretCritter(img, key);
  }
  window.__fishWrapSecretCritter = _wrapExistingSecretCritter;

  // Wire the two STATIC-location critters: the daily-streak Sea Star and the
  // Sea Urchin next to the Pool's "Inspect" button. Safe to call repeatedly.
  function _initStaticSecrets() {
    // Sea Star — already present in the Daily Streak sidebar.
    const starImg = document.querySelector('.ph-ss-icon .ph-ss-star-img')
                 || document.querySelector('.ph-ss-icon img[src*="sea-star"]');
    if (starImg) _wrapExistingSecretCritter(starImg, "star");
    // Sea Urchin — lives INSIDE the Pool Overview Modal, next to the
    // "Pool · N cards" title. Only visible when the player opens Inspect.
    const slot = document.getElementById("pv-pm-urchin-slot");
    if (slot && !slot.querySelector("img")) {
      const cfg = _SECRET_CRITTERS.urchin;
      const img = document.createElement("img");
      img.className = "secret-icon";
      img.src = cfg.img; img.alt = "";
      img.style.width = cfg.size + "px"; img.style.height = cfg.size + "px";
      img.style.display = "block";
      slot.appendChild(img);
      _wireSecretCritter(img, "urchin");
    }
  }
  window.__fishInitStaticSecrets = _initStaticSecrets;
  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", _initStaticSecrets);
  } else {
    _initStaticSecrets();
  }
  setTimeout(_initStaticSecrets, 1800);

  // ── Card zoom modal ────────────────────────────────────────────
  // ── Zoom navigation state ──────────────────────────────────────
  let _zoomHandEntries = [];   // ordered visible hand entries for prev/next nav
  let _zoomHandIdx     = -1;  // current index within _zoomHandEntries

  function _zoomPopulateCard(uid, name, text, species) {
    document.getElementById("pv-zoom-img").src = imagePathForUid(uid);
    document.getElementById("pv-zoom-img").alt = name || "";
    document.getElementById("pv-zm-name").textContent = name || "";
    document.getElementById("pv-zm-species").textContent = species || "";
    document.getElementById("pv-zm-species").style.color = speciesColor(species);
    const mt = mainText(text||"");
    const st = starText(text||"");
    document.getElementById("pv-zm-text").textContent = mt;
    const starEl = document.getElementById("pv-zm-star");
    if (st) { starEl.textContent = "★ " + st; starEl.style.display = ""; }
    else { starEl.style.display = "none"; }
  }

  function _zoomUpdateNav() {
    const hasNav = _zoomHandEntries.length > 1 && _zoomHandIdx >= 0;
    const prevBtn = document.getElementById("pv-zoom-prev");
    const nextBtn = document.getElementById("pv-zoom-next");
    const counter = document.getElementById("pv-zoom-counter");
    prevBtn.style.display = hasNav ? "" : "none";
    nextBtn.style.display = hasNav ? "" : "none";
    counter.style.display = hasNav ? "" : "none";
    if (hasNav) {
      prevBtn.disabled = _zoomHandIdx <= 0;
      nextBtn.disabled = _zoomHandIdx >= _zoomHandEntries.length - 1;
      counter.textContent = `${_zoomHandIdx + 1} / ${_zoomHandEntries.length}`;
    }
  }

  function _zoomPreselectDropdown(entryUid, faceUid) {
    const sel = document.getElementById("pv-action-select");
    if (!sel || !sel.options.length) return;
    // Find the first non-star play action for this card
    const act = legalActions.find(a =>
      (a.kind === "play_to_ocean" || a.kind === "play_ocean") &&
      !a.use_star &&
      (Number(a.card_uid) === entryUid || Number(a.face_uid) === faceUid)
    );
    if (act) sel.value = String(act.index);
  }

  function openZoom(uid, name, text, species, handEntries, handIdx) {
    _zoomHandEntries = Array.isArray(handEntries) ? handEntries : [];
    _zoomHandIdx     = (typeof handIdx === "number") ? handIdx : -1;
    _zoomPopulateCard(uid, name, text, species);
    _zoomUpdateNav();
    document.getElementById("pv-zoom-modal").classList.add("open");
  }

  function _zoomNavTo(idx) {
    if (idx < 0 || idx >= _zoomHandEntries.length) return;
    _zoomHandIdx = idx;
    const entry   = _zoomHandEntries[idx];
    const face    = (Array.isArray(entry.faces) && entry.faces.length > 0) ? entry.faces[0] : entry;
    const faceUid = Number(face.uid ?? entry.entry_uid ?? entry.uid);
    const entryUid = Number(entry.entry_uid ?? face.uid ?? entry.uid);
    _zoomPopulateCard(faceUid, face.name, face.text, face.species);
    _zoomUpdateNav();
    _zoomPreselectDropdown(entryUid, faceUid);
  }

  function closeZoom() { document.getElementById("pv-zoom-modal").classList.remove("open"); }
  document.getElementById("pv-zoom-close").addEventListener("click", closeZoom);
  document.getElementById("pv-zoom-prev").addEventListener("click", () => _zoomNavTo(_zoomHandIdx - 1));
  document.getElementById("pv-zoom-next").addEventListener("click", () => _zoomNavTo(_zoomHandIdx + 1));
  document.getElementById("pv-zoom-modal").addEventListener("click", (e) => {
    if (e.target === document.getElementById("pv-zoom-modal")) closeZoom();
  });
  // Arrow key navigation when zoom is open
  document.addEventListener("keydown", (e) => {
    if (!document.getElementById("pv-zoom-modal").classList.contains("open")) return;
    if (e.key === "ArrowLeft")  { e.preventDefault(); _zoomNavTo(_zoomHandIdx - 1); }
    if (e.key === "ArrowRight") { e.preventDefault(); _zoomNavTo(_zoomHandIdx + 1); }
    if (e.key === "Escape")     { e.preventDefault(); closeZoom(); }
  });

  // ── Pool overview modal ────────────────────────────────────────
  function openPoolModal() {
    document.getElementById("pv-pool-modal").classList.add("open");
    renderPoolModal();
  }
  function closePoolModal() {
    document.getElementById("pv-pool-modal").classList.remove("open");
  }
  function renderPoolModal() {
    const modal = document.getElementById("pv-pool-modal");
    if (!modal.classList.contains("open")) return;
    const pool = _latestPool;
    const actions = _latestPoolActions;
    const drawActions = actions.filter(a => a.kind === "draw");
    const canDrawPool = drawActions.some(a => Number(a.draw_from_pool) > 0);
    const titleEl = document.getElementById("pv-pm-title");
    const hintEl  = document.getElementById("pv-pm-hint");
    const gridEl  = document.getElementById("pv-pm-grid");
    const emptyEl = document.getElementById("pv-pm-empty");
    titleEl.textContent = `Pool · ${pool.length} card${pool.length !== 1 ? "s" : ""}`;
    const isSecondDrawModal = drawActions.length > 0 && !_latestPoolActions.some(a => a.kind !== "draw" && a.kind !== "end_turn");
    if (isSecondDrawModal && canInteract && canDrawPool) {
      hintEl.textContent = "Choose your 2nd card — click any pool card to draw it";
      hintEl.style.display = "";
    } else {
      hintEl.style.display = "none";
    }
    if (!pool.length) {
      gridEl.innerHTML = "";
      emptyEl.style.display = "";
      return;
    }
    emptyEl.style.display = "none";
    gridEl.innerHTML = "";
    pool.forEach(entry => {
      const face = (Array.isArray(entry.faces) && entry.faces.length > 0) ? entry.faces[0] : entry;
      const faceUid = Number(face.uid ?? entry.entry_uid ?? entry.uid);
      const card = document.createElement("div");
      card.className = "pv-pm-card";
      const imgWrap = document.createElement("div");
      imgWrap.className = "pv-pm-card-img";
      const img = document.createElement("img");
      img.src = imagePathForUid(faceUid);
      img.alt = face.name || "";
      img.loading = "lazy";
      imgWrap.appendChild(img);
      const nameEl = document.createElement("div");
      nameEl.className = "pv-pm-card-name";
      nameEl.textContent = face.name || "";
      card.appendChild(imgWrap);
      card.appendChild(nameEl);
      if (canDrawPool && canInteract) {
        let _pmTimer = null;
        card.addEventListener("dblclick", e => {
          e.stopPropagation();
          clearTimeout(_pmTimer);
          openZoom(faceUid, face.name, face.text, face.species);
        });
        card.addEventListener("click", e => {
          e.stopPropagation();
          clearTimeout(_pmTimer);
          _pmTimer = setTimeout(() => {
            closePoolModal();
            _drawFromPool(drawActions, faceUid);
          }, 200);
        });
      } else {
        card.addEventListener("click", e => {
          e.stopPropagation();
          openZoom(faceUid, face.name, face.text, face.species);
        });
      }
      gridEl.appendChild(card);
    });
  }
  document.getElementById("pv-pool-expand-btn").addEventListener("click", openPoolModal);
  document.getElementById("pv-pm-close").addEventListener("click", closePoolModal);
  document.getElementById("pv-pool-modal").addEventListener("click", e => {
    if (e.target === document.getElementById("pv-pool-modal")) closePoolModal();
  });

  document.getElementById("ph-gdm-close").addEventListener("click", () => {
    document.getElementById("ph-game-detail-modal").classList.remove("open");
  });
  document.getElementById("ph-game-detail-modal").addEventListener("click", (e) => {
    if (e.target === document.getElementById("ph-game-detail-modal"))
      document.getElementById("ph-game-detail-modal").classList.remove("open");
  });

  // ── State polling ──────────────────────────────────────────────
  let latestPayload = null;
  let pollTimer = null;
  let sseSource = null;
  let refreshInFlight = false;
  // Monotonic server state version of the last payload we applied. SSE pushes
  // and 1 s polling both deliver state; without this guard a slow/late poll
  // response can overwrite newer state with older, causing turn desync ("says
  // it's my turn when it isn't" / "my turn but won't let me play"). We drop any
  // payload whose version is strictly older than what we've already rendered.
  let _lastStateVersion = -1;
  let _lastRenderedVersion = -1; // skip full re-render when server version hasn't changed

  // ── Current Controller (admin mod tools) bridges ──────────────────
  // Read-only accessors so the Current Controller module (a separate <script>
  // at the end of the file) can reach the authoritative client state without
  // sharing lexical scope. Exposes nothing privileged — just what the client
  // already holds.
  window.__ccGetPayload = () => latestPayload;
  window.__ccConnInfo   = () => ({ version: _lastStateVersion, sse: !!sseSource, polling: !!pollTimer, room: (typeof roomId !== "undefined" ? roomId : null) || null });
  window.__ccLastAction = null;
  window.__ccNoteAction = (a) => { try { window.__ccLastAction = { kind: a && a.kind, action: a, at: Date.now() }; } catch (_) {} };
  // Monotonic count of successfully-submitted draw actions (deck OR pool). The
  // guided tutorial uses this to detect "the player drew their 2 cards" — needed
  // because the 2nd draw ends the turn, so a turn-state check (can_act) can't be
  // relied on to confirm the draw completed.
  let _ccDrawCount = 0;
  window.__ccDrawCount = () => _ccDrawCount;
  // Live payment-mode bridge for the guided tutorial: returns the action that is
  // currently staged waiting for the player to pick discard cards (or null when
  // not paying). Lets the tour detect "the player started paying for the Ocean /
  // creature" and walk them through Confirm Payment. (pendingPayAction is a let
  // in this same scope, assigned far below — only read at runtime mid-game.)
  window.__ccPendingPay = () => { try { return pendingPayAction || null; } catch (_) { return null; } };
  // Server-mod bridges: room id, this client's seat token, the live legal-action
  // list, and an apply hook (used by What If → Apply This Move).
  window.__ccRoomId = () => (typeof roomId !== "undefined" ? roomId : null);
  window.__ccSeatToken = () => { try { return (typeof getSeatToken === "function") ? getSeatToken() : null; } catch (_) { return null; } };
  window.__ccLegalActions = () => (typeof legalActions !== "undefined" && Array.isArray(legalActions) ? legalActions : []);
  window.__ccApplyAction = (i) => { try { return submitAction(legalActions[i]); } catch (_) { return null; } };
  window.__ccApiUrl = (p) => { try { return (typeof apiUrl === "function") ? apiUrl(p) : p; } catch (_) { return p; } };
  // Used by "The Game" tutorial to leave the rigged practice game and return to
  // the menu (the tour then reopens the tutorial chooser).
  window.__tutLeaveGame = async () => {
    try {
      const token = (typeof getSeatToken === "function") ? getSeatToken() : null;
      const rid = (typeof roomId !== "undefined") ? roomId : null;
      if (token && rid) {
        try { await apiPost(`/api/rooms/${rid}/leave`, { seat_token: token }, { timeoutMs: 5000 }); } catch (_) {}
      }
    } catch (_) {}
    try { returnToMenu(false); } catch (_) {}
  };
  let _serverWaking = false;       // true while Render server is returning 503
  let _serverWakeToastShown = false; // only show the "waking up" toast once per session
  let _prevTurnIdx = null;
  let _prevScore = null;
  let _myIdxGlobal = null;
  let _prevReplayTurn = false;
  // Timestamp (ms) of the last successfully-submitted action. Any payload
  // that arrives within 600 ms of an action AND still says can_act=true is
  // almost certainly a stale poll that raced the action — suppress the banner
  // update so "YOUR TURN" / "PLAY AGAIN" can't reappear until the fresh state
  // from the 160 ms post-action refresh arrives.
  let _lastActionMs = 0;
  let _prevTarponActive = false; // Tarpon avatar: detect each full-hand discard cycle
  let _lastHandCount = 0;        // viewer hand count from the previous render (pre-Tarpon hand)
  let _tarponStartHand = 0;      // hand size captured when a Tarpon discard phase begins
  let _prevEndTriggered = true; // start true so we only fire on a real false→true transition
  let _prevMustDiscard = false;  // detect false→true transition to reset selection state

  function buildStateUrl() {
    if (!roomId) return null;
    const p = new URLSearchParams();
    let seat, host;
    if (compMode) {
      // Use the token for whichever of my seats is currently active
      const activeSeat = latestPayload?.active_action_seat;
      const activeNum = Number(activeSeat);
      seat = (compMySeats.includes(activeNum) && compTokens[activeNum])
        ? compTokens[activeNum]
        : compTokens[compMySeats[0]] || getSeatToken();
      host = compHostToken || getHostToken();
    } else {
      seat = getSeatToken();
      host = getHostToken();
    }
    if (seat) p.set("seat_token", seat); else if (host) p.set("host_token", host);
    const qs = p.toString();
    return apiUrl(`/api/rooms/${roomId}/state${qs?"?"+qs:""}`);
  }

  // Single gate for applying a server state payload from either SSE or polling.
  // Returns true if applied, false if dropped as stale/out-of-order.
  function applyServerPayload(d) {
    if (!d || d.ok === false) return false;
    const v = Number(d.version);
    if (Number.isFinite(v) && v < _lastStateVersion) return false; // stale, drop
    if (Number.isFinite(v)) _lastStateVersion = v;
    latestPayload = d;
    // Competitive: a player controls two hands (two seats). When the turn
    // switches to my OTHER hand, the just-completed poll may have used my first
    // hand's token, so this payload's viewer is the wrong hand (can_act=false →
    // "waiting…"). Detect that and immediately re-fetch with the now-active
    // hand's token so its board + YOUR TURN go live without a poll-cycle lag.
    if (compMode && Array.isArray(compMySeats)) {
      const aas = Number(d.active_action_seat);
      const viewerSeat = Number(d.viewer && d.viewer.seat_index);
      if (compMySeats.includes(aas) && compTokens[aas] && viewerSeat !== aas) {
        setTimeout(() => { try { refreshState(); } catch (_) {} }, 0);
      }
    }
    // Skip the full DOM rebuild when the server state hasn't changed since last render.
    // Manual calls to renderPayload() bypass this and always re-render (local state changes).
    if (Number.isFinite(v) && v === _lastRenderedVersion) return true;
    _lastRenderedVersion = v;
    renderPayload(d);
    return true;
  }

  // Force a state refresh after an action — ignores refreshInFlight so a
  // background poll can't block the corrective fetch that clears "YOUR TURN".
  async function refreshStateAfterAction() {
    if (!roomId) return;
    // Wait for any in-flight poll to finish first, then do our own fetch.
    // Cap at 400ms so we never wait more than half the polling window.
    const deadline = Date.now() + 400;
    while (refreshInFlight && Date.now() < deadline) {
      await new Promise(r => setTimeout(r, 30));
    }
    refreshState();
  }

  async function refreshState() {
    if (!roomId || refreshInFlight) return;
    refreshInFlight = true;
    try {
      const url = isSpectating()
        ? apiUrl(`/api/rooms/${_spectatorRoomId}/state?spectator_token=${encodeURIComponent(_spectatorToken)}`)
        : buildStateUrl();
      const { ok, status, data } = await apiFetch(url.replace(apiUrl(""),""), { method:"GET", timeoutMs:6000 });
      if (status === 503 || status === 502) {
        // Render free-tier server is starting up — show a one-time toast and
        // keep polling; it will come back on its own in ~30 seconds.
        if (!_serverWaking) {
          _serverWaking = true;
          try { setStatus("⏳ Server waking up…"); } catch {}
          if (!_serverWakeToastShown) {
            _serverWakeToastShown = true;
            try { showToast("Server is warming up — connecting automatically in ~30 s", "warn"); } catch {}
          }
        }
        return;
      }
      if (_serverWaking) {
        // Server just came back online
        _serverWaking = false;
        try { showToast("Connected!", "ok"); } catch {}
      }
      if (ok && data && data.ok !== false) { applyServerPayload(data); }
      else if (data?.error === "room not found") handleRoomLost();
    } catch (e) {
      ccReport("reconnect_state_refresh_failed", {
        room: roomId,
        spectator: isSpectating() ? "1" : "0",
        error: e && (e.name || e.message || e)
      }, "warn");
    }
    finally { refreshInFlight = false; }
  }

  let _rejoinTouchTimer = null;
  function startPolling() {
    // Reset version guards: state_version is monotonic per room but a newly
    // joined room restarts low, so a stale high baseline would drop every
    // update. Entering/reconnecting always re-establishes the baseline.
    _lastStateVersion = -1;
    _lastRenderedVersion = -1;
    if (pollTimer) clearInterval(pollTimer);
    pollTimer = setInterval(refreshState, 1000);
    // Keep the rejoin window alive: refresh the localStorage timestamp every 60 s while active
    if (_rejoinTouchTimer) clearInterval(_rejoinTouchTimer);
    _rejoinTouchTimer = setInterval(touchRejoinToken, 60_000);
    refreshState();
  }

  let _roomLostShown = false;
  function handleRoomLost() {
    if (_roomLostShown) return;
    _roomLostShown = true;
    _specSetPresence(null); // clear in-game presence
    stopThemeSong();
    if (pollTimer) { clearInterval(pollTimer); pollTimer = null; }
    if (sseSource) { sseSource.close(); sseSource = null; }
    clearRejoinToken(roomId);
    showToast("Session ended — the server restarted. Please re-join.", "err");
    setTimeout(() => {
      _roomLostShown = false;
      roomId = null;
      document.getElementById("pv-game").style.display = "none";
      if (typeof window.__fishShowStatsLobby === "function") {
        window.__fishShowStatsLobby();
      } else {
        document.getElementById("pv-lobby").style.display = "none";
      }
      lobbyStatus("Session ended — server restarted. Create or join a new room.", true);
    }, 2500);
  }

  let _lastSseErrorLogMs = 0;
  function startSSE() {
    if (!roomId) return;
    if (compMode) return;  // competitive mode uses polling only
    _lastStateVersion = -1; _lastRenderedVersion = -1; // re-establish baseline for this connection
    if (sseSource) { sseSource.close(); sseSource = null; }
    const p = new URLSearchParams();
    const seat = getSeatToken(); const host = getHostToken();
    if (seat) p.set("seat_token", seat); else if (host) p.set("host_token", host);
    const qs = p.toString();
    const url = apiUrl(`/api/rooms/${roomId}/stream${qs?"?"+qs:""}`);
    try {
      sseSource = new EventSource(url);
      sseSource.onmessage = (ev) => {
        try {
          const d = JSON.parse(ev.data);
          if (d && d.ok !== false) { applyServerPayload(d); }
          else if (d?.error === "room not found") handleRoomLost();
        } catch {}
      };
      sseSource.onerror = () => {
        const now = Date.now();
        if (now - _lastSseErrorLogMs > 15000) {
          _lastSseErrorLogMs = now;
          ccReport("reconnect_stream_error", { room: roomId }, "warn");
        }
        // SSE dropped — polling will keep trying; room not found is handled there
      };
    } catch (e) {
      ccReport("reconnect_stream_start_failed", {
        room: roomId,
        error: e && (e.name || e.message || e)
      }, "warn");
    }
  }

  // ── Theme song (Web Audio API for gapless looping) ────────────
  // Plain <audio loop> on M4A files re-processes the file metadata at
  // each loop boundary, which on some browsers produces a "drowned out"
  // / muffled sound after a few cycles. Web Audio API decodes the file
  // once into a buffer and loops it natively → clean, gapless playback.
  let _themeAudioCtx = null;
  let _themeBuffer = null;
  let _themeSource = null;
  let _themeGain = null;
  let _themeBufferLoading = false;
  let _themeStarting = false;

  // Music volume — 0..100 stored in localStorage, mapped onto the theme gain.
  // 100% == the old fixed loudness (gain 2.2); 0% == silent (song never starts).
  const MUSIC_VOL_KEY = "fish_music_volume";
  const MUSIC_MAX_GAIN = 2.2;
  function musicVolumePct() {
    try {
      const raw = localStorage.getItem(MUSIC_VOL_KEY);
      if (raw === null || raw === "") {
        // Back-compat: honour the old on/off flag if no volume was saved yet.
        return localStorage.getItem("fish_music_on") === "0" ? 0 : 100;
      }
      const v = parseInt(raw, 10);
      if (!Number.isFinite(v)) return 100;
      return Math.max(0, Math.min(100, v));
    } catch { return 100; }
  }
  function applyThemeVolume() {
    if (!_themeGain) return;
    try {
      const target = MUSIC_MAX_GAIN * (musicVolumePct() / 100);
      // Ramp instead of hard-setting so rapid slider drags don't "zipper"/click.
      // A tiny time-constant (~15ms) settles fast enough to feel instant.
      if (_themeAudioCtx && typeof _themeGain.gain.setTargetAtTime === "function") {
        _themeGain.gain.setTargetAtTime(target, _themeAudioCtx.currentTime, 0.015);
      } else {
        _themeGain.gain.value = target;
      }
    } catch {}
  }
  window.__ccApplyThemeVolume = applyThemeVolume;

  async function _ensureThemeBuffer() {
    if (_themeBuffer) return _themeBuffer;
    if (_themeBufferLoading) return null;
    _themeBufferLoading = true;
    try {
      if (!_themeAudioCtx) {
        const Ctx = window.AudioContext || window.webkitAudioContext;
        if (!Ctx) return null;
        _themeAudioCtx = new Ctx();
      }
      const base = (typeof activeApiBaseUrl === "function" ? activeApiBaseUrl() : "") || "";
      const url = (base ? base : "") + "/theme-song.m4a?v=" + encodeURIComponent(APP_BUILD);
      const res = await fetch(url, { cache: "force-cache" });
      if (!res.ok) return null;
      const arr = await res.arrayBuffer();
      _themeBuffer = await new Promise((resolve, reject) => {
        try {
          const p = _themeAudioCtx.decodeAudioData(arr, resolve, reject);
          if (p && typeof p.then === "function") p.then(resolve, reject);
        } catch (e) { reject(e); }
      });
      return _themeBuffer;
    } catch { return null; }
    finally { _themeBufferLoading = false; }
  }

  async function startThemeSong() {
    try {
      // Respect the player's music volume (Settings). If it's at 0, never
      // start — this keeps it silent in-game even after turning it down.
      try { if (musicVolumePct() <= 0) return; } catch {}
      if (_themeSource || _themeStarting) return; // already playing, or already starting
      // Claim the "starting" slot synchronously, before the buffer-load await
      // below, so a second startThemeSong() call fired while this one is
      // still in flight (e.g. a fast reconnect) can't slip past the
      // _themeSource guard and spin up a duplicate, out-of-phase source.
      _themeStarting = true;
      const buffer = await _ensureThemeBuffer();
      if (!buffer || !_themeAudioCtx) return;
      if (_themeAudioCtx.state === "suspended") {
        try { await _themeAudioCtx.resume(); } catch {}
      }
      _themeSource = _themeAudioCtx.createBufferSource();
      _themeSource.buffer = buffer;
      _themeSource.loop = true;
      _themeGain = _themeAudioCtx.createGain();
      _themeGain.gain.value = MUSIC_MAX_GAIN * (musicVolumePct() / 100);
      _themeSource.connect(_themeGain).connect(_themeAudioCtx.destination);
      _themeSource.start(0);
    } catch {}
    finally { _themeStarting = false; }
  }

  function stopThemeSong() {
    try {
      if (_themeSource) {
        try { _themeSource.stop(0); } catch {}
        try { _themeSource.disconnect(); } catch {}
        _themeSource = null;
      }
      if (_themeGain) {
        try { _themeGain.disconnect(); } catch {}
        _themeGain = null;
      }
    } catch {}
  }

  // ── Spectator state ───────────────────────────────────────────────
  let _spectatorToken = "";      // non-empty when we are spectating
  let _spectatorRoomId = "";     // room we are spectating
  let _spectatorViewingIdx = null; // player index whose board we're viewing

  function isSpectating() { return !!_spectatorToken; }

  function _specBuildStateUrl() {
    if (!_spectatorRoomId || !_spectatorToken) return null;
    return apiUrl(`/api/rooms/${_spectatorRoomId}/state?spectator_token=${encodeURIComponent(_spectatorToken)}`);
  }

  async function joinAsSpectator(rid) {
    const name = (window.__fishNickname && window.__fishNickname()) || "Spectator";
    const r = await apiPost(`/api/rooms/${rid}/spectate`, { name }, { timeoutMs: 10000 });
    if (!r.ok) { showToast((r.data && r.data.error) || "Cannot spectate this game.", "err"); return; }
    _spectatorToken = r.data.spectator_token;
    _spectatorRoomId = rid;
    roomId = rid;
    _spectatorViewingIdx = null;
    // Switch presence in Firestore
    _specSetPresence(rid);
    // Show game UI in spectator mode
    const statsLobby = document.getElementById("auth-stats-lobby");
    if (statsLobby) statsLobby.classList.remove("visible");
    const _galEl = document.getElementById("avatar-gallery");
    if (_galEl) _galEl.classList.remove("open");
    if (window.__fishExitGalleryViewOnly) window.__fishExitGalleryViewOnly();
    document.getElementById("pv-game").style.display = "flex";
    document.getElementById("pv-room-id-badge").textContent = rid + " 👁";
    _specShowPanel(true);
    startPolling();
    startThemeSong();
    showToast("Joined as spectator. Click a player's avatar to view their board.", "ok");
  }

  async function leaveSpectator() {
    if (!_spectatorToken || !_spectatorRoomId) return;
    await apiPost(`/api/rooms/${_spectatorRoomId}/spectate_leave`, { spectator_token: _spectatorToken }, { timeoutMs: 5000 }).catch(() => {});
    _spectatorToken = "";
    _spectatorRoomId = "";
    _spectatorViewingIdx = null;
    roomId = null;
    _specShowPanel(false);
    _specSetPresence(null);
    try { window._igcpSetVisible?.(false); } catch {}
    try { window._bsSetVisible?.(false); } catch {}
    document.getElementById("pv-game").style.display = "none";
    stopThemeSong();
    if (typeof window.__fishShowStatsLobby === "function") window.__fishShowStatsLobby();
  }

  function _specShowPanel(active) {
    const panel = document.getElementById("pv-spectator-panel");
    const handZone = document.getElementById("pv-hand-zone");
    const handCards = document.getElementById("pv-hand");   // the cards ONLY (not the seats)
    const guideBar = document.getElementById("pv-guide-bar");
    const actionBar = document.getElementById("pv-action-bar");
    if (active) {
      if (panel) panel.classList.add("active");
      // IMPORTANT: the player seat avatars (#pv-seats-left / #pv-seats-right)
      // live INSIDE #pv-hand-zone. Hiding the whole zone (the old behaviour)
      // also hid the avatars, so a spectator had nothing to click. Instead,
      // keep the zone visible and hide only the spectator's own hand cards.
      if (handZone) handZone.style.display = "";
      if (handCards) handCards.style.display = "none";
      if (guideBar) guideBar.style.display = "none";
      if (actionBar) actionBar.style.display = "none";
    } else {
      if (panel) panel.classList.remove("active");
      if (handZone) handZone.style.display = "";
      if (handCards) handCards.style.display = "";
      if (guideBar) guideBar.style.display = "";
      if (actionBar) actionBar.style.display = "";
      const lbl = document.getElementById("spec-viewing-label");
      if (lbl) { lbl.style.display = "none"; lbl.textContent = ""; }
    }
  }

  function _specSetPresence(rid) {
    // Write current_room_id to Firestore so friends can see "In Game".
    try {
      const db = window.__fishDb && window.__fishDb();
      const user = window.__fishAuthUser && window.__fishAuthUser();
      if (db && user) {
        db.collection("users").doc(user.uid).update({ current_room_id: rid || null }).catch(() => {});
      }
    } catch {}
  }

  function _specRenderSpectatorList(spectators) {
    const wrap = document.getElementById("pv-spectator-list");
    const rows = document.getElementById("spec-list-rows");
    if (!wrap || !rows) return;
    if (!spectators || !spectators.length) { wrap.classList.remove("visible"); return; }
    wrap.classList.add("visible");
    rows.innerHTML = "";
    spectators.forEach(s => {
      const row = document.createElement("div");
      row.className = "spec-list-row";
      const nameEl = document.createElement("span");
      nameEl.className = "spec-name";
      nameEl.textContent = s.name;
      row.appendChild(nameEl);
      if (s.kick_votes > 0) {
        const prog = document.createElement("span");
        prog.className = "spec-kick-progress";
        prog.textContent = `${s.kick_votes}/${s.kick_needed} votes`;
        row.appendChild(prog);
      }
      if (!isSpectating()) {
        // Active players see the kick button
        const kickBtn = document.createElement("button");
        kickBtn.className = "spec-kick-btn";
        kickBtn.textContent = "Kick";
        kickBtn.addEventListener("click", async () => {
          kickBtn.disabled = true;
          const seatTok = getSeatToken();
          if (!seatTok || !roomId) return;
          // We store token_tail on each entry; client needs the full token from the server payload
          // Use name to find via payload — we'll store the full token in data attribute
          const specTok = kickBtn.dataset.specToken;
          if (!specTok) return;
          const r = await apiPost(`/api/rooms/${roomId}/kick_spectator`, { seat_token: seatTok, spectator_token: specTok }, { timeoutMs: 8000 });
          if (r && r.data && r.data.kicked) showToast(`${r.data.name} was removed.`, "ok");
          else if (r && r.data) showToast(`Vote recorded: ${r.data.votes}/${r.data.needed} needed.`, "ok");
          kickBtn.disabled = false;
        });
        kickBtn.dataset.specToken = s._token || "";
        row.appendChild(kickBtn);
      }
      rows.appendChild(row);
    });
  }

  // Scan localStorage for the most recent still-valid rejoin token across rooms.
  function findPendingRejoin() {
    let best = null;
    try {
      for (let i = 0; i < localStorage.length; i++) {
        const k = localStorage.key(i);
        if (!k || k.indexOf("fish_rejoin_") !== 0) continue;
        const rid = k.slice("fish_rejoin_".length);
        const raw = localStorage.getItem(k);
        if (!raw) continue;
        let obj; try { obj = JSON.parse(raw); } catch { continue; }
        if (!obj || !obj.token || !obj.savedAt) continue;
        if (Date.now() - obj.savedAt > REJOIN_WINDOW_MS) { try { localStorage.removeItem(k); } catch {} continue; }
        if (!best || obj.savedAt > best.savedAt) best = { roomId: rid, savedAt: obj.savedAt };
      }
    } catch {}
    return best;
  }
  function _refreshRejoinButton() { /* replaced by in-list rejoin card */ }

  function enterRoom(id) {
    // Entering any room ends an in-progress Quick Match search.
    try { if (typeof cancelQuickMatch === "function") cancelQuickMatch(true); } catch (_) {}
    roomId = id;
    document.getElementById("pv-room-id-badge").textContent = id;
    document.getElementById("pv-lobby").style.display = "none";
    // Hide stats lobby if it's showing
    const statsLobby = document.getElementById("auth-stats-lobby");
    if (statsLobby) statsLobby.classList.remove("visible");
    const _galEl = document.getElementById("avatar-gallery");
    if (_galEl) _galEl.classList.remove("open");
    if (window.__fishExitGalleryViewOnly) window.__fishExitGalleryViewOnly();
    document.getElementById("pv-game").style.display = "flex";
    startSSE();
    startPolling();
    startThemeSong();
    // Write current_room_id to Firestore presence
    _specSetPresence(id);
    // play_again_endgame: previous game ended with End Game card seen,
    // and now I'm entering a new game → fire the daily challenge.
    try {
      if (localStorage.getItem("cc_play_again_pending") === "1") {
        localStorage.removeItem("cc_play_again_pending");
        if (typeof window._reportDailyChallengeProgress === "function") {
          window._reportDailyChallengeProgress("play_again_endgame", 0, { complete: true });
        }
      }
    } catch {}
  }

  // ── Lobby create / join ────────────────────────────────────────

  // ── Waiting room overlay helpers ──────────────────────────────
  // Coral state is applied as a CSS class — the full button background
  // (coral + decorations) is loaded via the corresponding image.

  function showWaitingRoom(code, isHost, visibility, isQuickPlay) {
    const vis = visibility || _myRoomVisibility || "public";
    const codeEl = document.getElementById("wr-code-display");
    const copyEl = document.getElementById("wr-copy-btn");
    const chatEl = document.getElementById("wr-chat-btn");
    const subEl  = document.getElementById("wr-subtitle");
    if (chatEl) chatEl.style.display = isQuickPlay ? "inline-flex" : "none";
    document.getElementById("wr-title").textContent = isQuickPlay
      ? "Quick Play Lobby"
      : (isHost ? "Room Created!" : "Game Lobby");
    if (isQuickPlay) {
      if (codeEl) codeEl.style.display = "none";
      if (copyEl) copyEl.style.display = "none";
      if (subEl) subEl.textContent = isHost
        ? "Choose the player setup, chat with the table, and start when your selected human spots are filled."
        : "The host is choosing the player setup. Chat while the rest of the table fills.";
    } else if (compMode) {
      // Competitive: always show the room code so P2 can join by entering it.
      if (codeEl) { codeEl.style.display = ""; codeEl.textContent = code; }
      if (copyEl) copyEl.style.display = "";
      if (subEl)  subEl.textContent = "Share this code with your opponent to join:";
    } else if (vis === "private") {
      if (codeEl) { codeEl.style.display = ""; codeEl.textContent = code; }
      if (copyEl) copyEl.style.display = "";
      if (subEl)  subEl.textContent = "Share this code with your crew (it's also the password):";
    } else {
      if (codeEl) codeEl.style.display = "none";
      if (copyEl) copyEl.style.display = "";
      if (subEl)  subEl.textContent = "Your crew can join from the Public games list.";
    }
    document.getElementById("pv-waiting-room").classList.add("open");
  }
  function hideWaitingRoom() {
    document.getElementById("pv-waiting-room").classList.remove("open");
    try { _closeSwapPopup(); } catch (_) {}
  }
  // Three difficulty pills (Easy/Medium/Hard) shown next to AI bot seats in
  // the lobby. Only the host can click them; non-hosts see them as static.
  function buildDifficultyBox(seat, isHost) {
    const box = document.createElement("div");
    box.className = "wr-diff-box";
    const current = String(seat.difficulty || "medium").toLowerCase();
    [
      { id: "easy",   label: "Easy"   },
      { id: "medium", label: "Medium" },
      { id: "hard",   label: "Hard"   },
    ].forEach(opt => {
      const btn = document.createElement("button");
      btn.type = "button";
      btn.className = `wr-diff-pill wr-diff-${opt.id}` + (current === opt.id ? " active" : "");
      btn.textContent = opt.label;
      btn.disabled = !isHost;
      if (isHost) {
        btn.title = `Set ${seat.claimed_name || ("Seat " + (seat.index + 1))} to ${opt.label}`;
        btn.addEventListener("click", async () => {
          if (current === opt.id) return;
          await setBotDifficulty(seat.index, opt.id, btn);
        });
      } else {
        btn.title = `${opt.label}${current === opt.id ? " (selected)" : ""}`;
      }
      box.appendChild(btn);
    });
    return box;
  }

  async function setBotDifficulty(seatIndex, difficulty, originBtn) {
    if (!roomId) return;
    // Optimistic UI: mark selected pill immediately so the host gets instant feedback,
    // then sync via the next state poll if the server rejects it.
    const wrap = originBtn?.parentElement;
    if (wrap) {
      wrap.querySelectorAll(".wr-diff-pill").forEach(b => b.classList.remove("active"));
      originBtn.classList.add("active");
    }
    try {
      const hostToken = getHostToken();
      const seatToken = getSeatToken();
      const payload = { seat_index: seatIndex, difficulty };
      if (hostToken) payload.host_token = hostToken;
      if (seatToken) payload.seat_token = seatToken;
      const r = await apiPost(`/api/rooms/${roomId}/seat_difficulty`, payload, { timeoutMs: 6000 });
      if (!r.ok) {
        const msg = r.data?.error || ("HTTP " + r.status);
        showToast("Failed to set difficulty: " + msg, "err");
      }
    } catch (e) {
      showToast("Network error setting difficulty.", "err");
    }
  }

  let _wrSeatSetupBusy = false;
  function updateQuickPlaySetup(seats, isHost, isQuickPlay) {
    const setup = document.getElementById("wr-quick-setup");
    if (!setup) return;
    setup.style.display = isQuickPlay ? "" : "none";
    if (!isQuickPlay) return;
    const safeSeats = Array.isArray(seats) ? seats : [];
    const humanCount = safeSeats.filter(seat => seat.kind === "human").length;
    const filledHumans = safeSeats.filter(
      seat => seat.kind === "human" && seat.claimed_name
    ).length;
    setup.querySelectorAll(".wr-human-option").forEach(button => {
      const target = Number(button.dataset.humanPlayers || 0);
      button.classList.toggle("active", target === humanCount);
      button.disabled = _wrSeatSetupBusy || !isHost || target < filledHumans;
      if (target < filledHumans) {
        button.title = `${filledHumans} human players are already in this lobby`;
      } else if (!isHost) {
        button.title = "Only the host can change the player setup";
      } else {
        button.title = `Set this lobby to ${target} human players`;
      }
    });
    const note = document.getElementById("wr-quick-note");
    if (note) {
      note.textContent = isHost
        ? `${filledHumans} joined • Choose 2–4 human spots. Every remaining spot becomes a bot.`
        : `${filledHumans} joined • The host selected ${humanCount} human spot${humanCount === 1 ? "" : "s"}.`;
    }
  }

  async function setQuickPlayHumanSlots(humanPlayers) {
    if (!roomId || _wrSeatSetupBusy) return;
    const currentHumanCount = (latestPayload?.seats || []).filter(
      seat => seat.kind === "human"
    ).length;
    if (currentHumanCount === humanPlayers) return;
    _wrSeatSetupBusy = true;
    updateQuickPlaySetup(latestPayload?.seats || [], true, true);
    try {
      const res = await apiPost(`/api/rooms/${roomId}/quickplay_seats`, {
        host_token: getHostToken(),
        seat_token: getSeatToken(),
        human_players: humanPlayers,
      }, { timeoutMs: 7000 });
      if (!res.ok || !res.data?.ok) {
        showToast(res.data?.error || "Could not update the player setup.", "err");
      }
      await refreshState();
    } catch (_) {
      showToast("Network error updating the player setup.", "err");
    } finally {
      _wrSeatSetupBusy = false;
      updateQuickPlaySetup(
        latestPayload?.seats || [],
        Boolean(latestPayload?.viewer?.is_host || getHostToken()),
        Boolean(latestPayload?.room?.quick_play)
      );
    }
  }

  document.querySelectorAll(".wr-human-option").forEach(button => {
    button.addEventListener("click", () => {
      setQuickPlayHumanSlots(Number(button.dataset.humanPlayers || 0));
    });
  });

  // ── Team Mode (lobby) ──────────────────────────────────────────
  const TEAM_META = [
    { key: "red",    name: "Red",    hex: "#e0463c" },
    { key: "blue",   name: "Blue",   hex: "#3d7be0" },
    { key: "green",  name: "Green",  hex: "#3fb26b" },
    { key: "yellow", name: "Yellow", hex: "#e6b32e" },
  ];
  function teamName(t) { return (TEAM_META[t] && TEAM_META[t].name) || ("Team " + (Number(t) + 1)); }
  function teamHex(t)  { return (TEAM_META[t] && TEAM_META[t].hex)  || "#888"; }

  async function _teamSwitch(team) {
    if (!roomId) return;
    const r = await apiPost(`/api/rooms/${roomId}/team`, { seat_token: getSeatToken(), team }, { timeoutMs: 8000 });
    if (!r.ok) showToast(r.data?.error || "Could not switch teams", "err");
    refreshState();
  }
  async function _teamSwapRequest(targetSeat, targetName) {
    if (!roomId) return;
    const r = await apiPost(`/api/rooms/${roomId}/swap`,
      { seat_token: getSeatToken(), action: "request", target_seat: targetSeat }, { timeoutMs: 8000 });
    if (!r.ok) { showToast(r.data?.error || "Could not send swap request", "err"); return; }
    showToast(`Swap request sent to ${targetName}`, "info");
    refreshState();
  }

  // Render the team-columns lobby into the players list. Clicking a team header
  // or its "＋ Join" button moves MY seat to that team (self-service). Clicking
  // another human on a DIFFERENT team asks them to swap.
  function renderTeamLobbyInto(list, seats, teamCount, mySeatIndex) {
    list.innerHTML = '<div class="wr-players-title">Teams — tap a team to join, tap a player to ask for a swap</div>';
    seats = Array.isArray(seats) ? seats : [];
    const mySeat = seats.find(s => s.index === mySeatIndex) || null;
    const myTeam = mySeat ? mySeat.team : null;
    const iAmHuman = !!mySeat && mySeat.kind === "human";
    const wrap = document.createElement("div");
    wrap.className = "wr-teams cols-" + teamCount;
    for (let t = 0; t < teamCount; t++) {
      const col = document.createElement("div");
      col.className = "wr-team-col team-" + ((TEAM_META[t] && TEAM_META[t].key) || t);
      col.style.setProperty("--team-hex", teamHex(t));
      const members = seats.filter(s => s.team === t).sort((a, b) => a.index - b.index);
      const activeCount = members.filter(s => s.kind === "ai" || s.claimed_name).length;

      const head = document.createElement("button");
      head.className = "wr-team-head" + (myTeam === t ? " is-mine" : "");
      head.innerHTML = `<span class="wr-team-name">${teamName(t)}</span><span class="wr-team-count">${activeCount}</span>`;
      const canJoin = iAmHuman && myTeam !== t;
      head.disabled = !canJoin;
      if (canJoin) head.title = `Join the ${teamName(t)} team`;
      head.addEventListener("click", () => { if (canJoin) _teamSwitch(t); });
      col.appendChild(head);

      members.forEach(s => {
        const isAI = s.kind === "ai";
        const isOpen = !isAI && !s.claimed_name;
        const isMe = s.index === mySeatIndex;
        const chip = document.createElement("div");
        chip.className = "wr-team-chip"
          + (isMe ? " is-me" : "") + (isAI ? " is-ai" : "") + (isOpen ? " is-open" : "");
        const label = isAI ? (s.claimed_name || `Bot ${s.index + 1}`)
                    : isOpen ? "Open"
                    : (s.claimed_name + (isMe ? " (You)" : ""));
        chip.innerHTML = `<span class="wr-chip-dot"></span><span class="wr-chip-name">${_hesc(label)}</span>`;
        const canSwap = iAmHuman && !isMe && !isAI && !isOpen && s.team !== myTeam;
        if (canSwap) {
          chip.classList.add("can-swap");
          chip.title = `Ask ${s.claimed_name} to swap teams`;
          chip.addEventListener("click", () => _teamSwapRequest(s.index, s.claimed_name));
        }
        col.appendChild(chip);
      });

      if (canJoin) {
        const join = document.createElement("button");
        join.className = "wr-team-join";
        join.textContent = "＋ Join";
        join.addEventListener("click", () => _teamSwitch(t));
        col.appendChild(join);
      }
      wrap.appendChild(col);
    }
    list.appendChild(wrap);
  }

  // ── Incoming swap-request popup ────────────────────────────────
  // Shown on the TARGET's screen when another player asks to swap teams.
  let _swapPopupFromSeat = null; // from_seat currently shown (dedupe across polls)
  function _closeSwapPopup() {
    const el = document.getElementById("wr-swap-popup");
    if (el) el.classList.remove("open");
    _swapPopupFromSeat = null;
  }
  function _buildSwapPopup() {
    let el = document.getElementById("wr-swap-popup");
    if (el) return el;
    el = document.createElement("div");
    el.id = "wr-swap-popup";
    el.innerHTML =
      '<div class="wr-swap-box">' +
      '<div class="wr-swap-msg" id="wr-swap-msg"></div>' +
      '<div class="wr-swap-btns">' +
      '<button class="wr-swap-decline" id="wr-swap-decline">Decline</button>' +
      '<button class="wr-swap-accept" id="wr-swap-accept">Swap!</button>' +
      '</div></div>';
    document.body.appendChild(el);
    return el;
  }
  async function _respondSwap(action) {
    const fromSeat = _swapPopupFromSeat;
    // Hide the popup but KEEP _swapPopupFromSeat set: a poll can fire before the
    // server clears the request, and _syncIncomingSwap would otherwise re-show
    // this same offer. The tracker is fully reset once the request disappears.
    const el = document.getElementById("wr-swap-popup");
    if (el) el.classList.remove("open");
    if (!roomId || fromSeat == null) return;
    const r = await apiPost(`/api/rooms/${roomId}/swap`,
      { seat_token: getSeatToken(), action, from_seat: fromSeat }, { timeoutMs: 8000 });
    if (!r.ok && action === "accept") showToast(r.data?.error || "Swap failed", "err");
    refreshState();
  }
  // Called each poll while the team lobby is up: show/refresh/close the popup
  // based on whether a pending request targets MY seat.
  function _syncIncomingSwap(swapRequests, mySeatIndex) {
    const reqs = Array.isArray(swapRequests) ? swapRequests : [];
    const mine = (mySeatIndex == null) ? null : reqs.find(r => r && r.to_seat === mySeatIndex);
    if (!mine) { if (_swapPopupFromSeat != null) _closeSwapPopup(); return; }
    if (_swapPopupFromSeat === mine.from_seat) return; // already showing OR just acted on this one
    _swapPopupFromSeat = mine.from_seat;
    const el = _buildSwapPopup();
    const color = teamName(mine.from_team);
    document.getElementById("wr-swap-msg").innerHTML =
      `<strong>${_hesc(mine.from_name || "A player")}</strong> wants to swap teams with you.` +
      `<br>Accept to move to the <span class="wr-swap-team" style="color:${teamHex(mine.from_team)}">${_hesc(color)}</span> team.`;
    document.getElementById("wr-swap-accept").onclick = () => _respondSwap("accept");
    document.getElementById("wr-swap-decline").onclick = () => _respondSwap("decline");
    el.classList.add("open");
  }

  function updateWaitingRoom(seats, canStart, startFn, isHost, isCompetitive, isQuickPlay) {
    // A room is competitive ONLY if it was explicitly created that way. The
    // authoritative signal is the server's room.competitive flag (passed in as
    // isCompetitive); compMode is the local mirror of that for this client.
    // Never infer "competitive" from seat composition — a normal 4-player game
    // with 0 AI is all-human too, and must stay a normal game.
    const isComp = !!isCompetitive;
    const _room = (latestPayload && latestPayload.room) || {};
    const isTeam = !!_room.team_mode;
    const teamCount = Math.max(2, Math.min(4, Number(_room.team_count) || 2));
    const mySeatIndex = (latestPayload && latestPayload.viewer && typeof latestPayload.viewer.seat_index === "number")
      ? latestPayload.viewer.seat_index : null;
    document.getElementById("wr-title").textContent = isQuickPlay
      ? "Quick Play Lobby"
      : (isHost
          ? (isComp ? "⚔️ Competitive Room Created!" : (isTeam ? "🤝 Team Room Created!" : "Room Created!"))
          : (isComp ? "⚔️ Competitive Lobby" : (isTeam ? "🤝 Team Lobby" : "Game Lobby")));

    const list = document.getElementById("wr-players-list");
    list.innerHTML = '<div class="wr-players-title">Players in Room</div>';
    updateQuickPlaySetup(seats, isHost, isQuickPlay);

    if (isTeam) {
      renderTeamLobbyInto(list, seats, teamCount, mySeatIndex);
      _syncIncomingSwap(_room.swap_requests, mySeatIndex);
    } else if (isComp && seats && seats.length === 4) {
      // Show as two grouped players instead of four individual seats.
      const groups = [
        { label: "Player 1", seats: seats.filter(s => s.index < 2) },
        { label: "Player 2", seats: seats.filter(s => s.index >= 2) },
      ];
      groups.forEach(({ label, seats: gs }) => {
        const row = document.createElement("div"); row.className = "wr-player-row";
        const dot = document.createElement("div");
        const anyJoined = gs.some(s => s.claimed_name);
        dot.className = "wr-seat-dot" + (anyJoined ? " filled" : " empty");
        const nm = document.createElement("span");
        if (anyJoined) {
          const firstName = gs.find(s => s.claimed_name)?.claimed_name?.replace(/ 2$/, "") || label;
          nm.className = "wr-player-name";
          nm.textContent = `${label}: ${firstName} (2 hands)`;
        } else {
          nm.className = "wr-player-empty";
          nm.textContent = `${label}: Waiting to join…`;
        }
        row.appendChild(dot); row.appendChild(nm);
        list.appendChild(row);
      });
    } else {
      // Normal (non-competitive) seat list.
      (seats||[]).forEach(s => {
        const row = document.createElement("div"); row.className = "wr-player-row";
        const dot = document.createElement("div");
        dot.className = "wr-seat-dot" + (s.claimed_name ? " filled" : " empty");
        const nm = document.createElement("span");
        const isAI = (s.kind === "ai");
        if (isAI) {
          row.classList.add("wr-ai-row");
          nm.className = "wr-player-name wr-ai-name";
          nm.textContent = s.claimed_name || `Bot ${s.index}`;
        } else if (s.claimed_name) {
          nm.className = "wr-player-name";
          nm.textContent = `Seat ${s.index+1}: ${s.claimed_name}`;
        } else {
          nm.className = "wr-player-empty";
          nm.textContent = `Seat ${s.index+1}: Open`;
        }
        row.appendChild(dot); row.appendChild(nm);
        if (isAI) row.appendChild(buildDifficultyBox(s, isHost));
        list.appendChild(row);
      });
    }

    // Only humans count toward "(X of Y joined)" — bots auto-fill instantly.
    const humanSeats = (seats||[]).filter(s => s.kind === "human");
    const filled = humanSeats.filter(s => s.claimed_name).length;
    const total  = humanSeats.length;
    const btn = document.getElementById("wr-start-btn");
    const text = document.getElementById("wr-btn-text");
    btn.onclick = null;
    btn.classList.remove("coral-red", "coral-orange", "coral-yellow");
    text.className = "wr-btn-text";

    if (canStart && isHost) {
      // State 3: host in full room
      btn.disabled = false;
      btn.classList.add("coral-yellow");
      text.textContent = "Start Game";
      text.classList.add("with-play");
      btn.onclick = startFn;
    } else if (canStart) {
      // State 2: non-host in full room
      btn.disabled = true;
      btn.classList.add("coral-orange");
      text.textContent = "Waiting for host to start";
    } else {
      // State 1: still waiting for players
      btn.disabled = true;
      btn.classList.add("coral-red");
      text.textContent = total > 1
        ? `Waiting for players... (${filled} of ${total} joined)`
        : `Waiting for players...`;
    }
  }

  document.getElementById("wr-copy-btn").addEventListener("click", () => {
    // Always build the invite link from the real room id (works for public
    // rooms whose code is hidden, and private rooms where code === room id).
    const code = roomId || document.getElementById("wr-code-display").textContent;
    const link = `${location.origin}/play/${code}`;
    navigator.clipboard?.writeText(link).catch(()=>{});
    const btn = document.getElementById("wr-copy-btn");
    btn.innerHTML = '<span class="wr-copy-icon">✓</span><span>Link Copied!</span>';
    setTimeout(() => {
      btn.innerHTML = '<span class="wr-copy-icon">📋</span><span>Copy Invite Link</span>';
    }, 2000);
  });
  document.getElementById("wr-code-display").addEventListener("click", () => {
    document.getElementById("wr-copy-btn").click();
  });

  document.getElementById("pv-create-btn").addEventListener("click", async () => {
    if (window.__fishSyncNickname) window.__fishSyncNickname();
    const name = (window.__fishNickname && window.__fishNickname()) ||
                 document.getElementById("pv-host-name").value.trim() || "Host";
    let rid = normalizeRoomId(document.getElementById("pv-room-code-new").value.trim() ||
      Math.random().toString(36).slice(2,7).toUpperCase());
    if (!rid) rid = Math.random().toString(36).slice(2,7).toUpperCase().slice(0,5);
    const total = Number(document.getElementById("pv-total-players").value)||2;
    const ai    = Number(document.getElementById("pv-ai-players").value)||0;
    const createKey = `ck_${Date.now()}_${Math.random().toString(36).slice(2,8)}`;
    try { localStorage.setItem(createKeyKey(), createKey); } catch {}
    const createBtn = document.getElementById("pv-create-btn");
    createBtn.disabled = true;
    lobbyStatus("Generating Current…", false);
    const visibility = document.getElementById("pv-visibility").value;
    let password = "";
    if (visibility === "private") {
      const rawPw = document.getElementById("pv-room-password").value.trim();
      if (!rawPw) {
        lobbyStatus("Enter a code for the private Current.", true);
        createBtn.disabled = false; return;
      }
      // The private code IS both the join code and the password.
      const code = normalizeRoomCode(rawPw);
      if (!code) {
        lobbyStatus("Code must be 4–12 letters or numbers (no spaces or symbols).", true);
        createBtn.disabled = false; return;
      }
      rid = code;
      password = code;
    }
    _myRoomVisibility = visibility;
    _myRoomCode = password; // empty for public
    let r;
    try {
      r = await apiPost("/api/rooms", {
        create_key: createKey, host_name: name, room_id: rid,
        total_players: total, human_players: total - ai, ai_players: ai,
        replace_active: false, visibility, password,
      }, { timeoutMs:10000 });
    } catch (e) {
      createBtn.disabled = false;
      ccReport("room_create_failed", {
        source: "lobby",
        visibility,
        total,
        ai,
        error: e && (e.name || e.message || e)
      }, "error");
      lobbyStatus("Create failed — check your connection and try again.", true);
      showToast("Create failed — check your connection.", "err");
      return;
    }
    createBtn.disabled = false;
    if (!r.ok) {
      ccReport("room_create_failed", {
        source: "lobby",
        visibility,
        total,
        ai,
        status: r.status,
        error: r.data?.error || ""
      }, "warn");
      if (r.status === 503 || r.status === 502) {
        lobbyStatus("Server is warming up — please wait ~30 s and try again.", true);
        showToast("Server is warming up — try again in ~30 s", "warn");
        return;
      }
      const activeId = normalizeRoomId(r.data?.active_room_id || "");
      if (activeId) {
        // A room is already active — guide user to join it; do NOT auto-replace
        lobbyStatus(`A room (${activeId}) is already open — force-replace it or close it from another device first.`, false);
        // Show a one-time "Force replace" link next to the status
        const statusEl = document.getElementById("pv-home-status");
        if (statusEl && !statusEl.querySelector(".force-replace-btn")) {
          const forceBtn = document.createElement("button");
          forceBtn.className = "pv-btn sm force-replace-btn";
          forceBtn.style.cssText = "margin-top:6px;background:var(--red);border-color:var(--red);font-size:11px;padding:4px 10px;";
          forceBtn.textContent = "⚠ Force replace that room (lose all progress)";
          forceBtn.addEventListener("click", async () => {
            forceBtn.remove();
            lobbyStatus("Replacing room…", false);
            let r2;
            try {
              r2 = await apiPost("/api/rooms", {
                create_key: createKey, host_name: name, room_id: rid,
                total_players: total, human_players: total - ai, ai_players: ai,
                replace_active: true,
              }, { timeoutMs:10000 });
            } catch (e) {
              ccReport("room_create_failed", {
                source: "lobby_force_replace",
                visibility,
                total,
                ai,
                error: e && (e.name || e.message || e)
              }, "error");
              lobbyStatus("Create failed — check your connection and try again.", true);
              showToast("Create failed — check your connection.", "err");
              return;
            }
            if (!r2.ok) {
              ccReport("room_create_failed", {
                source: "lobby_force_replace",
                visibility,
                total,
                ai,
                status: r2.status,
                error: r2.data?.error || ""
              }, "warn");
              lobbyStatus("Create failed: " + (r2.data?.error||r2.status), true); return;
            }
            const rId2 = normalizeRoomId(r2.data?.room_id || rid);
            roomId = rId2;
            if (r2.data?.host_token) setHostToken(r2.data.host_token);
            if (r2.data?.seat_token) setSeatToken(r2.data.seat_token);
            document.getElementById("pv-my-name-badge").textContent = name;
            enterRoom(rId2);
            showWaitingRoom(rId2, true);
          });
          statusEl.appendChild(forceBtn);
        }
      } else {
        lobbyStatus("Create failed: " + (r.data?.error||r.status), true);
      }
      return;
    }
    // room_id is at top level of response; host seat is auto-claimed on creation
    const rId = normalizeRoomId(r.data?.room_id || rid);
    roomId = rId;
    const hToken = r.data?.host_token || "";
    if (hToken) setHostToken(hToken);
    // Server auto-claims seat 0 for host and returns seat_token — use it directly
    const sToken = r.data?.seat_token || "";
    if (sToken) setSeatToken(sToken);
    document.getElementById("pv-my-name-badge").textContent = name;
    enterRoom(rId);
    showWaitingRoom(rId, true);
  });

  // ── Seat picker logic ──────────────────────────────────────────
  // Two independent seat grids: "invited" view (link arrival) and "home" view (manual join)
  let _selectedSeat = null;       // invited view
  let _selectedSeatHome = null;   // home view

  function lobbyStatus(msg, isErr) {
    // update both status divs (one per view); only the visible one matters
    ["pv-lobby-status", "pv-home-status"].forEach(id => {
      const el = document.getElementById(id);
      if (el) { el.textContent = msg; el.style.color = isErr ? "var(--red)" : "var(--muted)"; }
    });
  }

  // seatObjs: array of {index, label, kind, claimed_name}
  function buildSeatGrid(gridEl, joinBtnEl, seatObjs, onSelect) {
    gridEl.innerHTML = "";
    for (const seat of seatObjs) {
      const isTaken = Boolean(seat.claimed_name);
      const btn = document.createElement("button");
      btn.className = "seat-btn" + (isTaken ? " taken" : "");
      btn.disabled = isTaken;
      btn.innerHTML = `<span class="seat-num">${seat.index + 1}</span><span class="seat-label">${isTaken ? (seat.claimed_name || "Taken") : "Open"}</span>`;
      btn.addEventListener("click", () => {
        gridEl.querySelectorAll(".seat-btn").forEach(b => b.classList.remove("selected"));
        btn.classList.add("selected");
        joinBtnEl.disabled = false;
        const _spTxt = document.getElementById("sp-join-text"); if (_spTxt) _spTxt.textContent = `Join as Seat ${seat.index + 1} →`;
        onSelect(seat.index);
      });
      gridEl.appendChild(btn);
    }
  }

  async function fetchSeats(rid) {
    // returns { seatObjs, mode } or null on error
    // Response shape: { ok, room: { total_players, mode, ... }, seats: [{index, kind, claimed_name, ...}], ... }
    const res = await apiFetch(`/api/rooms/${rid}/state`, { method:"GET", timeoutMs:8000 });
    if (!res.ok) return null;
    const allSeats = Array.isArray(res.data?.seats) ? res.data.seats : [];
    // Only offer human seats in the picker; AI seats can't be joined
    const seatObjs = allSeats.filter(s => s.kind === "human");
    if (seatObjs.length === 0) return null;
    const isComp = Boolean(res.data?.room?.competitive) || (res.data?.room?.mode === "competitive");
    return { seatObjs, mode: isComp ? "competitive" : "" };
  }

  // Redirect to competitive join overlay, pre-filling the room code
  function _openCompJoinOverlay(rid) {
    compOpenOverlay();
    compSwitchTab("join");
    const codeEl = document.getElementById("comp-join-code");
    if (codeEl) codeEl.value = normalizeRoomId(rid || "").toUpperCase();
    compSetStatus("", false);
  }

  async function doJoin(rid, name, seat, joinBtn) {
    if (joinBtn) { joinBtn.disabled = true; const _t0 = document.getElementById("sp-join-text"); if (_t0) _t0.textContent = "Joining…"; }
    roomId = rid;
    try {
      // For private rooms the code IS the password, so pass the room code as the
      // password — harmless for public rooms (no password gate), and lets people
      // join a private room just by typing its code.
      const j = await apiPost(`/api/rooms/${rid}/join`, { player_name: name, seat_index: seat, password: rid }, { timeoutMs:12000 });
      if (!j.ok) {
        const is503 = j.status === 503 || j.status === 502;
        const msg = is503
          ? "Server is warming up — please wait ~30 s and try again."
          : "Join failed: " + (j.data?.error || j.status);
        lobbyStatus(msg, true);
        showToast(msg, is503 ? "warn" : "err");
        roomId = null;
        if (joinBtn) { joinBtn.disabled = false; const _t1 = document.getElementById("sp-join-text"); if (_t1) _t1.textContent = `Join as Seat ${seat + 1} →`; }
        return;
      }
      if (j.data?.seat_token) setSeatToken(j.data.seat_token);
      document.getElementById("pv-my-name-badge").textContent = name;
      showToast("Joined! Waiting for host to start…", "ok");
      enterRoom(rid);
    } catch (e) {
      const msg = "Connection error — check your internet.";
      lobbyStatus(msg, true);
      showToast(msg, "err");
      roomId = null;
      if (joinBtn) { joinBtn.disabled = false; const _t2 = document.getElementById("sp-join-text"); if (_t2) _t2.textContent = `Join as Seat ${seat + 1} →`; }
    }
  }

  // Join a room by dropping the player straight into the first OPEN seat — no
  // seat-picking step. Seat choice no longer matters: the server randomizes the
  // turn order every game, so which physical seat you land in has no effect on
  // when you play. For private rooms the room code doubles as the password, so
  // passing the code (password || rid) works for public and private alike.
  // Returns true on a successful join.
  async function autoJoinOpenSeat(rid, seatObjs, password) {
    const name = (window.__fishNickname && window.__fishNickname()) || "Player";
    const open = (Array.isArray(seatObjs) ? seatObjs : []).filter(s => !s.claimed_name);
    if (!open.length) { showToast("All seats are taken.", "err"); return false; }
    roomId = rid; // must be set before setSeatToken (which keys by roomId)
    try {
      const j = await apiPost(`/api/rooms/${rid}/join`,
        { player_name: name, seat_index: open[0].index, password: password || rid },
        { timeoutMs: 12000 });
      if (!j.ok) {
        const is503 = j.status === 503 || j.status === 502;
        const msg = is503
          ? "Server is warming up — please wait ~30 s and try again."
          : "Join failed: " + (j.data?.error || j.status);
        lobbyStatus(msg, true);
        showToast(msg, is503 ? "warn" : "err");
        roomId = null;
        return false;
      }
      if (j.data?.seat_token) setSeatToken(j.data.seat_token);
      document.getElementById("pv-my-name-badge").textContent = name;
      showToast("Joined! Waiting for host to start…", "ok");
      enterRoom(rid);
      return true;
    } catch (e) {
      const msg = "Connection error — check your internet.";
      lobbyStatus(msg, true);
      showToast(msg, "err");
      roomId = null;
      return false;
    }
  }

  // ── INVITED VIEW (arrived via share link) ──────────────────────
  async function loadInvitedSeats(rid) {
    const data = await fetchSeats(rid);
    if (!data) {
      showToast("Room not found — ask the host to re-share the invite link.", "err");
      return;
    }
    // Competitive rooms need two hands claimed together — route to the
    // dedicated competitive join overlay instead of a single-seat auto-join.
    if (data.mode === "competitive") { _openCompJoinOverlay(rid); return; }
    if (data.seatObjs.every(s => s.claimed_name)) {
      showToast("All seats are taken in this room.", "warn");
      return;
    }
    await autoJoinOpenSeat(rid, data.seatObjs, "");
  }

  document.getElementById("pv-join-btn").addEventListener("click", async () => {
    const btn  = document.getElementById("pv-join-btn");
    const rid  = normalizeRoomId(document.getElementById("pv-join-code").value.trim());
    const name = (window.__fishNickname && window.__fishNickname()) ||
                 document.getElementById("pv-join-name").value.trim() || "Player";
    if (!rid)  { lobbyStatus("Room code missing.", true); return; }
    if (_selectedSeat === null) { lobbyStatus("Pick a seat first.", true); return; }
    lobbyStatus("Joining…", false);
    await doJoin(rid, name, _selectedSeat, btn);
  });


  // ── Lobby Browser ──────────────────────────────────────────────
  let _lbRefreshTimer = null;
  let _lbActiveTab = "public";
  let _lbAllRooms  = [];
  let _lbPendingRoom = null; // room object awaiting password entry

  function openLobbyBrowser() {
    document.getElementById("lobby-browser-modal").classList.add("open");
    fetchAndRenderRooms();
    _lbRefreshTimer = setInterval(fetchAndRenderRooms, 8000);
  }

  function closeLobbyBrowser() {
    document.getElementById("lobby-browser-modal").classList.remove("open");
    if (_lbRefreshTimer) { clearInterval(_lbRefreshTimer); _lbRefreshTimer = null; }
    _lbPendingRoom = null;
    document.getElementById("lb-pw-prompt").classList.remove("open");
    document.getElementById("lb-pw-err").textContent = "";
    document.getElementById("lb-pw-input").value = "";
  }

  async function fetchAndRenderRooms() {
    try {
      const res = await apiFetch("/api/rooms", { method:"GET", timeoutMs:6000 });
      if (res.ok && Array.isArray(res.data?.rooms)) {
        _lbAllRooms = res.data.rooms;
      }
    } catch {}
    renderLobbyList();
  }

  function renderLobbyList() {
    const list = document.getElementById("lb-browser-list");
    if (!list) return;

    let rooms = _lbAllRooms;

    if (_lbActiveTab === "public") {
      rooms = rooms.filter(r => r.visibility === "public" && r.mode !== "competitive");
    } else if (_lbActiveTab === "private") {
      rooms = rooms.filter(r => r.visibility === "private" && r.mode !== "competitive");
    } else if (_lbActiveTab === "competitive") {
      rooms = rooms.filter(r => r.mode === "competitive");
    }

    list.innerHTML = "";

    // Prepend a "Rejoin →" card if this player has a reserved seat in a running game.
    const pending = findPendingRejoin();
    if (pending) {
      const rjCard = document.createElement("div");
      rjCard.className = "room-card room-card-rejoin";
      rjCard.innerHTML = `
        <div class="room-card-info">
          <div class="room-card-host">Your reserved seat</div>
          <div class="room-card-meta">Seat held · expires soon</div>
          <span class="room-badge" style="background:rgba(0,180,120,.18);color:#00d89a;border-color:rgba(0,200,130,.35);">🔄 In Progress</span>
        </div>
        <button class="room-card-join pv-btn" style="background:linear-gradient(135deg,#0b8a5c,#076644);border-color:#00c87a;">Rejoin →</button>`;
      rjCard.querySelector("button").addEventListener("click", () => {
        const tok = loadRejoinToken(pending.roomId);
        if (!tok) { try { showToast("Rejoin window expired.", "warn"); } catch {} renderLobbyList(); return; }
        closeLobbyBrowser();
        roomId = pending.roomId;
        setSeatToken(tok);
        try { showToast("Rejoining your game…", "ok"); } catch {}
        enterRoom(pending.roomId);
      });
      list.appendChild(rjCard);
    }

    if (!rooms.length) {
      const label = _lbActiveTab === "competitive" ? "No open competitive rooms right now." :
                    _lbActiveTab === "private" ? "No open private rooms right now." :
                    "No open public rooms right now.";
      if (!pending) list.innerHTML = `<div class="lb-browser-empty">${label}</div>`;
      else list.appendChild(Object.assign(document.createElement("div"), { className:"lb-browser-empty", textContent: label }));
      return;
    }

    for (const room of rooms) {
      const card = document.createElement("div");
      card.className = "room-card";

      const modeBadge = room.mode === "competitive"
        ? `<span class="room-badge competitive">⚔ Competitive</span>`
        : `<span class="room-badge">🌊 Casual</span>`;

      const lockIcon = room.has_password ? "🔒 " : "";
      const sizeLabel = `${room.filled}/${room.total_players} players`;
      const aiCount = (room.total_players - room.human_players);
      const aiLabel = aiCount > 0 ? ` · ${aiCount} AI` : "";

      card.innerHTML = `
        <div class="room-card-info">
          <div class="room-card-host">${lockIcon}${escHtml(room.host_name || "Unknown")}</div>
          <div class="room-card-meta">${sizeLabel}${aiLabel} · ${escHtml(room.created_ago || "")}</div>
          ${modeBadge}
        </div>
        <button class="room-card-join pv-btn gold" data-rid="${escHtml(room.room_id)}">Join →</button>`;

      card.querySelector(".room-card-join").addEventListener("click", () => lbJoinRoom(room));
      list.appendChild(card);
    }
  }

  // Set of friend nicknames (lowercase) for the friends tab filter
  const _lbFriendNicks = new Set();
  async function refreshFriendNicks() {
    const authUser = window.__fishAuthUser ? window.__fishAuthUser() : null;
    const db = window.__fishDb ? window.__fishDb() : null;
    if (!authUser || !db) return;
    try {
      const snap = await db.collection("users").doc(authUser.uid).get();
      const friends = snap.data()?.friends || [];
      _lbFriendNicks.clear();
      for (const f of friends) {
        if (f.nickname) _lbFriendNicks.add(f.nickname.toLowerCase());
      }
    } catch {}
  }

  function escHtml(s) {
    return String(s || "").replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;").replace(/"/g,"&quot;");
  }

  async function lbJoinRoom(room) {
    if (room.has_password) {
      _lbPendingRoom = room;
      document.getElementById("lb-pw-err").textContent = "";
      document.getElementById("lb-pw-input").value = "";
      document.getElementById("lb-pw-prompt").classList.add("open");
      document.getElementById("lb-pw-input").focus();
    } else {
      await lbDoJoinRoom(room, "");
    }
  }

  async function lbDoJoinRoom(room, password) {
    const rid  = normalizeRoomId(room.room_id);
    const name = (window.__fishNickname ? window.__fishNickname() : "") || "Player";
    closeLobbyBrowser();

    const data = await fetchSeats(rid);
    if (!data || !data.seatObjs.length) {
      showToast("Room is full or no longer available.", "err"); return;
    }
    const open = data.seatObjs.filter(s => !s.claimed_name);
    if (!open.length) {
      showToast("All seats are taken.", "err"); return;
    }

    // Competitive: auto-claim the first two open seats as P2's two hands.
    if (data.mode === "competitive") {
      if (open.length < 2) { showToast("This competitive room is already full.", "err"); return; }
      roomId = rid;
      const pw = password || "";
      const j2 = await apiPost(`/api/rooms/${rid}/join`, { player_name: name, seat_index: open[0].index, password: pw }, { timeoutMs:12000 });
      if (!j2.ok) { showToast("Join failed: " + (j2.data?.error || j2.status), "err"); roomId = null; return; }
      const j3 = await apiPost(`/api/rooms/${rid}/join`, { player_name: name + " 2", seat_index: open[1].index, password: pw }, { timeoutMs:12000 });
      if (!j3.ok) { showToast("Join failed (Hand 4): " + (j3.data?.error || j3.status), "err"); return; }
      const s2 = open[0].index, s3 = open[1].index;
      const tokens = { [s2]: j2.data?.seat_token || "", [s3]: j3.data?.seat_token || "" };
      const p1Seat = data.seatObjs.find(s => s.index === 0);
      compMode = true; compMySeats = [s2, s3]; compTokens = tokens;
      compHostToken = ""; compHandNames = {}; _compHsSuppressed = true;
      _compPrevActiveSeat = null;
      compP1Name = p1Seat?.claimed_name?.replace(/ 2$/, "") || "Player 1";
      compP2Name = name;
      setSeatToken(j2.data?.seat_token || "");
      document.getElementById("pv-my-name-badge").textContent = name;
      try { sessionStorage.setItem(`fish_comp_seats_${rid}_${s2}`, JSON.stringify({ seats: [s2, s3], tokens, p1: compP1Name, p2: name })); } catch {}
      showToast("Joined! Waiting for host to start…", "ok");
      enterRoom(rid);
      return;
    }

    // Casual rooms (public or password-confirmed) — drop straight into the
    // first open seat. No seat picker: the server randomizes turn order every
    // game, so the specific seat doesn't matter.
    await autoJoinOpenSeat(rid, data.seatObjs, password);
  }

  // Visibility toggle
  document.getElementById("pv-visibility").addEventListener("change", (e) => {
    document.getElementById("pv-password-row").style.display = e.target.value === "private" ? "" : "none";
    if (e.target.value !== "private") document.getElementById("pv-room-password").value = "";
  });

  // Browse button
  document.getElementById("pv-browse-btn").addEventListener("click", () => {
    refreshFriendNicks();
    openLobbyBrowser();
  });

  // ── Quick Play: dedicated four-seat matchmaking queue ─────────
  // The first player stays on the home page while their queue room waits. As
  // soon as a second player joins, both clients enter the same lobby. Players
  // 3 and 4 may keep joining until those spots become bots.
  let _qmSearch = null;

  function _qmNewTicket() {
    try {
      if (crypto && typeof crypto.randomUUID === "function") {
        return crypto.randomUUID().replace(/-/g, "_");
      }
    } catch (_) {}
    return `qm_${Date.now()}_${Math.random().toString(36).slice(2, 12)}`;
  }

  function _qmUpdateSecs() {
    if (!_qmSearch) return;
    const el = document.getElementById("qm-search-secs");
    if (el) el.textContent = Math.floor((Date.now() - _qmSearch.startTs) / 1000) + "s";
  }
  function _qmSetStatus(message) {
    const statusEl = document.getElementById("qm-search-status");
    if (statusEl) statusEl.textContent = message;
  }
  function _qmShowBar() {
    _qmSetStatus("Finding Quick Play players…");
    const secEl = document.getElementById("qm-search-secs");
    if (secEl) secEl.textContent = "0s";
    const bar = document.getElementById("qm-search-bar");
    if (bar) bar.style.display = "";
  }
  function _qmHideBar() {
    const bar = document.getElementById("qm-search-bar");
    if (bar) bar.style.display = "none";
  }

  function _qmClearTimers(search) {
    if (!search) return;
    if (search.timerId) clearInterval(search.timerId);
    if (search.pollId) clearInterval(search.pollId);
    if (search.retryId) clearTimeout(search.retryId);
  }

  async function _qmReleaseSeat(queuedRoomId, queuedSeatToken) {
    if (!queuedRoomId || !queuedSeatToken) return;
    try {
      await apiPost(`/api/rooms/${queuedRoomId}/leave`,
        { seat_token: queuedSeatToken },
        { timeoutMs: 5000 });
    } catch (_) {}
  }

  async function cancelQuickMatch(silent) {
    const search = _qmSearch;
    _qmClearTimers(search);
    _qmSearch = null;
    _qmHideBar();
    if (search?.roomId && search?.seatToken) {
      await _qmReleaseSeat(search.roomId, search.seatToken);
    }
    if (!silent) { try { showToast("Stopped searching for a match.", "info"); } catch (_) {} }
  }

  function _qmEnterLobby(search) {
    if (!search || _qmSearch !== search || !search.roomId || !search.seatToken) return;
    _qmClearTimers(search);
    _qmSearch = null;
    _qmHideBar();
    roomId = normalizeRoomId(search.roomId);
    if (!roomId) return;
    setSeatToken(search.seatToken);
    if (search.hostToken) setHostToken(search.hostToken);
    _myRoomVisibility = "public";
    _myRoomCode = "";
    compMode = false;
    document.getElementById("pv-my-name-badge").textContent =
      (window.__fishNickname ? window.__fishNickname() : "") || "Player";
    try { showToast("Players found! Opening the Quick Play lobby…", "ok"); } catch (_) {}
    enterRoom(roomId);
  }

  async function _qmPollRoom() {
    const search = _qmSearch;
    if (!search || search.busy || !search.roomId || !search.seatToken) return;
    search.busy = true;
    try {
      const query = new URLSearchParams({ seat_token: search.seatToken });
      if (search.hostToken) query.set("host_token", search.hostToken);
      const res = await apiFetch(
        `/api/rooms/${search.roomId}/state?${query.toString()}`,
        { method: "GET", timeoutMs: 6000 }
      );
      if (_qmSearch !== search) return;
      if (!res.ok || !res.data?.ok) {
        if (search.pollId) clearInterval(search.pollId);
        search.pollId = null;
        search.roomId = "";
        search.seatToken = "";
        search.hostToken = "";
        _qmSetStatus("Reconnecting to Quick Play…");
        search.busy = false;
        await _qmJoinQueue(search);
        return;
      }
      const filled = Number(res.data?.room?.human_seats_filled || 0);
      if (res.data?.room?.quick_play && filled >= 2) {
        _qmEnterLobby(search);
      } else {
        _qmSetStatus("Waiting for another Quick Play player…");
      }
    } catch (_) {
      if (_qmSearch === search) _qmSetStatus("Quick Play is reconnecting…");
    } finally {
      if (_qmSearch === search) search.busy = false;
    }
  }

  async function _qmJoinQueue(search) {
    if (!search || _qmSearch !== search || search.busy) return;
    search.busy = true;
    const name = (window.__fishNickname ? window.__fishNickname() : "") || "Player";
    try {
      const res = await apiPost("/api/quickplay", {
        player_name: name,
        ticket: search.ticket,
      }, { timeoutMs: 10000 });
      if (_qmSearch !== search) {
        await _qmReleaseSeat(
          normalizeRoomId(res.data?.room_id),
          String(res.data?.seat_token || "")
        );
        return;
      }
      if (!res.ok || !res.data?.ok) {
        throw new Error(res.data?.error || "Quick Play is unavailable.");
      }
      search.roomId = normalizeRoomId(res.data.room_id);
      search.seatToken = String(res.data.seat_token || "");
      search.hostToken = String(res.data.host_token || "");
      if (!search.roomId || !search.seatToken) {
        throw new Error("Quick Play returned an incomplete room.");
      }
      if (res.data.matched) {
        _qmEnterLobby(search);
        return;
      }
      _qmSetStatus("Waiting for another Quick Play player…");
      if (search.pollId) clearInterval(search.pollId);
      search.pollId = setInterval(_qmPollRoom, 2500);
    } catch (_) {
      if (_qmSearch !== search) return;
      _qmSetStatus("Quick Play is reconnecting…");
      if (search.retryId) clearTimeout(search.retryId);
      search.retryId = setTimeout(() => {
        search.retryId = null;
        _qmJoinQueue(search);
      }, 2500);
    } finally {
      if (_qmSearch === search) search.busy = false;
    }
  }

  async function startQuickMatch() {
    if (_qmSearch) {
      try { showToast("Quick Play is already searching.", "info"); } catch (_) {}
      return;
    }
    const search = {
      ticket: _qmNewTicket(),
      startTs: Date.now(),
      timerId: null,
      pollId: null,
      retryId: null,
      busy: false,
      roomId: "",
      seatToken: "",
      hostToken: "",
    };
    _qmSearch = search;
    _qmShowBar();
    search.timerId = setInterval(_qmUpdateSecs, 1000);
    await _qmJoinQueue(search);
  }

  document.getElementById("qm-cancel-btn").addEventListener("click", () => cancelQuickMatch(false));

  // Modal close
  document.getElementById("lb-browser-close").addEventListener("click", closeLobbyBrowser);
  document.getElementById("lobby-browser-modal").addEventListener("click", (e) => {
    if (e.target === document.getElementById("lobby-browser-modal")) closeLobbyBrowser();
  });

  // Tab switching
  document.querySelectorAll(".lb-browser-tab").forEach(tab => {
    tab.addEventListener("click", () => {
      document.querySelectorAll(".lb-browser-tab").forEach(t => t.classList.remove("active"));
      tab.classList.add("active");
      _lbActiveTab = tab.dataset.tab;
      renderLobbyList();
    });
  });

  // Password confirm
  document.getElementById("lb-pw-confirm").addEventListener("click", async () => {
    // The private code is stored uppercased (it's the room code), so normalize
    // the entered value the same way before sending.
    const pw = document.getElementById("lb-pw-input").value.trim().toUpperCase();
    if (!pw) { document.getElementById("lb-pw-err").textContent = "Enter the room code."; return; }
    if (!_lbPendingRoom) { document.getElementById("lb-pw-prompt").classList.remove("open"); return; }
    const room = _lbPendingRoom;
    _lbPendingRoom = null;
    document.getElementById("lb-pw-prompt").classList.remove("open");
    await lbDoJoinRoom(room, pw);
  });
  document.getElementById("lb-pw-input").addEventListener("keydown", (e) => {
    if (e.key === "Enter") document.getElementById("lb-pw-confirm").click();
  });

  // Password cancel
  document.getElementById("lb-pw-cancel").addEventListener("click", () => {
    _lbPendingRoom = null;
    document.getElementById("lb-pw-prompt").classList.remove("open");
    document.getElementById("lb-pw-err").textContent = "";
  });


  // ── New Current Modal ──────────────────────────────────────────
  let _ncIsCompetitive = false; // tracks whether the modal was opened for a competitive game
  let _ncMode = "normal";       // 'normal' | 'competitive' | 'team'
  let _ncTeamCount = 2;         // 2..4 (team mode only)
  // Apply the chosen Mode to the setup modal.
  //  • Normal      — a fully customizable game (all settings editable).
  //  • Competitive — a locked "quick-match" ranked 1v1: 4 humans (2 hands
  //    each), 0 AI, public match. Those settings are fixed + disabled so the
  //    host only has to press the main button to continue.
  //  • Team        — a normal, fully-editable game played in 2–4 teams. Adds a
  //    Teams selector; humans/AI/privacy stay editable like Normal.
  // Accepts a mode string; legacy callers may still pass a boolean (isComp).
  function applyNcMode(mode) {
    if (mode === true) mode = "competitive";
    else if (mode === false || mode == null) mode = "normal";
    if (mode !== "competitive" && mode !== "team") mode = "normal";
    _ncMode = mode;
    _ncIsCompetitive = (mode === "competitive");
    const isTeam  = (mode === "team");
    const box     = document.getElementById("new-current-box");
    const totalEl = document.getElementById("nc-total");
    const aiEl    = document.getElementById("nc-ai");
    const visEl   = document.getElementById("nc-visibility");
    const modeEl  = document.getElementById("nc-mode");
    const teamsField = document.getElementById("nc-field-teams");
    const teamCountEl = document.getElementById("nc-team-count");
    const titleEl = document.getElementById("nc-modal-title");
    if (modeEl)  modeEl.value = mode;
    if (box)     box.classList.toggle("nc-comp", _ncIsCompetitive);
    if (box)     box.classList.toggle("nc-team", isTeam);
    if (titleEl) titleEl.textContent = _ncIsCompetitive
      ? "⚔️ Competitive 1v1 — 2 hands per player"
      : (isTeam ? "🤝 New Team Current" : "🌊 New Current");
    if (teamsField) teamsField.style.display = isTeam ? "" : "none";
    if (isTeam && teamCountEl) _ncTeamCount = Math.max(2, Math.min(4, Number(teamCountEl.value) || 2));
    const lock = (fieldId, el, on) => {
      const f = document.getElementById(fieldId);
      if (f)  f.classList.toggle("nc-locked", on);
      if (el) el.disabled = on;
    };
    if (_ncIsCompetitive) {
      if (totalEl) totalEl.value = "4";
      if (aiEl)    aiEl.value    = "0";
      if (visEl)   visEl.value   = "public";
      document.getElementById("nc-password-row").style.display = "none";
      document.getElementById("nc-password").value = "";
    } else if (isTeam) {
      // A team game defaults to 4 humans so 2 teams start 2-v-2, but stays editable.
      if (totalEl && (Number(totalEl.value) || 0) < 2) totalEl.value = "4";
    } else {
      // Back to a fresh, fully-editable Normal game.
      if (totalEl) totalEl.value = "2";
      if (aiEl)    aiEl.value    = "0";
    }
    // Only Competitive locks the base settings; Team leaves them editable.
    lock("nc-field-humans",  totalEl, _ncIsCompetitive);
    lock("nc-field-ai",      aiEl,    _ncIsCompetitive);
    lock("nc-field-privacy", visEl,   _ncIsCompetitive);
  }

  function openNewCurrentModal(opts) {
    document.getElementById("nc-current-err").textContent = "";
    document.getElementById("nc-password-row").style.display = "none";
    document.getElementById("nc-password").value = "";
    document.getElementById("nc-visibility").value = "public";
    applyNcMode((opts && opts.competitive) ? "competitive" : (opts && opts.team) ? "team" : "normal");
    const _ncBtn = document.getElementById("nc-create-btn");
    _ncBtn.disabled = false;
    _ncBtn.classList.remove("generating");
    const _ncLabel = _ncBtn.querySelector(".nc-btn-label");
    if (_ncLabel) _ncLabel.textContent = "Generate Current →";
    document.getElementById("new-current-modal").classList.add("open");
  }
  function closeNewCurrentModal() {
    document.getElementById("new-current-modal").classList.remove("open");
  }
  // Mode selector: switch between Normal / Competitive / Team on the fly.
  document.getElementById("nc-mode").addEventListener("change", (e) => {
    applyNcMode(e.target.value);
  });
  // Team count selector (2–4 teams).
  (function () {
    const tc = document.getElementById("nc-team-count");
    if (tc) tc.addEventListener("change", (e) => {
      _ncTeamCount = Math.max(2, Math.min(4, Number(e.target.value) || 2));
    });
  })();

  // ── Giant Squid challenge: a 1v1 vs-AI match. Winning unlocks the Sea
  // Anemone + the "It Is Finally Over" achievement (+1000 XP). ─────────
  let _giantSquidChallengeActive = false;
  let _giantSquidChallengeRoom = "";
  async function _startGiantSquidChallenge() {
    const name = (window.__fishNickname && window.__fishNickname()) || "Challenger";
    const rid = "SQUID" + Math.random().toString(36).slice(2,5).toUpperCase();
    const createKey = `ck_${Date.now()}_${Math.random().toString(36).slice(2,8)}`;
    try { localStorage.setItem(createKeyKey(), createKey); } catch {}
    const r = await apiPost("/api/rooms", {
      create_key: createKey, host_name: name, room_id: rid,
      total_players: 2, human_players: 1, ai_players: 1,
      replace_active: false, visibility: "private", password: rid,
      competitive: false,
    }, { timeoutMs: 10000 });
    if (!r.ok) { try { showToast("The Giant Squid slipped away — try again.", "err"); } catch (_) {} return; }
    const rId = normalizeRoomId(r.data?.room_id || rid);
    roomId = rId;
    _giantSquidChallengeActive = true;
    _giantSquidChallengeRoom = rId;
    if (r.data?.host_token) setHostToken(r.data.host_token);
    if (r.data?.seat_token) setSeatToken(r.data.seat_token);
    _myRoomVisibility = "private"; _myRoomCode = rId;
    const badge = document.getElementById("pv-my-name-badge"); if (badge) badge.textContent = name;
    enterRoom(rId);
    showWaitingRoom(rId, true);
  }
  window.__fishStartGiantSquidChallenge = _startGiantSquidChallenge;
  // Called from saveGameStats when a game ends: if it was the challenge room
  // and the player won, grant the reward. Clears the challenge either way.
  function _resolveGiantSquidChallenge(isWinner) {
    if (!_giantSquidChallengeActive) return;
    if (roomId && _giantSquidChallengeRoom && roomId !== _giantSquidChallengeRoom) return;
    _giantSquidChallengeActive = false;
    _giantSquidChallengeRoom = "";
    if (isWinner) {
      try { window.__fishUnlockAchievementById?.("it_is_finally_over"); } catch (_) {}
      try { showToast("🦑 You beat the Giant Squid! The Sea Anemone is saved.", "info", 6000); } catch (_) {}
    }
  }

  document.getElementById("nc-close").addEventListener("click", closeNewCurrentModal);
  document.getElementById("new-current-modal").addEventListener("click", (e) => {
    if (e.target === document.getElementById("new-current-modal")) closeNewCurrentModal();
  });

  document.getElementById("nc-visibility").addEventListener("change", (e) => {
    document.getElementById("nc-password-row").style.display = e.target.value === "private" ? "" : "none";
    if (e.target.value !== "private") document.getElementById("nc-password").value = "";
  });

  document.getElementById("nc-create-btn").addEventListener("click", async () => {
    const btn = document.getElementById("nc-create-btn");
    const errEl = document.getElementById("nc-current-err");
    const name = (window.__fishNickname && window.__fishNickname()) || "Host";
    const isTeam = (_ncMode === "team");
    const teamCount = isTeam ? Math.max(2, Math.min(4, _ncTeamCount || 2)) : 2;
    // Competitive games are always 4 humans (2 per player), 0 AI.
    const human = _ncIsCompetitive ? 4 : Math.max(1, Number(document.getElementById("nc-total").value) || 2);
    const ai    = _ncIsCompetitive ? 0 : Math.max(0, Number(document.getElementById("nc-ai").value) || 0);
    const total = human + ai;
    // Team games need enough seats (players + bots) to fill every team.
    if (isTeam && total < teamCount) {
      document.getElementById("nc-current-err").textContent =
        `${teamCount} teams need at least ${teamCount} players or bots — add more seats.`;
      return;
    }
    // Tutorial flag is a one-shot set by "The Game" tour; consume it here so a
    // later manual create is never mis-flagged as a tutorial game.
    const _isTutGame = (window.__ccTutorialGame === true);
    window.__ccTutorialGame = false;
    // Tutorial variant ("blob" = B-Lob Strategy tutorial) tells the server which
    // opening-hand rig to apply. One-shot, consumed here like the tutorial flag.
    const _tutVariant = _isTutGame ? String(window.__ccTutorialVariant || "") : "";
    window.__ccTutorialVariant = "";
    let visibility = document.getElementById("nc-visibility").value;
    let password = "";
    let rid = Math.random().toString(36).slice(2,7).toUpperCase();
    if (visibility === "private") {
      const rawPw = document.getElementById("nc-password").value.trim();
      if (!rawPw) { errEl.textContent = "Enter a code for the private Current."; return; }
      const code = normalizeRoomCode(rawPw);
      if (!code) { errEl.textContent = "Code must be 4–12 letters or numbers (no spaces or symbols)."; return; }
      // The private code IS both the join code and the password.
      rid = code;
      password = code;
    }
    if (_isTutGame) {
      // Keep the tutorial game completely separate from every other game:
      // force it PRIVATE with a unique TUT… code so it never appears in the
      // Open Currents list and no real player can join and disrupt the guided
      // turn (which would scramble turn order and trap the draw step).
      visibility = "private";
      const tutSuffix = (Date.now().toString(36) + Math.random().toString(36).slice(2))
        .replace(/[^a-z0-9]/gi, "").toUpperCase();
      rid = ("TUT" + tutSuffix).slice(0, 12);   // always 4–12 uppercase alphanumerics
      password = rid;
    }
    _myRoomVisibility = visibility;
    _myRoomCode = password;
    const createKey = `ck_${Date.now()}_${Math.random().toString(36).slice(2,8)}`;
    try { localStorage.setItem(createKeyKey(), createKey); } catch {}
    btn.disabled = true;
    btn.classList.add("generating");
    const _ncBtnLabel = btn.querySelector(".nc-btn-label");
    if (_ncBtnLabel) _ncBtnLabel.textContent = "Generating…";
    errEl.textContent = "";
    let r;
    try {
      r = await apiPost("/api/rooms", {
        create_key: createKey, host_name: name, room_id: rid,
        total_players: total, human_players: human, ai_players: ai,
        replace_active: false, visibility, password,
        competitive: _ncIsCompetitive, tutorial: _isTutGame, tutorial_variant: _tutVariant,
        team: isTeam, team_count: teamCount,
      }, { timeoutMs:10000 });
    } catch (e) {
      btn.disabled = false;
      btn.classList.remove("generating");
      if (_ncBtnLabel) _ncBtnLabel.textContent = "Generate Current →";
      ccReport("room_create_failed", {
        source: "new_current",
        visibility,
        total,
        ai,
        competitive: _ncIsCompetitive ? "1" : "0",
        tutorial: _isTutGame ? "1" : "0",
        error: e && (e.name || e.message || e)
      }, "error");
      errEl.textContent = "Failed — check your connection and try again.";
      try { showToast("Create failed — check your connection.", "err"); } catch (_) {}
      return;
    }
    btn.disabled = false;
    btn.classList.remove("generating");
    if (_ncBtnLabel) _ncBtnLabel.textContent = "Generate Current →";
    if (!r.ok) {
      ccReport("room_create_failed", {
        source: "new_current",
        visibility,
        total,
        ai,
        competitive: _ncIsCompetitive ? "1" : "0",
        tutorial: _isTutGame ? "1" : "0",
        status: r.status,
        error: r.data?.error || ""
      }, "warn");
      errEl.textContent = "Failed: " + (r.data?.error || r.status); return;
    }
    const rId = normalizeRoomId(r.data?.room_id || rid);
    roomId = rId;
    if (r.data?.host_token) setHostToken(r.data.host_token);
    if (r.data?.seat_token) setSeatToken(r.data.seat_token);
    document.getElementById("pv-my-name-badge").textContent = name;
    closeNewCurrentModal();
    // Competitive: claim seat 1 for P1's second hand, then enter as comp mode.
    if (_ncIsCompetitive) {
      const hToken = r.data?.host_token || "";
      const seat0Tok = r.data?.seat_token || "";
      const j1 = await apiPost(`/api/rooms/${rId}/join`, { player_name: name + " 2", seat_index: 1, host_token: hToken }, { timeoutMs: 8000 });
      if (j1.ok) {
        const tokens = { 0: seat0Tok, 1: j1.data?.seat_token || "" };
        compMode = true; compMySeats = [0, 1]; compTokens = tokens;
        compHostToken = hToken; compHandNames = {}; _compHsSuppressed = true;
        _compPrevActiveSeat = null; compP1Name = name; compP2Name = "Player 2";
        try { sessionStorage.setItem(`fish_comp_seats_${rId}_0`, JSON.stringify({ seats: [0,1], tokens, p1: name, p2: "Player 2" })); } catch {}
      }
    }
    enterRoom(rId);
    showWaitingRoom(rId, true);
  });

  // ── Seat Picker Modal (for joining public rooms from lobby browser) ──
  let _spPendingRid = null;
  let _spSelectedSeat = null;

  function openSeatPickerModal(rid, seatObjs) {
    _spPendingRid = rid;
    _spSelectedSeat = null;
    document.getElementById("sp-title").textContent = "🪑 Join " + rid;
    document.getElementById("seat-picker-err").textContent = "";
    const joinBtn = document.getElementById("sp-join-btn");
    joinBtn.disabled = true;
    const _spJoinTxt = document.getElementById("sp-join-text"); if (_spJoinTxt) _spJoinTxt.textContent = "Choose a seat above";
    buildSeatGrid(
      document.getElementById("sp-seat-grid"),
      joinBtn,
      seatObjs,
      (i) => { _spSelectedSeat = i; }
    );
    document.getElementById("seat-picker-modal").classList.add("open");
  }
  function closeSeatPickerModal() {
    document.getElementById("seat-picker-modal").classList.remove("open");
    _spPendingRid = null; _spSelectedSeat = null;
  }

  document.getElementById("sp-close").addEventListener("click", closeSeatPickerModal);
  document.getElementById("seat-picker-modal").addEventListener("click", (e) => {
    if (e.target === document.getElementById("seat-picker-modal")) closeSeatPickerModal();
  });

  // ── Draw-over-10 warning modal handlers ────────────────────────
  function closeDrawWarn() {
    document.getElementById("draw-warn-modal").classList.remove("open");
  }
  document.getElementById("draw-warn-cancel").addEventListener("click", () => {
    closeDrawWarn();
    _pendingDrawAction = null;
    selectedPool.clear();
    if (latestPayload) renderPayload(latestPayload);
    setStatus("Draw cancelled — your turn continues.");
  });
  document.getElementById("draw-warn-confirm").addEventListener("click", () => {
    closeDrawWarn();
    const act = _pendingDrawAction;
    _pendingDrawAction = null;
    if (!act) return;
    _drawWarnBypass = true;
    submitAction(act);
  });
  // Clicking the dim backdrop = cancel
  document.getElementById("draw-warn-modal").addEventListener("click", (e) => {
    if (e.target === document.getElementById("draw-warn-modal")) {
      document.getElementById("draw-warn-cancel").click();
    }
  });

  document.getElementById("sp-join-btn").addEventListener("click", async () => {
    if (_spSelectedSeat === null || !_spPendingRid) return;
    const rid = _spPendingRid;
    const name = (window.__fishNickname && window.__fishNickname()) || "Player";
    const btn = document.getElementById("sp-join-btn");
    btn.disabled = true; const _spTxtJ = document.getElementById("sp-join-text"); if (_spTxtJ) _spTxtJ.textContent = "Joining…";
    const j = await apiPost(`/api/rooms/${rid}/join`, { player_name: name, seat_index: _spSelectedSeat }, { timeoutMs:12000 });
    if (!j.ok) {
      document.getElementById("seat-picker-err").textContent = "Join failed: " + (j.data?.error || j.status);
      btn.disabled = false; const _spTxtR = document.getElementById("sp-join-text"); if (_spTxtR) _spTxtR.textContent = `Join as Seat ${_spSelectedSeat + 1} →`;
      return;
    }
    roomId = rid; // must be set before setSeatToken (which keys by roomId)
    if (j.data?.seat_token) setSeatToken(j.data.seat_token);
    document.getElementById("pv-my-name-badge").textContent = name;
    closeSeatPickerModal();
    showToast("Joined! Waiting for host to start…", "ok");
    enterRoom(rid);
  });

  // ── Action submission ──────────────────────────────────────────
  let actionInFlight = false;
  let pendingPayAction = null; // action staged waiting for payment card selection
  const selectedPayment = new Set();
  const selectedDiscard = new Set();
  const selectedPool    = new Set();
  let handEntryMap = new Map();

  function updatePaymentModeUI() {
    const bar         = document.getElementById("pv-payment-mode-bar");
    const playCtrl    = document.getElementById("pv-play-controls");
    const payInfo     = document.getElementById("pv-payment-info");
    const confirmBtn  = document.getElementById("pv-payment-confirm-btn");
    const txt         = document.getElementById("pv-payment-mode-text");
    if (!bar) return;
    if (!pendingPayAction) {
      bar.style.display = "none";
      if (playCtrl) playCtrl.style.display = "flex";
      return;
    }
    bar.style.display = "flex";
    if (playCtrl) playCtrl.style.display = "none";
    const cost    = Number(pendingPayAction.cost_to_pay || 0);
    const name    = pendingPayAction.face_name || "card";
    const sym     = pendingPayAction.required_symbol || pendingPayAction.star_symbol || "";
    const symHint = sym ? ` — needs a ${sym} card` : "";
    const sel     = selectedPayment.size;
    const need    = cost - sel;
    if (txt) {
      txt.textContent = sel >= cost
        ? `✓ Ready — ${cost} card${cost!==1?"s":""} selected to pay for ${name}`
        : `Playing ${name} — click or hover a card and tap "Use as Payment" (${need} more needed${symHint})`;
    }
    if (confirmBtn) {
      confirmBtn.disabled    = sel !== cost;
      confirmBtn.textContent = sel >= cost ? `✓ Confirm Payment` : `Select ${need} more`;
    }
  }

  function enterPaymentMode(action) {
    pendingPayAction = action;
    selectedPayment.clear();
    updatePaymentModeUI();
    const cost = Number(action?.cost_to_pay || 0);
    if (cost > 0) {
      try {
        showToast(`${action.face_name || "This card"} costs ${cost} card${cost === 1 ? "" : "s"} to play. Choose payment cards.`, "info");
      } catch (_) {}
    }
    document.getElementById("pv-hand")?.classList.add("payment-active");
    _handRenderKey = "";
    if (_handRenderData) {
      const { me, actions, mustDiscard, discardExcess } = _handRenderData;
      renderHand(me, actions, mustDiscard, discardExcess);
    }
  }

  // Toggle a card in/out of the payment selection, capping the total at the
  // card's required cost. Returns true if the selection changed. A player can
  // always UNSELECT, but can never select MORE than the cost — so overpaying
  // is impossible at the source (the UI), and the server re-validates anyway.
  function _togglePaymentCard(entryUid) {
    const id = Number(entryUid);
    const cost = Number(pendingPayAction?.cost_to_pay || 0);
    if (selectedPayment.has(id)) {
      selectedPayment.delete(id);   // unselect is always allowed
      return true;
    }
    if (selectedPayment.size >= cost) {
      // Already at the required count — block the extra selection.
      showToast(`You selected too many cards. This card only costs ${cost}.`, "warn");
      return false;
    }
    selectedPayment.add(id);
    return true;
  }

  function exitPaymentMode() {
    pendingPayAction = null;
    selectedPayment.clear();
    updatePaymentModeUI();
    document.getElementById("pv-hand")?.classList.remove("payment-active");
    _handRenderKey = "";
    if (_handRenderData) {
      const { me, actions, mustDiscard, discardExcess } = _handRenderData;
      renderHand(me, actions, mustDiscard, discardExcess);
    }
  }

  // Full "back button" for the current turn: cancel any in-progress (un-submitted)
  // action and wipe EVERY piece of local staging state so the next play starts
  // from a clean slate. Without this, leftover state from a canceled action
  // (e.g. a staged play + selected payment) bleeds into the next action — the
  // classic "it charged me but never placed the animal" bug. Clears: the staged
  // play (card / ocean / side / spot held in pendingPayAction), payment-card
  // selection + confirmation, pool/discard selections, all drag/drop state, the
  // pending-draw confirmation, and the in-flight / action-used flag. Then it
  // re-renders from the last known server state so no stale highlight survives.
  function resetTurnStaging() {
    pendingPayAction   = null;   // staged play (card_uid + ocean_uid + side/spot)
    selectedPayment.clear();     // chosen payment cards
    selectedPool.clear();        // pool picks
    selectedDiscard.clear();     // discard picks
    _pendingDrawAction = null;   // draw awaiting the over-10 confirm
    _pendingMoveAnim   = null;   // move-between-oceans animation staging
    _handDragSrc       = null;   // in-hand reorder drag
    _boardMoveDragSrc  = null;   // board animal move drag
    _drawWarnBypass    = false;  // one-shot draw-warning bypass
    actionInFlight     = false;  // never leave the turn looking "already used"
    // Visual cleanup: payment overlay, any drag-over highlights, the draw modal.
    document.getElementById("pv-hand")?.classList.remove("payment-active");
    document.querySelectorAll(".drag-over").forEach(el => el.classList.remove("drag-over"));
    document.getElementById("draw-warn-modal")?.classList.remove("open");
    updatePaymentModeUI();
    updatePaymentBadge();
    // Repaint hand + board from the last server snapshot so nothing stale lingers.
    _handRenderKey = "";
    if (latestPayload) renderPayload(latestPayload);
  }

  function setStatus(msg) { document.getElementById("pv-status-text").textContent = msg; }

  function _viewerCanActNow() {
    try { return !!(latestPayload && latestPayload.viewer && latestPayload.viewer.can_act); }
    catch (_) { return false; }
  }

  function _dirHuman(dir) {
    const d = String(dir || "").toLowerCase();
    return d === "up" ? "Up" : d === "down" ? "Down" : d === "left" ? "Left" : d === "right" ? "Right" : "that";
  }

  function _entryFirstFace(entry) {
    return (entry && Array.isArray(entry.faces) && entry.faces.length) ? entry.faces[0] : entry;
  }

  function _blockedPlayMessage(entryUid, faceUid, targetDir) {
    if (!_viewerCanActNow()) return "It is not your turn.";
    if (_imAway) return "You're on Surf's Up — tap 🌊 I'm Back before making a move.";

    const entry = handEntryMap.get(Number(entryUid)) || null;
    const face = _entryFirstFace(entry) || {};
    const species = String(face.species || entry?.species || "").trim();
    const me = latestPayload?.state?.players?.find(p => p.index === myIdx);
    const board = Array.isArray(me?.board) ? me.board : [];
    if (!board.length && species && species !== "Ocean") {
      return "You need to play an Ocean first.";
    }

    const acts = (legalActions || []).filter(a =>
      (a.kind === "play_to_ocean" || a.kind === "play_ocean") &&
      (Number(a.card_uid) === Number(entryUid) || Number(a.face_uid) === Number(faceUid))
    );
    if (!acts.length) {
      if (species === "Ocean") return "This Ocean goes in the Ocean drop zone.";
      return "That card cannot be played right now.";
    }

    const costs = [...new Set(acts.map(a => Number(a.cost_to_pay || 0)).filter(n => n > 0))];
    const dirs = [...new Set(acts.map(a => String(a.face_direction || "").toLowerCase()).filter(Boolean))];
    const tDir = String(targetDir || "").toLowerCase();
    if (tDir && dirs.length && !dirs.includes(tDir)) {
      return dirs.length === 1
        ? `This card only goes in the ${_dirHuman(dirs[0])} lane.`
        : `This card only goes in these lanes: ${dirs.map(_dirHuman).join(", ")}.`;
    }
    if (costs.length) {
      const cost = Math.min(...costs);
      return `This card costs ${cost} card${cost === 1 ? "" : "s"} to play.`;
    }
    return "That card can't be played here.";
  }

  function normalizeSymbol(s) { return String(s||"").trim().toLowerCase(); }
  function entryHasSymbolMatch(entryUid, sym) {
    if (!sym) return false;
    const entry = handEntryMap.get(Number(entryUid));
    if (!entry) return false;
    const target = normalizeSymbol(sym);
    // Dual-faced cards: a match on EITHER face counts as payable for the star ability.
    if (Array.isArray(entry.faces) && entry.faces.length > 0) {
      return entry.faces.some(f => normalizeSymbol(f && f.symbol || "") === target);
    }
    return normalizeSymbol(entry.symbol) === target;
  }

  function uniqueIntList(arr) {
    const out = []; const seen = new Set();
    for (const r of (arr||[])) { const n=Number(r); if(Number.isInteger(n)&&!seen.has(n)){seen.add(n);out.push(n);} }
    return out;
  }

  function buildPaymentSet(action, sourceUids) {
    const cost = Number(action.cost_to_pay||0);
    if (cost <= 0) return [];
    const reqSym = Boolean(action.requires_symbol_match && action.required_symbol);
    const avail = uniqueIntList(sourceUids).filter(u => u !== Number(action.card_uid) && handEntryMap.has(u));
    const picks = []; const rem = [...avail];
    if (reqSym) {
      const m = rem.find(u => entryHasSymbolMatch(u, action.required_symbol));
      if (m == null) return null;
      picks.push(m); rem.splice(rem.indexOf(m),1);
    }
    for (const u of rem) { if (picks.length >= cost) break; picks.push(u); }
    return picks.length === cost ? picks : null;
  }

  function choosePayment(action) {
    const cost = Number(action.cost_to_pay||0);
    if (cost <= 0) return { picks:[], error:"" };
    const manual = uniqueIntList(Array.from(selectedPayment));
    if (manual.length === 0) {
      const sym = action.required_symbol || action.star_symbol || "";
      const symHint = sym ? ` (needs a ${sym} card)` : "";
      return { picks:[], error:`Select ${cost} payment card(s) from your hand first${symHint}.` };
    }
    if (manual.length !== cost) {
      return { picks:[], error:`Select exactly ${cost} payment card(s) — you have ${manual.length} selected.` };
    }
    const mp = buildPaymentSet(action, manual);
    if (mp) return { picks: mp, error:"" };
    const sym = action.required_symbol;
    if (sym) return { picks:[], error:`Payment invalid — at least one selected card must have the ${sym} symbol.` };
    return { picks:[], error:`Selected cards cannot be used as payment for this action.` };
  }

  async function submitAction(action) {
    try { window.__ccNoteAction && window.__ccNoteAction(action); } catch (_) {} // Current Controller bug-log breadcrumb
    // Surf's Up!! — you cannot play any moves while you are Away. Tap "I'm Back"
    // (the 🌊 button) first. Mirrors the server-side guard so it's 100% accurate.
    if (_imAway) {
      try { showToast("You're on Surf's Up — tap 🌊 I'm Back to make a move.", "warn"); } catch {}
      return;
    }
    // If the action costs cards, ensure we have valid payment staged for THIS action.
    // enterPaymentMode() clears any stale selection from a prior action.
    if (Number(action.cost_to_pay || 0) > 0) {
      // Payment is considered "confirmed" (pendingPayAction=null) only when the user
      // explicitly clicked Confirm Payment, clearing pendingPayAction before calling here.
      // In every other path (drag, slot-click, picker) pendingPayAction is still set or null
      // from a prior action — if it doesn't match the current action, re-enter payment mode.
      const confirmedPath = pendingPayAction === null && selectedPayment.size > 0;
      const sameStagedAction = pendingPayAction !== null &&
        Number(pendingPayAction.card_uid) === Number(action.card_uid) &&
        Number(pendingPayAction.ocean_uid ?? -1) === Number(action.ocean_uid ?? -1);
      if (!confirmedPath && !sameStagedAction) {
        enterPaymentMode(action);
        return;
      }
    }

    // Hand-over-10 warning: ONLY for manual draw actions (pool / deck / mix).
    // Card-triggered draws don't come through here — they happen server-side
    // as part of resolving a play. So this naturally only catches user draws.
    // Draws are now 1 card at a time, so warn only when THIS draw would push
    // the hand past 10 (not when a hypothetical second draw might).
    if (action.kind === "draw" && !_drawWarnBypass) {
      const meNow = (latestPayload?.state?.players || []).find(p => p.index === myIdx);
      const handCount = Number(meNow?.hand_count ?? (Array.isArray(meNow?.hand) ? meNow.hand.length : 0));
      if (handCount + 1 > 10) {
        _pendingDrawAction = action;
        document.getElementById("draw-warn-modal").classList.add("open");
        return;
      }
    }
    _drawWarnBypass = false;

    // In competitive mode, use the token for whichever of our seats is currently active.
    // mySeatIdx is the seat index (token key); myIdx is the game/player index.
    let token;
    if (compMode && mySeatIdx !== null && compTokens[mySeatIdx]) {
      token = compTokens[mySeatIdx];
    } else {
      token = getSeatToken();
    }
    if (!token) { setStatus("No seat token — re-join."); showToast("No seat token — re-join.", "err"); return; }
    if (actionInFlight) { setStatus("Wait for previous action…"); return; }

    const pl = { seat_token: token, use_star: Boolean(action.use_star), request_id: makeRequestId() };
    const hi = v => typeof v === "number" && Number.isInteger(v);
    if (hi(action.index))          pl.action_index = action.index;
    if (action.kind)               pl.kind = action.kind;
    if (hi(action.card_uid))       pl.card_uid = action.card_uid;
    if (hi(action.face_uid))       pl.face_uid = action.face_uid;
    if (hi(action.ocean_uid))      pl.ocean_uid = action.ocean_uid;
    if (hi(action.source_ocean_uid)) pl.source_ocean_uid = action.source_ocean_uid;
    if (hi(action.draw_from_pool)) pl.draw_from_pool = action.draw_from_pool;
    const need = Number(action.draw_from_pool||0);
    if (Array.isArray(action.pool_pick_uids) && action.pool_pick_uids.length > 0) {
      pl.pool_pick_uids = action.pool_pick_uids;
    } else if (need > 0) {
      pl.pool_pick_uids = Array.from(selectedPool).slice(0, need);
    }
    if (action.kind === "discard_batch_to_pool" && Array.isArray(action.pool_pick_uids))
      pl.pool_pick_uids = action.pool_pick_uids;
    const cost = Number(action.cost_to_pay||0);
    if (cost > 0) {
      // ── Star play without a matching-symbol payment ──────────────
      // The ★ toggle is on, so this is the STAR variant — which needs at least
      // one payment card whose symbol matches. If the player's chosen payment
      // has NO matching symbol, don't hard-error (the old behavior, which felt
      // like the game "breaking"). Instead pop the friendly "skip the ★?" confirm:
      //   • Confirm → replay the SAME card WITHOUT the star, using their cards.
      //   • Go back → return to payment mode with their picks intact so they can
      //     swap in a matching-symbol card and keep the star.
      if (action.use_star && action.requires_symbol_match && action.required_symbol
          && selectedPayment.size === cost) {
        const sym = action.required_symbol;
        const hasMatch = Array.from(selectedPayment).some(uid => entryHasSymbolMatch(uid, sym));
        if (!hasMatch) {
          const nonStar = (legalActions || []).find(a => !a.use_star &&
            Number(a.card_uid) === Number(action.card_uid) &&
            String(a.kind) === String(action.kind) &&
            Number(a.ocean_uid ?? -1) === Number(action.ocean_uid ?? -1) &&
            String(a.face_direction || "") === String(action.face_direction || "")
          );
          const entry = handEntryMap.get(Number(action.card_uid));
          const face  = entry?.faces?.[0] || entry;
          const ability = starText(face?.text || entry?.text || "") || "the star ability";
          const msg = document.getElementById("star-skip-msg");
          if (msg) msg.textContent =
            `You didn't discard a ${sym} card, so you won't get "${ability}". Play it without the star ability?`;
          _starSkipPendingCb = () => {
            // Submit the non-star play with the SAME chosen payment.
            submitAction(nonStar ? { ...nonStar } : { ...action, use_star: false });
          };
          _starSkipBackCb = () => {
            // Return to payment mode, keeping their current selection.
            pendingPayAction = action;
            document.getElementById("pv-hand")?.classList.add("payment-active");
            updatePaymentModeUI();
            if (latestPayload) { _handRenderKey = ""; renderPayload(latestPayload); }
          };
          document.getElementById("star-skip-modal")?.classList.add("open");
          return;
        }
      }
      const pay = choosePayment(action);
      if (pay.error) {
        // Invalid selection — re-enter payment mode so the user can pick valid cards.
        enterPaymentMode(action);
        setStatus(pay.error); showToast(pay.error, "err"); return;
      }
      pl.payment_uids = pay.picks;
    }

    // Increment the draw counter OPTIMISTICALLY before the network round-trip so
    // a slow or 503-ing server can never leave the tutorial stuck on the draw step.
    // Reverted below if the server rejects the action.
    const _isDrawAction = (action.kind === "draw");
    if (_isDrawAction) _ccDrawCount++;

    actionInFlight = true;
    setStatus("Submitting…");
    try {
      const r = await apiPost(`/api/rooms/${roomId}/action`, pl, { timeoutMs:15000 });
      if (!r.ok) {
        if (_isDrawAction) _ccDrawCount--;  // revert optimistic increment on rejection
        if (r.data?.error === "room not found") { handleRoomLost(); return; }
        const errMsg = "Failed: " + (r.data?.error || r.status);
        setStatus(errMsg); showToast(errMsg, "err"); return;
      }
      selectedPayment.clear(); selectedPool.clear(); selectedDiscard.clear();
      pendingPayAction = null;
      document.getElementById("pv-hand")?.classList.remove("payment-active");
      updatePaymentBadge();
      updatePaymentModeUI();
      const desc = action.description ? action.description : (action.kind || "Action sent");
      setStatus("→ " + desc);
      showToast(desc, "ok");
      // Only optimistically clear the banner and block canInteract when the
      // submitted action is end_turn — that's the only action that actually
      // advances active_action_seat. For mid-turn actions (draw, play card,
      // move animal, etc.) can_act correctly stays true and the banner should
      // remain "YOUR TURN" without any confusing flicker.
      if (action.kind === "end_turn") {
        const _optBanner = document.getElementById("pv-turn-banner");
        const _optEndBtn  = document.getElementById("pv-end-turn-inline");
        if (_optBanner) _optBanner.className = "their-turn";
        if (_optEndBtn)  _optEndBtn.classList.remove("pulse-glow");
        canInteract = false;
        _lastActionMs = Date.now();
      }
      // (draw counter already incremented optimistically above)
      // Track per-game stats for achievements
      // I Don't Need Help: any manual draw (Pool OR Deck) disqualifies the game.
      if (action.kind === "draw" && Number(action.draw_from_pool || 0) === 0) {
        _gameAchTracker.manualDeckDraw = true;
        // Peruvian Pelican avatar: cumulative deck draws (1 card per deck draw).
        _gameAchTracker.deckDraws = (_gameAchTracker.deckDraws || 0) + 1;
      }
      // Hard Choices (cumulative): discard cards to pay card costs — bump by the
      // number of payment cards spent this action.
      try {
        const payCount = Array.isArray(pl.payment_uids) ? pl.payment_uids.length : 0;
        if (payCount > 0) window.__fishBumpAchievement?.("hard_choices", payCount, 100);
      } catch {}
      if (action.kind === "draw" && Number(action.draw_from_pool || 0) > 0) {
        _gameAchTracker.usedPool = true;
        // ── Pool draw challenge hooks ─────────────────────────────
        try {
          const myName = (Array.isArray(_latestPlayers) ? _latestPlayers : []).find(p => p.index === myIdx)?.name;
          const pickUids = Array.isArray(action.pool_pick_uids) ? action.pool_pick_uids.map(Number) : [];

          // fresh_current — drawing from a freshly-reset pool (within 60s of reset)
          if (_chObsPoolJustResetAt && (Date.now() - _chObsPoolJustResetAt) < 60000 && pickUids.length > 0) {
            window._reportDailyChallengeProgress?.("fresh_current", 0, { complete: true });
            _chObsPoolJustResetAt = 0;
          }

          // Check provenance of drawn cards: which were added by other players?
          let drawnFromOther = false;
          let drawnFromOpponentLastTurn = false;
          let drawnFromMyCompPartner = false;
          const round = Number(latestPayload?.state?.round_count) || 0;
          for (const uid of pickUids) {
            const owner = _chObsPoolEntryOwner.get(uid);
            const addedTurn = _chObsPoolEntryAddedTurn.get(uid);
            if (!owner) continue;
            if (owner !== myName) {
              drawnFromOther = true;
              // deny_the_setup / stolen_setup — opponent put it in last turn
              if (addedTurn != null && (round - Number(addedTurn)) <= 1) {
                drawnFromOpponentLastTurn = true;
              }
            }
            // set_it_up — comp only, this device's seats put it in
            if (_chObsCompSelfDiscarded.has(uid)) {
              const ownerSeatIdx = (Array.isArray(_latestPlayers) ? _latestPlayers : [])
                .find(p => p.name === owner)?.index;
              // Make sure the pickup is by the OPPOSITE hand of the same device.
              if (Array.isArray(compMySeats) && compMySeats.includes(ownerSeatIdx) && ownerSeatIdx !== myIdx) {
                drawnFromMyCompPartner = true;
              }
            }
          }

          // pool_watcher — streak of pool draws from OTHER players' cards.
          // Any pool draw from MY OWN discarded card resets the streak.
          if (pickUids.length > 0) {
            if (drawnFromOther && pickUids.every(u => {
                  const o = _chObsPoolEntryOwner.get(u);
                  return o && o !== myName;
                })) {
              _chObsPoolWatcherStreak++;
              if (_chObsPoolWatcherStreak >= 5) {
                window._reportDailyChallengeProgress?.("pool_watcher", 0, { complete: true });
              }
            } else {
              _chObsPoolWatcherStreak = 0;
            }
          }

          // deny_the_setup (daily) / stolen_setup (weekly) — drew an opponent's
          // very-recently-played pool card.
          if (drawnFromOpponentLastTurn) {
            window._reportDailyChallengeProgress?.("deny_the_setup", 0, { complete: true });
            window._reportWeeklyChallengeProgress?.("stolen_setup", 0, { complete: true });
          }

          // set_it_up (daily, comp only) — pulled out a card that THIS device
          // had earlier set up via the opposite hand.
          if (drawnFromMyCompPartner) {
            window._reportDailyChallengeProgress?.("set_it_up", 0, { complete: true });
          }

          // pool_patience — a card that has been in the pool for >= one full
          // rotation (N players * 1 turn each) gets taken by me.
          const playerCount = (Array.isArray(_latestPlayers) ? _latestPlayers.length : 0) || 4;
          for (const uid of pickUids) {
            const addedTurn = _chObsPoolEntryAddedTurn.get(uid);
            if (addedTurn != null && (round - Number(addedTurn)) >= 1) {
              window._reportDailyChallengeProgress?.("pool_patience", 0, { complete: true });
              break;
            }
          }

          // Clear taken cards from provenance maps so they don't re-trigger.
          for (const uid of pickUids) {
            _chObsPoolEntryOwner.delete(uid);
            _chObsPoolEntryAddedTurn.delete(uid);
            _chObsCompSelfDiscarded.delete(uid);
          }
        } catch (e) { /* non-fatal */ }
      }
      if (action.kind === "move_between_oceans") {
        _gameAchTracker.animalMoves = (_gameAchTracker.animalMoves || 0) + 1;
        // Daily: current_lite — Move 3 animals today (target 3, accumulates).
        try { window._reportDailyChallengeProgress?.("current_lite", 1); } catch {}
        // Daily: last_turn_move — Move an animal after End Game appears.
        // Achievement board_fixer: moved an animal on the final turn (end-game
        // window) — combined with a win at game end.
        if (_gameAchTracker.endGameSeen) {
          _gameAchTracker.movedDuringEndgame = true;
          try { window._reportDailyChallengeProgress?.("last_turn_move", 0, { complete: true }); } catch {}
        }
        // Snapshot my score before the move resolves; the per-payload
        // observer will compare to the post-move score to detect
        // 'better_spot' (move increased my score).
        try {
          const meNow = (Array.isArray(_latestPlayers) ? _latestPlayers : []).find(p => p.index === myIdx);
          if (meNow) _chObsPreMoveScore = Number(meNow.score || 0);
        } catch {}
      }

      // ── Surface / Floor streak hooks ──────────────────────────────
      if (action.kind === "play_to_ocean") {
        // Card-name based avatar hooks.
        try {
          const playedName = String(handEntryMap.get(Number(action.card_uid))?.name || "").trim().toLowerCase();
          // Razorbill Auk: play both in same turn in a 4-player game.
          if (playedName === "razorbill auk") {
            _gameAchTracker.razorbillThisTurn = (_gameAchTracker.razorbillThisTurn || 0) + 1;
            const _razPlayers = (Array.isArray(_latestPlayers) ? _latestPlayers.length : 0);
            if (_gameAchTracker.razorbillThisTurn >= 2 && _razPlayers >= 4 && typeof window.__fishGrantUnlockedIcon === "function") {
              if (await window.__fishGrantUnlockedIcon("/avatars/razorbill-auk.png")) _queueAnimalUnlock("razorbill-auk");
            }
          }
          // Big Eye Tuna: play all 5 in one game (checked for the win at game end).
          if (playedName === "big eye tuna") {
            _gameAchTracker.bigEyeTunaPlayed = (_gameAchTracker.bigEyeTunaPlayed || 0) + 1;
          }
          // Roosterfish: its ★ ability is "play a free Baitfish" (legacy counter).
          if (playedName === "roosterfish" && action.use_star) {
            _gameAchTracker.freeBaitfishUses = (_gameAchTracker.freeBaitfishUses || 0) + 1;
          }
          // Grooved Brain Coral avatar: use 2 Grooved Brain Coral ★ abilities and
          // play a Giant Squid and a Bobtail Squid via those free-cephalopod
          // windows. Grooved Brain Coral is the ONLY card that grants a free
          // cephalopod, so a squid played while a free-cephalopod window is open
          // necessarily came from its ★ ability.
          if (playedName === "grooved brain coral" && action.use_star) {
            _gameAchTracker.grooveBrainStars = (_gameAchTracker.grooveBrainStars || 0) + 1;
          }
          const _fpsAtPlay = Array.isArray(latestPayload?.legal_actions?.free_play_species)
            ? latestPayload.legal_actions.free_play_species : [];
          const _freeCephActive = _fpsAtPlay.some(s => String(s).trim().toLowerCase() === "cephalopod");
          if (_freeCephActive && playedName === "giant squid")   _gameAchTracker.giantSquidViaGBC = true;
          if (_freeCephActive && playedName === "bobtail squid") _gameAchTracker.bobtailSquidViaGBC = true;
        } catch {}

        // ── Invertebrate "draw one" avatars ───────────────────────────
        // Each of these animals draws a card when a trigger condition fires,
        // but only while it is already on your board. Count one draw per copy
        // on board at play time (the just-played card isn't on board yet).
        try {
          // Resolve the played face (name + species) from the hand entry. The
          // played face uid may be a face uid OR an entry key, so scan faces.
          let _pf = null, _pe = null;
          for (const e of handEntryMap.values()) {
            const hit = (Array.isArray(e.faces) ? e.faces : []).find(f => Number(f.uid) === Number(action.card_uid));
            if (hit) { _pf = hit; _pe = e; break; }
          }
          if (!_pe) { _pe = handEntryMap.get(Number(action.card_uid)) || null; _pf = _pe?.faces?.[0] || null; }
          const invName    = String(_pf?.name || _pe?.name || "").trim().toLowerCase();
          const invSpecies = String(_pf?.species || "").trim().toLowerCase();
          const invDir     = String(action.face_direction || "").toLowerCase();
          const myBoard = (Array.isArray(_latestPlayers) ? _latestPlayers : []).find(p => p.index === myIdx)?.board;
          const countOnBoard = (nm) => {
            let n = 0;
            for (const ocean of (Array.isArray(myBoard) ? myBoard : [])) {
              for (const d of ["up","down","left","right"]) {
                for (const c of (Array.isArray(ocean[d]) ? ocean[d] : [])) {
                  if (String(c.name || "").trim().toLowerCase() === nm) n++;
                }
              }
            }
            return n;
          };
          // Sea Urchin — draw one (per Urchin) when you play an animal on the surface.
          if (invDir === "up")
            _gameAchTracker.seaUrchinDraws = (_gameAchTracker.seaUrchinDraws || 0) + countOnBoard("sea urchin");
          // Sea Star — draw one (per Star) when you play a card on the ocean floor.
          if (invDir === "down")
            _gameAchTracker.seaStarDraws = (_gameAchTracker.seaStarDraws || 0) + countOnBoard("common sea star");
          // Sea Cucumber — draw one (per Cucumber) when you play a Game Fish.
          if (invSpecies === "game fish")
            _gameAchTracker.seaCucumberDraws = (_gameAchTracker.seaCucumberDraws || 0) + countOnBoard("sea cucumber");
          // Sea Anemone — its ★ ability draws one card when activated (legacy draw count).
          if (invName === "sea anemone" && action.use_star)
            _gameAchTracker.seaAnemoneDraws = (_gameAchTracker.seaAnemoneDraws || 0) + 1;
          // Sea Anemone — count every Sea Anemone card played this game (avatar: 25 lifetime plays).
          if (invName === "sea anemone")
            _gameAchTracker.seaAnemonePlayedThisGame = (_gameAchTracker.seaAnemonePlayedThisGame || 0) + 1;
          // Sea Cucumber — count every Sea Cucumber card played this game (avatar: 25 lifetime plays).
          if (invName === "sea cucumber")
            _gameAchTracker.seaCucumberPlayedThisGame = (_gameAchTracker.seaCucumberPlayedThisGame || 0) + 1;
          // Frigatebird avatar: 7 Coral cards played onto a Coral Reef ocean in one game.
          if (invSpecies === "coral") {
            const targetOceanUid = Number(action.ocean_uid ?? -1);
            const playedOnCoralReef = (Array.isArray(myBoard) ? myBoard : []).some(o =>
              Number(o.ocean_uid) === targetOceanUid &&
              String(o.ocean?.name || "").trim().toLowerCase() === "coral reef"
            );
            if (playedOnCoralReef)
              _gameAchTracker.coralCardsPlayed = (_gameAchTracker.coralCardsPlayed || 0) + 1;
          }
          // All Bait Fish played this game (Roosterfish avatar: 250 lifetime total).
          if (invSpecies === "baitfish")
            _gameAchTracker.baitfishPlayedThisGame = (_gameAchTracker.baitfishPlayedThisGame || 0) + 1;
          // Loggerhead Sea Turtle — count cards played in the current turn and
          // flag when a Turtle was played (its ability chains extra card plays).
          _gameAchTracker.cardsPlayedThisTurn = (_gameAchTracker.cardsPlayedThisTurn || 0) + 1;
          if (invName === "loggerhead sea turtle") _gameAchTracker.turtlePlayedThisTurn = true;
          // Hermit Crab — its ability lets you play baitfish for free this turn.
          // Flag the Hermit Crab play and count Bait Fish played this turn.
          if (invName === "hermit crab") _gameAchTracker.hermitUsedThisTurn = true;
          if (invSpecies === "baitfish") _gameAchTracker.baitFishThisTurn = (_gameAchTracker.baitFishThisTurn || 0) + 1;
          // Grant the Hermit Crab avatar the moment the requirement is met — a
          // Hermit Crab turn with 6+ Bait Fish in a 4+ player game — rather than
          // waiting for game end (which could be missed if the game ends first).
          if (_gameAchTracker.hermitUsedThisTurn && Number(_gameAchTracker.baitFishThisTurn || 0) >= 6) {
            _gameAchTracker.hermitSixBaitDone = true;
            const _hcPlayers = (Array.isArray(_latestPlayers) ? _latestPlayers.length : 0);
            if (_hcPlayers >= 4 && typeof window.__fishGrantUnlockedIcon === "function") {
              if (await window.__fishGrantUnlockedIcon("/avatars/hermit-crab.png")) _queueAnimalUnlock("hermit-crab");
            }
          }
        } catch {}

        const dir = String(action.face_direction || "").toLowerCase();
        if (dir === "up") {
          _chObsSurfaceStreak++;
          _chObsFloorStreak = 0;
          if (_chObsSurfaceStreak >= 3) {
            try { window._reportDailyChallengeProgress?.("surface_life", 0, { complete: true }); } catch {}
          }
        } else if (dir === "down") {
          _chObsFloorStreak++;
          _chObsSurfaceStreak = 0;
          if (_chObsFloorStreak >= 3) {
            try { window._reportDailyChallengeProgress?.("ocean_floor", 0, { complete: true }); } catch {}
          }
        } else {
          // left/right break both streaks
          _chObsSurfaceStreak = 0;
          _chObsFloorStreak = 0;
        }

        // Free animal play — submitted a play during an active free-play window.
        const fpsBefore = Array.isArray(latestPayload?.legal_actions?.free_play_species)
          ? latestPayload.legal_actions.free_play_species
          : [];
        if (fpsBefore.length > 0) {
          try { window._reportWeeklyChallengeProgress?.("free_animal_week", 1); } catch {}
        }
      } else if (action.kind && action.kind !== "play_ocean") {
        // Any other action (draw, move, discard, end turn) breaks the streaks.
        _chObsSurfaceStreak = 0;
        _chObsFloorStreak = 0;
      }

      // ── Star ability activation hooks ─────────────────────────────
      if (action.use_star) {
        _gameAchTracker.starsActivated = (_gameAchTracker.starsActivated || 0) + 1;
        _chObsStarTurnPlayer = latestPayload?.state?.current_player || null;
        // Snapshot turn-start score so combo_current can verify the +15 hit.
        try {
          const meNow = (Array.isArray(_latestPlayers) ? _latestPlayers : []).find(p => p.index === myIdx);
          const myName = meNow?.name;
          if (myName && _turnStartScores[myName] != null) {
            _chObsStarTurnStartScore = Number(_turnStartScores[myName]);
          }
        } catch {}
        try {
          // Daily: star_spark — Activate 2 ★ abilities (target 2, accumulates)
          window._reportDailyChallengeProgress?.("star_spark", 1);
          // Daily: star_surfer — Activate 5 ★ in ONE game. Per-game counter
          // resets in _resetGameAchTracker, so once the in-game count reaches
          // 5 we mark it complete (idempotent if already done).
          if (_gameAchTracker.starsActivated >= 5) {
            window._reportDailyChallengeProgress?.("star_surfer", 0, { complete: true });
          }
          // Daily: symbol_match — Discard matching symbol to activate ★
          // (any successful ★ activation requires a matching symbol).
          window._reportDailyChallengeProgress?.("symbol_match", 0, { complete: true });
          // Achievement perfect_symbol (cumulative): matching-symbol ★ activation 100×.
          window.__fishBumpAchievement?.("perfect_symbol", 1, 100);
          // Daily: star_finish — ★ activation after End Game appears
          if (_gameAchTracker.endGameSeen) {
            window._reportDailyChallengeProgress?.("star_finish", 0, { complete: true });
          }
          // Weekly: star_storm — 20 ★ activations this week
          window._reportWeeklyChallengeProgress?.("star_storm", 1);
        } catch {}
      }
      // Competitive: hand-switch is handled by checkCompHandSwitch in renderPayload
      // once the server confirms the active seat changed — no immediate call needed here.
      await sleep(160);
      refreshStateAfterAction();
    } catch(e) { setStatus("Error: " + e.message); showToast("Error: " + e.message, "err"); }
    finally { actionInFlight = false; }
  }

  // ── Rendering helpers ──────────────────────────────────────────
  function cl(el) { while(el.firstChild) el.removeChild(el.firstChild); }

  function symbolEmoji(sym) {
    const s = normalizeSymbol(sym);
    if (s==="diamond")  return "◆";
    if (s==="circle")   return "●";
    if (s==="square")   return "■";
    if (s==="triangle") return "▲";
    if (s==="heart")    return "♥";
    return sym || "?";
  }

  // ── Canonical animal-family colours — ONE colour per species, used
  //    everywhere (strategy highlights, card glows, corner tags, tooltips and
  //    the strategy panel). A single source of truth is what keeps the colours
  //    100% consistent for players: e.g. a pink glow ALWAYS means "Mammal". ──
  const FAMILY_COLORS = {
    mammal:       "#f25fa6", // pink
    "game fish":  "#9aa6b2", // grey
    crustacean:   "#ef4444", // red    (lobsters)
    invertebrate: "#a855f7", // purple
    crosscurrent: "#22c55e", // green  (border / cross-current)
    coral:        "#facc15", // yellow
    baitfish:     "#a86a34", // brown
    cephalopod:   "#fb8c2a", // orange
    bird:         "#3b82f6", // blue
    ocean:        "#14c7d4", // teal   (the only family the player didn't name)
  };
  // Normalise the many spellings the data uses ("Gamefish", "Crustaceans",
  // "Lobster", plurals…) down to a FAMILY_COLORS key.
  function _normFamily(species) {
    let s = String(species || "").toLowerCase().trim();
    if (s === "gamefish" || s === "game-fish") s = "game fish";
    if (s === "lobster" || s === "lobsters" || s === "crustaceans") s = "crustacean";
    if (s === "cross current" || s === "cross-current" || s === "current") s = "crosscurrent";
    if (FAMILY_COLORS[s]) return s;
    if (s.endsWith("s") && FAMILY_COLORS[s.slice(0, -1)]) return s.slice(0, -1);
    return s;
  }
  function familyColor(species) { return FAMILY_COLORS[_normFamily(species)] || "#b388ff"; }
  // Black or white text, whichever stays legible on a given family colour.
  function _idealText(hex) {
    const h = String(hex || "").replace("#", "");
    if (h.length < 6) return "#07101f";
    const r = parseInt(h.slice(0,2),16), g = parseInt(h.slice(2,4),16), b = parseInt(h.slice(4,6),16);
    return ((0.299*r + 0.587*g + 0.114*b) / 255) > 0.6 ? "#07101f" : "#ffffff";
  }
  // Tooltip / zoom species-label colour. Falls back for the non-animal "End
  // Game" reminder tag, then to muted for anything unknown.
  function speciesColor(species) {
    const s = _normFamily(species);
    if (FAMILY_COLORS[s]) return FAMILY_COLORS[s];
    if (s === "end game") return "#f87171";
    return "var(--muted)";
  }
  // Small colour key shown at the top of the Strategies panel so new players
  // instantly learn which colour means which animal family.
  const _FAMILY_LEGEND = [
    ["Mammals", "mammal"], ["Birds", "bird"], ["Lobsters", "crustacean"],
    ["Cephalopods", "cephalopod"], ["Baitfish", "baitfish"], ["Game Fish", "game fish"],
    ["Coral", "coral"], ["Invertebrates", "invertebrate"], ["Cross-Current", "crosscurrent"],
    ["Oceans", "ocean"],
  ];
  function _familyLegendHtml() {
    return `<div class="hs-legend"><span class="hs-legend-cap">Card colours:</span>` +
      _FAMILY_LEGEND.map(([lbl, sp]) => `<span class="hs-legend-chip" style="--lc:${FAMILY_COLORS[sp]}">${lbl}</span>`).join("") +
      `</div>`;
  }

  function starText(text) { const m=/\*([^*]+)\*/g.exec(text||""); return m ? m[1].trim():""; }
  function mainText(text) {
    return String(text||"").replace(/\*[^*]+\*/g,"").replace(/\|\s*\|/g,"|")
      .replace(/^\s*\|\s*/,"").replace(/\s*\|\s*$/,"").trim();
  }

  // Star-skip guard: if the player is about to play a card with an available star
  // ability WITHOUT activating it, show a quick confirmation so they don't
  // accidentally skip it. "Let me go back" cancels; "Yes, that's okay" proceeds.
  let _starSkipPendingCb = null;
  let _starSkipBackCb = null;   // runs when the player declines (Go back / backdrop)
  // Move confirmation dialog state
  let _moveConfirmPendingCb  = null;
  let _endTurnPendingCb      = null;
  // Pending move animation: set when a move is confirmed so renderMyBoard can FLIP-animate the card
  let _pendingMoveAnim = null; // { srcRect, faceUid, tgtUid }
  (function _initStarSkipModal() {
    const modal    = document.getElementById("star-skip-modal");
    const backBtn  = document.getElementById("star-skip-back");
    const okBtn    = document.getElementById("star-skip-confirm");
    if (!modal || !backBtn || !okBtn) return;
    backBtn.addEventListener("click", () => {
      modal.classList.remove("open");
      const bcb = _starSkipBackCb;
      _starSkipPendingCb = null; _starSkipBackCb = null;
      if (bcb) bcb();
    });
    okBtn.addEventListener("click", () => {
      modal.classList.remove("open");
      const cb = _starSkipPendingCb;
      _starSkipPendingCb = null; _starSkipBackCb = null;
      if (cb) cb();
    });
    modal.addEventListener("click", (e) => {
      if (e.target === modal) {
        modal.classList.remove("open");
        const bcb = _starSkipBackCb;
        _starSkipPendingCb = null; _starSkipBackCb = null;
        if (bcb) bcb();
      }
    });
  })();

  // Move confirmation dialog: "You are about to MOVE this card from X to Y. Are you sure?"
  // Only shown for move_between_oceans actions (never for play-from-hand).
  (function _initMoveConfirmModal() {
    const modal     = document.getElementById("move-confirm-modal");
    const cancelBtn = document.getElementById("move-confirm-cancel");
    const okBtn     = document.getElementById("move-confirm-ok");
    if (!modal || !cancelBtn || !okBtn) return;
    cancelBtn.addEventListener("click", () => { modal.classList.remove("open"); _moveConfirmPendingCb = null; });
    okBtn.addEventListener("click", () => {
      modal.classList.remove("open");
      const cb = _moveConfirmPendingCb; _moveConfirmPendingCb = null;
      if (cb) cb();
    });
    modal.addEventListener("click", (e) => {
      if (e.target === modal) { modal.classList.remove("open"); _moveConfirmPendingCb = null; }
    });
  })();

  // Friendly End Turn confirmation modal (replaces scary browser confirm())
  function _openEndTurnModal(endAct, isFreeWindow, freePlaySpecies) {
    const msgEl = document.getElementById("end-turn-msg");
    if (msgEl) {
      msgEl.textContent = isFreeWindow
        ? `You have a free ${(freePlaySpecies||[]).join("/")} play available. Skip it and pass to the next player?`
        : "You're about to pass to the next player. You can still cancel if you want to keep playing.";
    }
    _endTurnPendingCb = () => submitAction(endAct);
    document.getElementById("end-turn-modal")?.classList.add("open");
  }
  (function _initEndTurnModal() {
    const modal     = document.getElementById("end-turn-modal");
    const cancelBtn = document.getElementById("end-turn-cancel");
    const okBtn     = document.getElementById("end-turn-confirm");
    if (!modal || !cancelBtn || !okBtn) return;
    cancelBtn.addEventListener("click", () => { modal.classList.remove("open"); _endTurnPendingCb = null; });
    okBtn.addEventListener("click", () => {
      modal.classList.remove("open");
      const cb = _endTurnPendingCb; _endTurnPendingCb = null;
      if (cb) cb();
    });
    modal.addEventListener("click", (e) => {
      if (e.target === modal) { modal.classList.remove("open"); _endTurnPendingCb = null; }
    });
  })();

