    26:  { name:"Sea Anemone",       symbol:"circle",   species:"invertebrate",text:"+3 pts per Invertebrate on your board.",                starText:"Draw one card." },
    27:  { name:"Peruvian Pelican",  symbol:"diamond",  species:"bird",        text:"+5 pts | Draw one card.",                              starText:"Draw three cards instead." },
