  _pg("pv-grp-cancel").addEventListener("click", pvcCloseGroupModal);
  _pg("pv-grp-save").addEventListener("click", pvcGroupSave);
  _pg("pv-grp-leave").addEventListener("click", pvcGroupLeave);
  _pg("pv-grp-modal").addEventListener("click", (e) => { if (e.target === _pg("pv-grp-modal")) pvcCloseGroupModal(); });
  _pg("pv-grp-name").addEventListener("keydown", (e) => { if (e.key === "Enter") { e.preventDefault(); pvcGroupSave(); } });

  // ═══════════════════════════════════════════════════════════════
  // FULL SCREEN BUTTON
  // ═══════════════════════════════════════════════════════════════
  (function setupFullScreenBtn() {
    const btn = document.getElementById("pv-fullscreen-btn");
    if (!btn) return;
    function isFs() {
      return Boolean(document.fullscreenElement || document.webkitFullscreenElement);
    }
    function updateLabel() {
      btn.innerHTML = isFs() ? "⛶ Exit Full Screen" : "⛶ Full Screen";
    }
    btn.addEventListener("click", async () => {
      const entering = !isFs();
      try {
        if (entering) {
          const target = document.documentElement;
          if (target.requestFullscreen) await target.requestFullscreen();
          else if (target.webkitRequestFullscreen) await target.webkitRequestFullscreen();
        } else {
          if (document.exitFullscreen) await document.exitFullscreen();
          else if (document.webkitExitFullscreen) await document.webkitExitFullscreen();
        }
      } catch (e) { /* swallow — browsers may block depending on gesture */ }
      if (entering && !isFs()) {
        try { showToast("Full screen was blocked by the browser. Try the button again.", "warn"); } catch (_) {}
      }
      updateLabel();
    });
    document.addEventListener("fullscreenchange", updateLabel);
    document.addEventListener("webkitfullscreenchange", updateLabel);
    updateLabel();
  })();

  // ═══════════════════════════════════════════════════════════════
  // FULL-SCREEN LAUNCH SPLASH
  // Shows after sign-in (revealLobby adds .show). The Play button is the
  // user gesture browsers require to enter true full screen. The slim resume
  // pill appears if the player drops out of full screen after opting in.
  // ═══════════════════════════════════════════════════════════════
  (function setupGameWindowFullscreen() {
    const splash   = document.getElementById("cc-fs-splash");
    const playBtn  = document.getElementById("ccfs-play");
    const winBtn   = document.getElementById("ccfs-window");
    const resume   = document.getElementById("cc-fs-resume");
    const statusEl = document.getElementById("ccfs-status");
    if (!splash || !playBtn || !winBtn || !resume) return;

    let wantsFullscreen = false;
    const isFs = () => Boolean(document.fullscreenElement || document.webkitFullscreenElement);
    function setFsStatus(msg) {
      if (statusEl) statusEl.textContent = msg || "";
    }
    async function enterFs() {
      const el = document.documentElement;
      try {
        if (el.requestFullscreen) await el.requestFullscreen();
        else if (el.webkitRequestFullscreen) await el.webkitRequestFullscreen();
        return isFs();
      } catch (e) {
        ccReport("fullscreen_request_failed", {
          error: e && (e.name || e.message || e)
        }, "warn");
        return false;
      }
    }

    playBtn.addEventListener("click", async () => {
      wantsFullscreen = true;
      document.body.classList.add("cc-fullscreen-wanted");
      setFsStatus("Opening full screen…");
      const ok = await enterFs();
      if (ok) {
        setFsStatus("");
        splash.classList.remove("ccfs-blocked");
        splash.classList.remove("show");
        try { sessionStorage.setItem("cc_fs_splash_dismissed", "1"); } catch (_) {}
      } else {
        // Reveal the "Continue in this window" fallback only now that the
        // browser actually refused full screen, so the splash otherwise stays
        // true to the artwork.
        splash.classList.add("ccfs-blocked");
        setFsStatus("Your browser blocked full screen. Try again, or continue in this window.");
      }
    });
    winBtn.addEventListener("click", () => {
      wantsFullscreen = false;
      document.body.classList.remove("cc-fullscreen-wanted");
      setFsStatus("");
      splash.classList.remove("show");
      try { sessionStorage.setItem("cc_fs_splash_dismissed", "1"); } catch (_) {}
    });
    resume.addEventListener("click", async () => {
      const ok = await enterFs();
      if (!ok) try { showToast("Full screen was blocked — tap the button again.", "warn"); } catch (_) {}
    });

    function onFsChange() {
      if (wantsFullscreen && !isFs()) resume.classList.add("show");
      else resume.classList.remove("show");
    }
    document.addEventListener("fullscreenchange", onFsChange);
    document.addEventListener("webkitfullscreenchange", onFsChange);
  })();

  // ═══════════════════════════════════════════════════════════════
  // TOUCH-DRAG SHIM  (the Mobile control system)
  // The whole game drives card placement with native HTML5 drag-and-drop,
  // which a finger cannot trigger. When the player chose Mobile
  // (body.cc-device-mobile) this turns single-finger gestures on any
  // draggable card into the EXACT drag/drop events the game already listens
  // for (dragstart → dragenter/dragover/dragleave → drop → dragend), carrying
  // one shared DataTransfer so every existing setData/getData keeps working.
  // So in Mobile mode you can drag cards with your finger, and a plain tap
  // still falls through to the existing tap-to-place handlers. Computer mode
  // is never touched — it keeps native mouse drag-and-drop.
  // ═══════════════════════════════════════════════════════════════
  (function setupTouchDrag() {
    const MOVE_THRESHOLD = 8; // px before a touch becomes a drag (taps fall through)
    let src = null, dt = null, started = false, lastTarget = null, ghost = null;
    let startX = 0, startY = 0, touchId = null;

    const mobileActive = () =>
      document.body && document.body.classList.contains("cc-device-mobile");

    function closestDraggable(el) {
      while (el && el !== document.body) {
        if (el.draggable === true || (el.getAttribute && el.getAttribute("draggable") === "true")) return el;
        el = el.parentElement;
      }
      return null;
    }

    function makeDT() {
      try { return new DataTransfer(); } catch (e) {}
      // Fallback for browsers without a constructable DataTransfer.
      let store = {};
      return {
        dropEffect: "move", effectAllowed: "all", types: [],
        setData(t, v) { store[t] = String(v); },
        getData(t) { return store[t] || ""; },
        clearData(t) { if (t) delete store[t]; else store = {}; },
        setDragImage() {}
      };
    }

    function fire(type, target, x, y) {
      if (!target) return;
      let ev;
      try {
        ev = new DragEvent(type, { bubbles: true, cancelable: true, composed: true, dataTransfer: dt, clientX: x, clientY: y });
      } catch (e) {
        ev = document.createEvent("Event");
        ev.initEvent(type, true, true);
        ev.clientX = x; ev.clientY = y;
      }
      // Browsers null out dataTransfer on synthetic events — force ours so the
      // game's setData/getData calls hit the one shared object.
      if (ev.dataTransfer !== dt) {
        try { Object.defineProperty(ev, "dataTransfer", { value: dt, configurable: true }); } catch (e) {}
      }
      target.dispatchEvent(ev);
    }

    function makeGhost(el, x, y) {
      try {
        const r = el.getBoundingClientRect();
        ghost = el.cloneNode(true);
        ghost.classList.add("cc-touch-ghost");
        ghost.style.cssText =
          "position:fixed;left:0;top:0;margin:0;pointer-events:none;z-index:2147483600;opacity:.85;" +
          "width:" + r.width + "px;height:" + r.height + "px;box-shadow:0 8px 24px rgba(0,0,0,.45);transition:none;";
        ghost._w = r.width; ghost._h = r.height;
        moveGhost(x, y);
        document.body.appendChild(ghost);
      } catch (e) { ghost = null; }
    }
    function moveGhost(x, y) {
      if (ghost) ghost.style.transform = "translate(" + (x - ghost._w / 2) + "px," + (y - ghost._h / 2) + "px)";
    }
    function killGhost() { if (ghost && ghost.parentNode) ghost.parentNode.removeChild(ghost); ghost = null; }
    function reset() { src = null; dt = null; started = false; lastTarget = null; touchId = null; killGhost(); }

    function touchById(list) {
      for (let i = 0; i < list.length; i++) if (list[i].identifier === touchId) return list[i];
      return null;
    }

    document.addEventListener("touchstart", (e) => {
      if (src || !mobileActive() || e.touches.length !== 1) return;
      const t = e.touches[0];
      const d = closestDraggable(t.target);
      if (!d) return;
      src = d; startX = t.clientX; startY = t.clientY; started = false; touchId = t.identifier;
      // Do NOT preventDefault yet — a short press should still tap (place) or scroll.
    }, { passive: true });

    document.addEventListener("touchmove", (e) => {
      if (!src) return;
      const t = touchById(e.changedTouches);
      if (!t) return;
      const dx = t.clientX - startX, dy = t.clientY - startY;
      if (!started) {
        if (Math.abs(dx) < MOVE_THRESHOLD && Math.abs(dy) < MOVE_THRESHOLD) return; // still a tap/scroll
        started = true;
        dt = makeDT();
        fire("dragstart", src, t.clientX, t.clientY);
        makeGhost(src, t.clientX, t.clientY);
      }
      e.preventDefault(); // own the gesture now (no page scroll while dragging)
      moveGhost(t.clientX, t.clientY);
      const over = document.elementFromPoint(t.clientX, t.clientY); // ghost is pointer-events:none
      if (over !== lastTarget) {
        if (lastTarget) fire("dragleave", lastTarget, t.clientX, t.clientY);
        if (over) fire("dragenter", over, t.clientX, t.clientY);
        lastTarget = over;
      }
      if (over) fire("dragover", over, t.clientX, t.clientY);
    }, { passive: false });

    function endHandler(e) {
      if (!src) return;
      const t = touchById(e.changedTouches);
      if (!started) { reset(); return; } // was a tap — let the native click / tap-to-place run
      if (t) {
        const over = document.elementFromPoint(t.clientX, t.clientY);
        if (over) { fire("dragover", over, t.clientX, t.clientY); fire("drop", over, t.clientX, t.clientY); }
      }
      fire("dragend", src, t ? t.clientX : startX, t ? t.clientY : startY);
      e.preventDefault(); // swallow the post-drag synthetic click so it can't re-fire tap-to-place
      reset();
    }
    document.addEventListener("touchend", endHandler, { passive: false });
    document.addEventListener("touchcancel", () => {
      if (started && src) fire("dragend", src, startX, startY);
      reset();
    }, { passive: false });
  })();

  // ═══════════════════════════════════════════════════════════════
  // IN-GAME BOARD SIZE CONTROL  (+ / − buttons, and + = - keys)
  // Zooms ONLY the board (#pv-table-inner) — never the hand, action bar,
  // End Turn / Undo buttons, or the rest of the website. Clamped so the
  // board can't be zoomed too far in (cut-off) or too far out (broken/tiny).
  // ═══════════════════════════════════════════════════════════════
  const _BS_MIN = 0.7, _BS_MAX = 1.5, _BS_STEP = 0.1, _BS_KEY = "cc_board_zoom";
  // Board zoom ALWAYS starts at 100% for every player on every load — a saved
  // zoom is never restored, so the board can never come up zoomed in/out from a
  // previous session. Players can still zoom with the +/- control during a match
  // (that change lives only for the current session). Any stale value saved by
  // an older build is cleared here so it can never take effect again.
  let _boardZoom = 1;
  try { localStorage.removeItem(_BS_KEY); } catch {}

  function applyBoardZoom() {
    _boardZoom = Math.min(_BS_MAX, Math.max(_BS_MIN, Math.round(_boardZoom * 10) / 10));
    try { document.documentElement.style.setProperty("--board-zoom", String(_boardZoom)); } catch {}
    const table = document.getElementById("pv-table");
    if (table) table.classList.toggle("pv-table-zoomed", _boardZoom > 1.001);
    const readout = document.getElementById("bs-readout");
    if (readout) readout.textContent = Math.round(_boardZoom * 100) + "%";
    const plus  = document.getElementById("bs-plus");
    const minus = document.getElementById("bs-minus");
    if (plus)  plus.disabled  = _boardZoom >= _BS_MAX - 0.001;
    if (minus) minus.disabled = _boardZoom <= _BS_MIN + 0.001;
    // Intentionally NOT persisted — board zoom resets to 100% on every load.
  }

  function boardZoomBy(delta) {
    const before = _boardZoom;
    _boardZoom = Math.min(_BS_MAX, Math.max(_BS_MIN, Math.round((_boardZoom + delta) * 10) / 10));
    if (_boardZoom !== before) applyBoardZoom();
  }

  // Only treat the game as "active" (controls visible / keys live) when the
  // game screen is actually on-screen.
  function _bsGameActive() {
    const g = document.getElementById("pv-game");
    return Boolean(g) && g.style.display !== "none" && g.style.display !== "";
  }

  window._bsSetVisible = function(visible) {
    // Switch the mobile game viewport on entering / leaving the in-game screen
    // (no-op on desktop). Done first so it runs even if the bs-ctrl is absent.
    try { window.ccGameViewport && window.ccGameViewport(visible); } catch {}
    const ctrl = document.getElementById("bs-ctrl");
    if (!ctrl) return;
    ctrl.style.display = visible ? "flex" : "none";
    if (visible) applyBoardZoom();
  };

  (function setupBoardSizeControl() {
    const plus  = document.getElementById("bs-plus");
    const minus = document.getElementById("bs-minus");
    if (plus)  plus.addEventListener("click",  () => boardZoomBy(+_BS_STEP));
    if (minus) minus.addEventListener("click", () => boardZoomBy(-_BS_STEP));

    // Keyboard: + or = zoom in, - or _ zoom out — only inside a game, and
    // never when typing. Bare keys only — Cmd/Ctrl +/- stay browser zoom.
    document.addEventListener("keydown", (e) => {
      if (e.ctrlKey || e.metaKey || e.altKey) return;     // leave browser zoom alone
      if (!_bsGameActive()) return;
      const t = e.target;
      if (t && (t.isContentEditable ||
                /^(INPUT|TEXTAREA|SELECT)$/.test(t.tagName || ""))) return;
      const k = e.key;
      if (k === "+" || k === "=") { boardZoomBy(+_BS_STEP); e.preventDefault(); }
      else if (k === "-" || k === "_") { boardZoomBy(-_BS_STEP); e.preventDefault(); }
    });

    applyBoardZoom(); // initialise the CSS var + readout at 100%
  })();

  // ═══════════════════════════════════════════════════════════════
  // SURF'S UP!! AWAY SYSTEM + INACTIVITY TIMER
  // ═══════════════════════════════════════════════════════════════
  let _imAway = false;
  let _wasAway = false; // for detecting away→active transition (welcome-back toast)
  // The automatic 5-minute idle "Are you there?" timer has been REMOVED. Players
  // are no longer auto-flagged inactive just for taking a while on their turn.
  // AFK is now handled solely by the chat-vote system (type "<player> is AFK" /
  // "<player> away"). These declarations + no-op stubs remain so the existing
  // callers (state sync, Surf's Up handler, game cleanup) keep working unchanged.
  let _idleTimer = null;
  let _serverInactiveEligibleSent = false;

  function _isMyTurnNow() {
    try {
      const aas = latestPayload?.active_action_seat;
      return Number.isInteger(aas) && Number.isInteger(myIdx) && aas === myIdx;
    } catch { return false; }
  }

  function _hideIdleWarn() { /* idle warning removed — no-op */ }
  async function _clearServerInactive() { /* idle auto-flagging removed — no-op */ }
  function resetIdleTimer() { /* idle timer removed — no-op */ }

  // Surf's Up!! button
  let _surfBtnInFlight = false;
  document.getElementById("pv-surf-btn")?.addEventListener("click", async () => {
    if (!roomId) return;
    if (_surfBtnInFlight) return;

    // Resolve the correct seat token — competitive mode may have a token per seat
    let token;
    if (typeof compMode !== "undefined" && compMode) {
      // Use whichever of my seats is currently active, fall back to first
      const activeNum = typeof myIdx === "number" ? myIdx : null;
      token = (activeNum !== null && compTokens && compTokens[activeNum])
        ? compTokens[activeNum]
        : (compTokens && compMySeats && compTokens[compMySeats[0]]) || getSeatToken();
    } else {
      token = getSeatToken();
    }

    if (!token) {
      try { showToast("No seat token — re-join the game first.", "err"); } catch {}
      return;
    }

    const want = !_imAway;
    const btn = document.getElementById("pv-surf-btn");
    _surfBtnInFlight = true;
    if (btn) { btn.disabled = true; btn.style.opacity = "0.6"; }
    try {
      const r = await apiPost(`/api/rooms/${roomId}/away`, { seat_token: token, away: want }, { timeoutMs: 10000 });
      if (r?.data?.ok) {
        _imAway = Boolean(r.data.is_away);
        _updateSurfBtnLabel();
        if (_imAway) {
          _hideIdleWarn();
          _clearServerInactive();
        } else {
          resetIdleTimer();
        }
        refreshState();
      } else {
        try { showToast(r?.data?.error || "Surf's Up!! request failed — try again.", "warn"); } catch {}
      }
    } catch (e) {
      try { showToast("Could not reach server — check your connection.", "err"); } catch {}
    } finally {
      _surfBtnInFlight = false;
      if (btn) { btn.disabled = false; btn.style.opacity = ""; }
    }
  });

  function _updateSurfBtnLabel() {
    const btn = document.getElementById("pv-surf-btn");
    if (!btn) return;
    btn.classList.toggle("is-away", _imAway);
    btn.innerHTML = _imAway ? "🌊 I'm Back" : "🏄 Surf's Up!!";
    btn.title = _imAway
      ? "You're Away — you can't play any moves. Tap to come back and resume your turn."
      : "Surf's Up!! — mark yourself officially Away. The table waits for you and no one can report you AFK. While Away you can't play any moves — tap 'I'm Back' to return.";
  }
  _updateSurfBtnLabel();

  function _showWelcomeBackToast(message) {
    const t = document.getElementById("pv-welcome-back-toast");
    if (!t) return;
    t.textContent = message;
    t.classList.add("visible");
    clearTimeout(t._hideTo);
    t._hideTo = setTimeout(() => t.classList.remove("visible"), 6000);
  }

  async function drawForInactive(targetSeatIndex, targetName) {
    if (!roomId) return;
    const token = getSeatToken();
    if (!token) return;
    try {
      const r = await apiPost(`/api/rooms/${roomId}/draw_for_inactive`,
        { seat_token: token, target_seat_index: targetSeatIndex }, { timeoutMs: 8000 });
      if (!r?.data?.ok) {
        try { showToast(r?.data?.error || `Could not draw for ${targetName || "player"}.`, "warn"); } catch {}
      }
      refreshState();
    } catch (e) {}
  }
  window._fishDrawForInactive = drawForInactive;

  // ═══════════════════════════════════════════════════════════════
  // AFK-VOTE CHALLENGE — "Are you still here?" popup for the active player
  // ═══════════════════════════════════════════════════════════════
  let _afkOpen = false;
  let _afkTicker = null;
  let _afkEndsAt = 0;
  let _afkCancelInFlight = false;
  let _afkSuppressUntil = 0;  // bridge the poll gap after a cancel so it can't re-open
  let _afkForced = false;     // true when AFK timer ran out without any player interaction
  const AFK_TOTAL_SEC = 20;

  function _afkRingColor(frac) {
    // frac: 1 = full time left (teal), 0 = out of time (red). Teal→gold→red.
    if (frac > 0.5)  return "#18C8A8"; // --teal
    if (frac > 0.25) return "#F0C840"; // --gold
    return "#ef6a6a";                  // urgent red
  }

  function _afkPaint() {
    const ring = document.getElementById("pv-afk-ring");
    const cd   = document.getElementById("pv-afk-countdown");
    if (!ring || !cd) return;
    const leftMs = Math.max(0, _afkEndsAt - Date.now());
    const secs   = Math.ceil(leftMs / 1000);
    const frac   = Math.max(0, Math.min(1, leftMs / (AFK_TOTAL_SEC * 1000)));
    cd.textContent = String(secs);
    const secNum = document.getElementById("pv-afk-seconds-num");
    if (secNum) secNum.textContent = String(secs);
    ring.style.setProperty("--pct", (frac * 100).toFixed(1) + "%");
    ring.style.setProperty("--ring", _afkRingColor(frac));
    ring.classList.toggle("urgent", frac <= 0.3);
    if (leftMs <= 0) {
      // Time's up on the client — the server resolves authoritatively and the
      // next poll will clear the challenge. Stop the local ticker.
      if (_afkTicker) { clearInterval(_afkTicker); _afkTicker = null; }
      // Player did not interact before timer expired: mark as forced so undo is blocked.
      _afkForced = true;
    }
  }

  function _showAfkChallenge(remainingSec) {
    const modal = document.getElementById("pv-afk-modal");
    if (!modal) return;
    // Anchor the end time once when the popup first opens; later polls don't
    // restart the countdown (avoids the timer "jumping" each refresh).
    if (!_afkOpen) {
      const rem = (typeof remainingSec === "number" && remainingSec > 0)
        ? Math.min(AFK_TOTAL_SEC, remainingSec) : AFK_TOTAL_SEC;
      _afkEndsAt = Date.now() + rem * 1000;
      _afkOpen = true;
      modal.classList.add("open");
      _afkPaint();
      if (_afkTicker) clearInterval(_afkTicker);
      _afkTicker = setInterval(_afkPaint, 120);
    }
  }

  function _hideAfkChallenge() {
    if (!_afkOpen) return;
    _afkOpen = false;
    if (_afkTicker) { clearInterval(_afkTicker); _afkTicker = null; }
    const modal = document.getElementById("pv-afk-modal");
    if (modal) modal.classList.remove("open");
  }

  async function _cancelAfkChallenge() {
    if (!_afkOpen || _afkCancelInFlight) return;
    _afkCancelInFlight = true;
    _afkForced = false;   // player was active — undo stays available
    _afkSuppressUntil = Date.now() + 4000;  // don't let a stale poll re-open it
    _hideAfkChallenge();  // optimistic close — feels instant on interaction
    try {
      let token;
      if (typeof compMode !== "undefined" && compMode) {
        const activeNum = typeof myIdx === "number" ? myIdx : null;
        token = (activeNum !== null && compTokens && compTokens[activeNum])
          ? compTokens[activeNum]
          : (compTokens && compMySeats && compTokens[compMySeats[0]]) || getSeatToken();
      } else {
        token = getSeatToken();
      }
      if (token && roomId) {
        await apiPost(`/api/rooms/${roomId}/afk_cancel`, { seat_token: token }, { timeoutMs: 6000 });
      }
      refreshState();
    } catch (e) {
    } finally {
      _afkCancelInFlight = false;
    }
  }

  // Any interaction inside the game cancels the AFK check (only while open).
  ["click","mousedown","mousemove","keydown","touchstart","wheel"].forEach(ev =>
    window.addEventListener(ev, () => { if (_afkOpen) { try { _cancelAfkChallenge(); } catch {} } }, { passive: true })
  );

  // ── Auto-join from URL ─────────────────────────────────────────
  (function() {
    const urlRoom = roomFromUrl();
    if (!urlRoom) return;
    const params = new URLSearchParams(location.search);
    const urlSeat = params.get("seat_token");
    const urlHost = params.get("host_token");
    roomId = urlRoom;
    if (urlSeat) setSeatToken(urlSeat);
    if (urlHost) setHostToken(urlHost);
    if (getSeatToken() || getHostToken()) {
      // already have a token — go straight in
      enterRoom(urlRoom);
    } else {
      // Check localStorage for a fresh rejoin token (saved within the last 5 minutes)
      const rejoinToken = loadRejoinToken(urlRoom);
      if (rejoinToken) {
        setSeatToken(rejoinToken); // restore to sessionStorage for this tab
        showToast("Rejoining your game…", "ok");
        enterRoom(urlRoom);
      } else {
        // no token — show seat picker modal so they can pick + join
        loadInvitedSeats(urlRoom);
      }
    }
  })();

  // Keep server warm
  function pingServer() { fetch(window.__FISH_API_BASE__+"/api/health",{method:"GET",cache:"no-store"}).catch(()=>{}); }
  pingServer();
  setInterval(pingServer, 4*60*1000); // ping every 4 min to prevent Render free-tier sleep

