  const EXCLUSIVE_BACKGROUNDS = [
    { id:"bg-kelp",           name:"Kelp Forest",      img:"/backgrounds/bg-kelp.png",            facts:"Golden kelp swaying in sunlit green water." },
    { id:"bg-coral-reef",     name:"Coral Reef",       img:"/backgrounds/bg-coral-reef.png",      facts:"A vivid coral garden bursting with color." },
    { id:"bg-artificial-reef",name:"Artificial Reef",  img:"/backgrounds/bg-artificial-reef.png", facts:"A sunken structure reclaimed by the sea." },
    { id:"bg-tide-pool",      name:"Tide Pool",        img:"/backgrounds/bg-tide-pool.png",       facts:"A shimmering rocky pool left by the tide." },
    { id:"bg-arctic",         name:"Arctic Ocean",     img:"/backgrounds/bg-arctic.png",          facts:"Icy blue water beneath drifting floes." },
    { id:"bg-deep",           name:"Deep Ocean",       img:"/backgrounds/bg-deep.png",            facts:"The dark, mysterious open deep." },
    { id:"bg-pier",           name:"Pier",             img:"/backgrounds/bg-pier.png",            facts:"Pilings and dappled light under the dock." },
    { id:"bg-mangrove",       name:"Mangrove",         img:"/backgrounds/bg-mangrove.png",        facts:"Tangled roots mirrored in warm, shallow water." },
  ];
  const _BG_BY_ID  = Object.fromEntries(EXCLUSIVE_BACKGROUNDS.map(b => [b.id, b]));
  const _BG_BY_IMG = Object.fromEntries(EXCLUSIVE_BACKGROUNDS.map(b => [b.img, b]));
  function backgroundById(id){ return _BG_BY_ID[id] || null; }
  function normalizeBgUrl(u){
    let s = String(u||"").trim();
    if (!s) return "";
    const i = s.indexOf("/backgrounds/");
    if (i >= 0) s = s.slice(i);
    s = s.split("?")[0];
    return s.startsWith("/backgrounds/") ? s : "";
  }
  // Competitive rank tier ordering (Unranked < Bronze < Silver < Gold < Diamond < Emerald < King).
  function rankTierValue(rankName){
    const n = String(rankName||"").trim().toLowerCase();
    if (!n || n === "unranked") return 0;
    if (n.startsWith("bronze"))  return 1;
    if (n.startsWith("silver"))  return 2;
    if (n.startsWith("gold"))    return 3; // "Golden Grouper …"
    if (n.startsWith("diamond")) return 4;
    if (n.startsWith("emerald")) return 5;
    if (n.startsWith("king"))    return 6;
    return 0;
  }
  const _RANK_TIER_VALUE = { bronze:1, silver:2, gold:3, golden:3, diamond:4, emerald:5, king:6 };
  // Lowercased names of every Game Fish species (for the Sailfish board check).
  const GAME_FISH_NAMES = ANIMAL_AVATARS.filter(a => a.species === "Game Fish").map(a => a.name.toLowerCase());
  const DEFAULT_AVATAR_IMG = "/avatars/mullet.png";
  const _animalByImg = {}, _animalById = {};
  ANIMAL_AVATARS.forEach(a => { _animalByImg[a.img] = a; _animalById[a.id] = a; });
  function animalByImg(img){ return _animalByImg[String(img||"").trim().toLowerCase()] || null; }
  function animalById(id){ return _animalById[id] || null; }
  function animalFacts(a){ return (a && a.facts) ? a.facts : "Fun facts coming soon."; }
  // Numeric unlock progress (0..1) for stat-based animals; null for event/achievement.
  function animalUnlockProgress(a, stats, level){
    const u = a && a.unlock; if (!u) return null;
    if (u.type === "starter")   return 1;
    if (u.type === "level")     return Math.min(1, Number(level||0) / (u.goal||1));
    if (u.type === "comp_wins") return Math.min(1, Number(stats?.lifetime_comp_wins||0) / (u.goal||1));
    if (u.type === "stat")      return Math.min(1, Number(stats?.[u.stat]||0) / (u.goal||1));
    if (u.type === "rank")      return Math.min(1, rankTierValue(stats?.rank_competitive) / (_RANK_TIER_VALUE[u.tier]||1));
    if (u.type === "achievement" && u.achId && u.goal) {
      const achs = (typeof window.__fishGetUserAchievements === "function") ? window.__fishGetUserAchievements() : {};
      const rec = achs[u.achId] || {};
      if (rec.completed) return 1;
      const cur = Number(rec.progress || 0);
      return Math.min(1, cur / u.goal);
    }
    // Events and secrets: return null (no numeric progress bar — shown as "Complete the challenge")
    return null;
  }
  function animalProgressText(a, stats, level){
    const u = a && a.unlock; if (!u) return "";
    if (u.type === "level")     return `Level ${Number(level||0)} / ${u.goal}`;
    if (u.type === "comp_wins") return `${Number(stats?.lifetime_comp_wins||0)} / ${u.goal} Competitive wins`;
    if (u.type === "stat")      return `${Number(stats?.[u.stat]||0)} / ${u.goal}${u.unit ? " " + u.unit : ""}`;
    if (u.type === "rank")      return `Current rank: ${stats?.rank_competitive || "Unranked"}`;
    if (u.type === "achievement" && u.achId && u.goal) {
      const achs = (typeof window.__fishGetUserAchievements === "function") ? window.__fishGetUserAchievements() : {};
      const rec = achs[u.achId] || {};
      if (rec.completed) return "✓ Achievement completed!";
      const cur = Number(rec.progress || 0);
      const goal = u.goal;
      if (goal === 1) return cur > 0 ? "In progress — finish the challenge to unlock" : "Not yet achieved";
      return `${cur} / ${goal} qualifying wins`;
    }
    return "";
  }

  // ── Animal unlock screen queue (shown on return to the home menu) ──
  let _pendingAnimalUnlocks = [];
  let _animalUnlockShowing = false;
  let _animalUnlockAutoTimer = null;
  function _queueAnimalUnlock(id){
    if (id && animalById(id) && !_pendingAnimalUnlocks.includes(id)) _pendingAnimalUnlocks.push(id);
    // Flag this avatar as "New" for the Avatar Gallery until the player views it.
    if (id) {
      try {
        const k = "cc_new_avatars";
        const s = new Set(JSON.parse(localStorage.getItem(k) || "[]"));
        s.add(id);
        localStorage.setItem(k, JSON.stringify([...s]));
      } catch {}
      // Ring the notification bell so the player can click straight to the animal.
      const a = animalById(id);
      window.__fishNotifPushAnimal?.(id, a ? a.name : id);
    }
    // Show the unlock popup IMMEDIATELY (debounced so several grants earned in
    // the same moment queue up and then display one-by-one). This is what makes
    // an avatar appear the instant it's earned DURING a game, with the Equip
    // Now button, instead of only after the game ends. _showNextAnimalUnlock is
    // guarded by _animalUnlockShowing so this can never double-open.
    clearTimeout(_animalUnlockAutoTimer);
    _animalUnlockAutoTimer = setTimeout(() => { try { _showNextAnimalUnlock(); } catch {} }, 700);
  }
  function _showNextAnimalUnlock(){
    if (_animalUnlockShowing) return;
    const ov = document.getElementById("animal-unlock-overlay");
    if (!ov) return;
    const id = _pendingAnimalUnlocks.shift();
    if (!id) return;
    const a = animalById(id);
    if (!a) { _showNextAnimalUnlock(); return; }
    _animalUnlockShowing = true;
    ov._currentAnimal = a;
    const img = document.getElementById("au-animal-img");
    if (img) { img.src = a.img; img.alt = a.name; }
    const nm = document.getElementById("au-animal-name");   if (nm) nm.textContent = a.name;
    const sp = document.getElementById("au-animal-species"); if (sp) sp.textContent = a.species || "";
    const fc = document.getElementById("au-animal-facts");   if (fc) fc.textContent = animalFacts(a);
    const ht = document.getElementById("au-animal-howto");
    const htTxt = document.getElementById("au-animal-howto-text");
    if (ht) {
      const lbl = a.unlock && a.unlock.label;
      if (htTxt) htTxt.textContent = lbl || "";
      ht.style.display = lbl ? "" : "none";
    }
    ov.classList.add("open");
  }
  function _closeAnimalUnlock(){
    const ov = document.getElementById("animal-unlock-overlay");
    if (ov) { ov.classList.remove("open"); ov._currentAnimal = null; }
    _animalUnlockShowing = false;
    if (_pendingAnimalUnlocks.length) setTimeout(_showNextAnimalUnlock, 350);
  }
  (function wireAnimalUnlockButtons(){
    const yes = document.getElementById("au-btn-yes");
    const no  = document.getElementById("au-btn-no");
    if (yes) yes.addEventListener("click", async () => {
      const ov = document.getElementById("animal-unlock-overlay");
      const a = ov && ov._currentAnimal;
      if (a && typeof window.__fishEquipAvatar === "function") {
        try { await window.__fishEquipAvatar(a.img); } catch {}
      }
      _closeAnimalUnlock();
    });
    if (no) no.addEventListener("click", () => _closeAnimalUnlock());
  })();
  window.__fishQueueAnimalUnlock = _queueAnimalUnlock;
  window.__fishShowAnimalUnlocks = () => { if (_pendingAnimalUnlocks.length) _showNextAnimalUnlock(); };

