  // ── Avatar / Achievement integrity validation ──────────────────────
  // Confirms every avatar and achievement is well-formed and that every
  // avatar↔achievement reward mapping resolves. Returns a list of problems
  // (empty = healthy). Logged once on load; callable from the console as
  // window.__fishValidateAvatars().
  function validateAvatarAchievementSystem() {
    const problems = [];
    const avIds = new Set(), avImgs = new Set(), achIds = new Set();
    // Achievements: ids unique, required fields present.
    (ACHIEVEMENT_DEFS || []).forEach(d => {
      if (!d || !d.id) { problems.push("achievement missing id: " + JSON.stringify(d)); return; }
      if (achIds.has(d.id)) problems.push("duplicate achievement id: " + d.id);
      achIds.add(d.id);
      if (!d.name) problems.push("achievement " + d.id + " missing name");
      if (typeof d.xp !== "number") problems.push("achievement " + d.id + " missing/!number xp");
    });
    // Avatars: ids/images unique, required fields, and unlock mapping resolves.
    (ANIMAL_AVATARS || []).forEach(a => {
      if (!a || !a.id) { problems.push("avatar missing id: " + JSON.stringify(a)); return; }
      if (avIds.has(a.id)) problems.push("duplicate avatar id: " + a.id);
      avIds.add(a.id);
      if (!a.name) problems.push("avatar " + a.id + " missing name");
      if (!a.img || !/^\/avatars\/.+\.png$/i.test(String(a.img))) problems.push("avatar " + a.id + " bad image path: " + a.img);
      if (avImgs.has(a.img)) problems.push("duplicate avatar image: " + a.img + " (" + a.id + ")");
      avImgs.add(a.img);
      if (!a.species) problems.push("avatar " + a.id + " missing species/category");
      if (!a.unlock || !a.unlock.type) problems.push("avatar " + a.id + " missing unlock requirement");
      else if (a.unlock.type === "achievement") {
        if (!a.unlock.achId) problems.push("avatar " + a.id + " achievement-unlock missing achId");
        else if (!achIds.has(a.unlock.achId)) problems.push("avatar " + a.id + " points to MISSING achievement: " + a.unlock.achId);
      }
    });
    // Every strategy-master achievement (STRAT_TO_ACH) maps to a real achievement.
    return problems;
  }
  window.__fishValidateAvatars = function () {
    const probs = validateAvatarAchievementSystem();
    if (probs.length) { console.warn("[avatar-validation] " + probs.length + " problem(s):", probs); }
    else console.info("[avatar-validation] OK — " + (ANIMAL_AVATARS || []).length + " avatars, " + (ACHIEVEMENT_DEFS || []).length + " achievements, all mappings resolve.");
    return probs;
  };
  // Run once on load (non-fatal).
  try { window.__fishValidateAvatars(); } catch (_) {}

