    // ── Leaderboard: delegated clicks → public profile + add friend ──
    (function() {
      const ALL_LB_TBODIES = ["ph-lb-xp-tbody","ph-lb-wins-tbody","ph-lb-casual-tbody","ph-lb-cp-tbody","ph-lb-single-tbody","ph-lb-combined-tbody"];
      ALL_LB_TBODIES.forEach(id => {
        const tb = $a(id);
        if (!tb) return;
        tb.addEventListener("click", async e => {
          // Add-friend button
          const addBtn = e.target.closest(".ph-lb-add-btn[data-add-uid]");
          if (addBtn) {
            e.stopPropagation();
            if (addBtn.disabled) return;
            const targetUid = addBtn.dataset.addUid;
            if (!targetUid || !_authUser) return;
            addBtn.disabled = true;
            addBtn.innerHTML = `<svg width="12" height="12" viewBox="0 0 12 12" fill="none"><circle cx="6" cy="6" r="5" stroke="currentColor" stroke-width="1.4" stroke-dasharray="2 2"/></svg>`;
            try {
              // Load the target's profile to get their friend code / nickname
              const tp = await loadProfile(targetUid);
              const code = tp?.friend_code || "";
              const nick = tp?.nickname || "";
              const input = code ? String(code) : nick;
              if (!input) { addBtn.innerHTML = "!"; return; }
              const res = await addFriend(_authUser.uid, input, _playerNickname);
              if (res.ok || res.requested || res.autoAccepted) {
                addBtn.classList.add("lb-add-sent");
                addBtn.innerHTML = _LB_ICON_FRIENDS;
                addBtn.title = res.autoAccepted ? "Now friends!" : "Request sent!";
                if (res.autoAccepted) { addBtn.classList.add("lb-add-friends"); _lbFriendUids.add(targetUid); }
              } else {
                addBtn.innerHTML = _LB_ICON_ADD;
                addBtn.disabled = false;
                addBtn.title = res.error || "Could not send request";
              }
            } catch { addBtn.innerHTML = _LB_ICON_ADD; addBtn.disabled = false; }
            return;
          }
          // Profile click (not the add-btn)
          const cell = e.target.closest(".ph-lb-player-cell.pub-clickable");
          if (!cell) return;
          const row = cell.closest("tr[data-uid]");
          if (!row || !row.dataset.uid) return;
          openPublicProfile(row.dataset.uid);
        });
      });
    })();

    // ── Startup ──────────────────────────────────────────────────
    (async function startAuth() {
      // FIRST SCREEN GATE: do not boot auth, lobby, or game until the
      // player has chosen Computer or Mobile. Resolves immediately when a
      // choice is already saved for this session. The chosen device's body
      // class / window.CC_* flags are applied before anything else runs.
      try { if (window.ccDeviceReady) await window.ccDeviceReady; } catch (_) {}

      if (!_auth) {
        const savedGuestNick = (localStorage.getItem(GUEST_NICK_KEY) || "").trim();
        const savedGuestAvatar = sanitizeSelectableAvatar(localStorage.getItem(GUEST_AVATAR_KEY) || "", savedGuestNick || "guest");
        if (savedGuestNick) {
          _guestAvatarUrl = savedGuestAvatar;
          if (IS_GAME_WINDOW()) {
            revealGuestLobbyGated(savedGuestNick);
          } else {
            // Launcher: returning guest — offer a one-click Open Game (no re-nick).
            _ccLaunchCtx = { type: "guest", nick: savedGuestNick, avatarUrl: savedGuestAvatar, gameUrl: ccGameUrl() };
            ccSetLaunchScreen("ready", { nick: savedGuestNick, avatarUrl: savedGuestAvatar });
          }
          return;
        }
        $a("auth-loading-screen").classList.add("hidden");
        showStep("auth-step-choose");
        setAuthMsg("auth-choose-err", "Sign-in is not configured on this server. You can still play as guest.", false);
        return;
      }

      // Firebase ready — wait for persisted auth state
      _auth.onAuthStateChanged(async (user) => {
        const authSeq = ++_authStateSeq;

        // ── LAUNCHER MODE ── Never reveal the lobby in the launcher tab; the
        // real game runs in the dedicated window. Just show the launch screen
        // (and route auth/onboarding into the game window).
        if (!IS_GAME_WINDOW()) {
          $a("auth-loading-screen").classList.add("hidden");
          if (user) {
            _authUser = user;
            _guestSessionActive = false;
            let nick = String(user.displayName || "").split(" ")[0] || "";
            let avatarUrl = "";
            try {
              const { profile, reason } = await loadProfileWithFallbacks(user);
              if (authSeq !== _authStateSeq) return;
              if (reason !== "error" && profile) {
                _activeProfile = profile;
                if (profile.nickname) nick = profile.nickname;
                _playerNickname = profile.nickname || "";
                _friendCode = profile.friend_code || "";
                avatarUrl = sanitizeSelectableAvatar(profile.avatar_url, user.uid) || "";
              }
            } catch (_) {}
            // Signed in on the launcher — go straight into the game in THIS tab
            // (the Firebase session carries over via this tab's sessionStorage).
            // No separate window, no "running" card.
            _ccLaunchCtx = { type: "google", nick, avatarUrl, gameUrl: ccGameUrl({ auth: "google" }) };
            ccLaunchFromLauncher(_ccLaunchCtx);
          } else {
            _authUser = null;
            const gNick = (localStorage.getItem(GUEST_NICK_KEY) || "").trim();
            if (gNick) {
              _guestAvatarUrl = sanitizeSelectableAvatar(localStorage.getItem(GUEST_AVATAR_KEY) || "", gNick);
              _ccLaunchCtx = { type: "guest", nick: gNick, avatarUrl: _guestAvatarUrl, gameUrl: ccGameUrl() };
              ccSetLaunchScreen("ready", { nick: gNick, avatarUrl: _guestAvatarUrl });
            } else {
              showStep("auth-step-choose");
            }
          }
          return;
        }

        // ── GAME WINDOW MODE ── full auth / onboarding / lobby logic ──
        if (user) {
          const prevUid = _authUser?.uid || "";
          if (prevUid && prevUid !== user.uid) {
            stopPresencePing(prevUid);
            if (_reqUnsubscribe) { _reqUnsubscribe(); _reqUnsubscribe = null; }
          }
          _authUser = user;
          _guestSessionActive = false;
          _playerNickname = "";
          _friendCode = "";
          _activeProfile = null;
          startHoursTimer(user.uid);

          // Load profile: tries UID → email → nickname, then retries on error.
          // NEVER creates a new account or shows a wrong name on any error.
          let { profile, reason } = await loadProfileWithFallbacks(user);
          // Retry up to 3 times with backoff if Firestore is temporarily unavailable
          for (let attempt = 1; reason === "error" && attempt <= 3; attempt++) {
            const delay = attempt * 1500;
            console.log(`[auth] Retry ${attempt}/3 in ${delay}ms…`);
            await new Promise(r => setTimeout(r, delay));
            if (authSeq !== _authStateSeq || !_authUser || _authUser.uid !== user.uid) return;
            ({ profile, reason } = await loadProfileWithFallbacks(user));
          }
          if (authSeq !== _authStateSeq || !_authUser || _authUser.uid !== user.uid) return;

          // Firestore still unreachable after 3 retries — show a recoverable error.
          // Do NOT create a "Player" profile. Do NOT overwrite anything.
          if (reason === "error") {
            console.error("[auth] Firestore unavailable after 3 retries — showing retry screen");
            $a("auth-loading-screen").classList.add("hidden");
            showStep("auth-step-choose");
            setAuthMsg("auth-choose-err",
              "Could not load your profile. Please check your connection and try signing in again.", false);
            return;
          }

          _activeProfile = profile || null;
          // Load unlocked animal icons before judging avatar validity.
          _unlockedIcons = Array.isArray(profile?.unlocked_icons)
            ? profile.unlocked_icons.filter(s => typeof s === "string" && s.startsWith("/avatars/"))
            : [];
          _unlockedBackgrounds = Array.isArray(profile?.unlocked_backgrounds)
            ? profile.unlocked_backgrounds.map(s => normalizeBgUrl(s)).filter(Boolean)
            : [];
          // One-time achievement system v2 reset (clears old unlocks + XP).
          try { await runAchievementResetIfNeeded(user.uid, _activeProfile); } catch {}
          $a("auth-loading-screen").classList.add("hidden");

          const hasNickname = hasStoredNickname(profile);
          const hasAvatar = hasStoredSelectableAvatar(profile);
          if (hasNickname && hasAvatar) {
            _pendingOnboardingUid = "";
            revealRegisteredLobbyGated(profile.nickname, profile.friend_code || "", profile, user);
          } else {
            const sl = $a("auth-stats-lobby");
            if (sl) sl.classList.remove("visible");
            const bar = $a("auth-profile-bar");
            if (bar) bar.style.display = "none";
            _pendingOnboardingUid = user.uid;
            if (!hasNickname) {
              // New account (doc doesn't exist): must choose nickname first.
              const hint = (user.displayName || "").split(" ")[0].slice(0, 15);
              const nickInput = $a("auth-nick-input");
              if (nickInput && hint) nickInput.value = hint;
              _signupAvatarUrl = sanitizeSelectableAvatar(profile?.avatar_url, user.uid || user.email || hint || "player");
              showStep("auth-step-nickname");
            } else {
              // Existing account whose stored avatar is no longer valid: silently default to Mullet.
              _playerNickname = String(profile.nickname || "").trim();
              _friendCode = profile?.friend_code ? String(profile.friend_code).trim() : "";
              _activeProfile = { ...(profile || {}), uid: user.uid, avatar_url: DEFAULT_AVATAR_IMG };
              try { await applyAvatarSelection(DEFAULT_AVATAR_IMG); } catch {}
              _pendingOnboardingUid = "";
              revealRegisteredLobbyGated(profile.nickname, profile.friend_code || "", profile, user);
            }
          }
        } else {
          if (_authUser?.uid) stopPresencePing(_authUser.uid);
          if (_reqUnsubscribe) { _reqUnsubscribe(); _reqUnsubscribe = null; }
          stopHoursTimer();
          _authUser = null;
          _activeProfile = null;
          _playerNickname = "";
          _friendCode = "";
          _pendingOnboardingUid = "";
          const savedGuestNick = (localStorage.getItem(GUEST_NICK_KEY) || "").trim();
          const savedGuestAvatar = sanitizeSelectableAvatar(localStorage.getItem(GUEST_AVATAR_KEY) || "", savedGuestNick || "guest");
          _avatarPromptShownForUid = "";
          setStatsAvatarClickable(false);
          $a("auth-loading-screen").classList.add("hidden");
          if (savedGuestNick) {
            _guestAvatarUrl = savedGuestAvatar;
            try {
              const _uiKey = GUEST_UNLOCKED_ICONS_PREFIX + savedGuestNick.toLowerCase();
              const _uiRaw = localStorage.getItem(_uiKey);
              if (_uiRaw) _unlockedIcons = JSON.parse(_uiRaw).filter(s => typeof s === "string" && s.startsWith("/avatars/"));
            } catch { _unlockedIcons = []; }
            revealGuestLobbyGated(savedGuestNick);
          } else {
            // Not signed in in this window. (For Google, the session is normally
            // inherited from the launcher; if it wasn't, the player finishes with
            // one tap on the Google button — which uses a reliable popup, never
            // the cross-domain redirect.)
            showStep("auth-step-choose");
            if (_ccWantsGoogleAuth) {
              setAuthMsg("auth-choose-err", "Tap “Continue with Google” to finish signing in.", true);
            }
          }
        }
      });
    })();

    // ── Terms & Agreement modal ──────────────────────────────────
    // Dual-purpose. mode "agree": gated flow shown on first account creation
    // and EVERY guest sign-in — the "I Agree & Consent" button stays disabled
    // until the reader scrolls to the bottom of the terms. mode "view":
    // read-only, opened from Settings (no gating, backdrop/Close dismiss).
    function ccShowTerms(opts) {
      opts = opts || {};
      const isView   = opts.mode === "view";
      const modal    = $a("terms-modal");
      const scroll   = $a("terms-scroll");
      const hint     = $a("terms-scroll-hint");
      const agreeBtn = $a("terms-agree-btn");
      const closeBtn = $a("terms-close-btn");
      const cancel   = $a("terms-cancel");
      // Fail-open: if the modal is somehow missing, never block sign-in.
      if (!modal || !scroll || !agreeBtn) {
        if (!isView && typeof opts.onAgree === "function") opts.onAgree();
        return;
      }
      setAuthMsg("terms-err", "", false);

      // Buttons per mode.
      agreeBtn.style.display = isView ? "none" : "";
      closeBtn.style.display = isView ? "" : "none";
      cancel.style.display   = isView ? "none" : "";
      hint.style.display     = isView ? "none" : "";

      let atBottom = isView;            // view mode never gates
      agreeBtn.disabled = !atBottom;
      hint.classList.remove("done");
      hint.textContent = "⬇ Please scroll to the bottom to continue";

      function unlock() {
        if (atBottom) return;
        atBottom = true;
        agreeBtn.disabled = false;
        hint.classList.add("done");
        hint.textContent = "✓ You've reached the end — you can now agree";
      }
      function checkBottom() {
        if (atBottom) return;
        if (scroll.scrollHeight - scroll.scrollTop - scroll.clientHeight <= 24) unlock();
      }
      function cleanup() {
        scroll.removeEventListener("scroll", onScroll);
        agreeBtn.removeEventListener("click", onAgree);
        closeBtn.removeEventListener("click", onClose);
        cancel.removeEventListener("click", onCancel);
        modal.removeEventListener("click", onBackdrop);
      }
      function close()  { modal.classList.remove("open"); cleanup(); }
      function onScroll() { checkBottom(); }
      function onAgree()  { if (agreeBtn.disabled) return; close(); if (typeof opts.onAgree  === "function") opts.onAgree();  }
      function onClose()  { close(); if (typeof opts.onClose  === "function") opts.onClose();  }
      function onCancel() { close(); if (typeof opts.onCancel === "function") opts.onCancel(); }
      // Backdrop click closes in view mode only — the agree gate must not be dismissible.
      function onBackdrop(e) { if (e.target === modal && isView) onClose(); }

      scroll.addEventListener("scroll", onScroll, { passive: true });
      agreeBtn.addEventListener("click", onAgree);
      closeBtn.addEventListener("click", onClose);
      cancel.addEventListener("click", onCancel);
      modal.addEventListener("click", onBackdrop);

      modal.classList.add("open");
      requestAnimationFrame(() => {
        scroll.scrollTop = 0;
        // If the whole text already fits without scrolling, don't trap the user.
        if (!isView && scroll.scrollHeight - scroll.clientHeight <= 24) unlock();
        try { scroll.focus({ preventScroll: true }); } catch (_) {}
      });
    }
    window.__ccShowTerms = ccShowTerms;

    // ── Guest flow ───────────────────────────────────────────────
    $a("auth-guest-btn").addEventListener("click", () => {
      $a("auth-guest-overlay").classList.add("visible");
      $a("auth-guest-btn").style.pointerEvents = "none";
      $a("auth-choose-google-btn").style.pointerEvents = "none";
      setAuthMsg("auth-guest-err", "", false);
      $a("auth-guest-nick").value = "";
      setTimeout(() => $a("auth-guest-nick").focus(), 60);
    });

    $a("auth-guest-back").addEventListener("click", () => {
      $a("auth-guest-overlay").classList.remove("visible");
      $a("auth-guest-btn").style.pointerEvents = "";
      $a("auth-choose-google-btn").style.pointerEvents = "";
    });

    async function beginCleanGoogleSignIn(errId) {
      if (!_auth) {
        setAuthMsg(errId, "Sign-in is not yet configured for this server.", false);
        return;
      }
      setAuthMsg(errId, "", false);
      const previousUid = _auth.currentUser?.uid || "";
      clearGuestSessionStorage();
      _playerNickname = "";
      _friendCode = "";
      _activeProfile = null;
      _pendingOnboardingUid = "";
      _avatarPromptShownForUid = "";
      syncStatsHeader(null);
      const sl = $a("auth-stats-lobby");
      if (sl) sl.classList.remove("visible");
      const bar = $a("auth-profile-bar");
      if (bar) bar.style.display = "none";
      if (_auth.currentUser) {
        try { await _auth.signOut(); } catch {}
      }
      try {
        const provider = new firebase.auth.GoogleAuthProvider();
        provider.setCustomParameters({ prompt: "select_account consent" });
        const result = await _auth.signInWithPopup(provider);
        const signedUid = result?.user?.uid || "";
        if (previousUid && signedUid && signedUid === previousUid) {
          setAuthMsg(errId, "You selected the same Google account. Choose a different account in the Google picker.", false);
        }
      } catch (e) {
        ccReport("firebase_google_signin_failed", ccErrDetail(e), "warn");
        const popupBlocked = ["auth/popup-blocked","auth/cancelled-popup-request"].includes(e.code);
        if (popupBlocked) {
          const rp = new firebase.auth.GoogleAuthProvider();
          rp.setCustomParameters({ prompt: "select_account consent" });
          try { await _auth.signInWithRedirect(rp); return; } catch {}
        }
        setAuthMsg(errId, friendlyAuthErr(e.code), false);
      }
    }

    // Google sign-in performed INSIDE the dedicated game window (the in-window
    // "Continue with Google" button). Uses signInWithPopup — gesture-driven and
    // reliable on every browser. signInWithRedirect is only a last-resort
    // fallback if the popup is blocked, because the app's Firebase authDomain is
    // a different domain (…firebaseapp.com) and modern browsers partition that
    // storage, which makes getRedirectResult() come back empty (sign-in silently
    // fails). After popup sign-in, onAuthStateChanged reveals the lobby here.
    async function beginGameWindowGoogleSignIn(errId) {
      if (!_auth) { setAuthMsg(errId, "Sign-in is not configured for this server.", false); return; }
      setAuthMsg(errId, "", false);
      clearGuestSessionStorage();
      _playerNickname = ""; _friendCode = ""; _activeProfile = null;
      _pendingOnboardingUid = ""; _avatarPromptShownForUid = "";
      try { syncStatsHeader(null); } catch (_) {}
      const sl = $a("auth-stats-lobby"); if (sl) sl.classList.remove("visible");
      const bar = $a("auth-profile-bar"); if (bar) bar.style.display = "none";
      try {
        if (_auth.currentUser) { try { await _auth.signOut(); } catch (_) {} }
        const provider = new firebase.auth.GoogleAuthProvider();
        provider.setCustomParameters({ prompt: "select_account consent" });
        await _auth.signInWithPopup(provider);
      } catch (e) {
        ccReport("firebase_google_signin_failed", ccErrDetail(e), "warn");
        const popupBlocked = ["auth/popup-blocked","auth/cancelled-popup-request"].includes(e.code);
        if (popupBlocked) {
          try {
            const rp = new firebase.auth.GoogleAuthProvider();
            rp.setCustomParameters({ prompt: "select_account consent" });
            _ccGoogleRedirectStarted = true;
            await _auth.signInWithRedirect(rp); return;
          } catch (_) {}
        }
        setAuthMsg(errId, friendlyAuthErr(e.code), false);
      }
    }

    const chooseGoogleBtn = $a("auth-choose-google-btn");
    if (chooseGoogleBtn) chooseGoogleBtn.addEventListener("click", async () => {
      if (IS_GAME_WINDOW()) {
        // Already inside the dedicated window (or on mobile, where we play
        // inline) — sign in here with a popup.
        await beginGameWindowGoogleSignIn("auth-choose-err");
      } else {
        // Launcher: sign in with Google HERE using a popup (gesture-driven and
        // reliable on all browsers — unlike the cross-domain signInWithRedirect).
        // When sign-in resolves, onAuthStateChanged opens the dedicated game
        // window (which inherits this session) — or shows the Open Game button.
        await beginCleanGoogleSignIn("auth-choose-err");
      }
    });

    $a("auth-guest-go-btn").addEventListener("click", () => {
      const nick = ($a("auth-guest-nick").value || "").trim();
      const err = validateNick(nick);
      if (err) { setAuthMsg("auth-guest-err", err, false); return; }
      // Guests must agree to the Terms EVERY time they start a session.
      ccShowTerms({ mode: "agree", onAgree: () => {
        _authUser = null;
        _guestSessionActive = true;
        _friendCode = "";
        _guestAvatarUrl = sanitizeSelectableAvatar(localStorage.getItem(GUEST_AVATAR_KEY) || "", nick || "guest");
        localStorage.setItem(GUEST_NICK_KEY, nick);
        localStorage.setItem(GUEST_AVATAR_KEY, _guestAvatarUrl);
        _activeProfile = { nickname: nick, avatar_url: _guestAvatarUrl };
        if (IS_GAME_WINDOW()) {
          revealLobby(nick, "");
        } else {
          // Launcher: the guest session we just saved is read by the dedicated
          // window — so the player never enters the nickname twice. Mark that
          // Terms were just agreed so the game window doesn't re-prompt for
          // THIS dive (a fresh, separate session will still be gated).
          markGuestTermsAgreed();
          ccLaunchFromLauncher({ type: "guest", nick, avatarUrl: _guestAvatarUrl, gameUrl: ccGameUrl() });
        }
      }});
    });
    $a("auth-guest-nick").addEventListener("keydown", e => { if (e.key === "Enter") $a("auth-guest-go-btn").click(); });

    // Google sign-in is wired up earlier via #auth-choose-google-btn (chooser screen)
    // Play as Guest is wired up via #auth-guest-btn → #auth-guest-go-btn flow.

    // Handle redirect result from signInWithRedirect (fires on page load after Google redirect)
    if (_auth) {
      _auth.getRedirectResult().then(result => {
        // onAuthStateChanged fires automatically if sign-in succeeded
      }).catch(e => {
        if (e.code && e.code !== "auth/no-current-user") {
          ccReport("firebase_redirect_result_failed", ccErrDetail(e), "warn");
          setAuthMsg("auth-choose-err", friendlyAuthErr(e.code), false);
        }
      });
    }

    // ── Nickname setup (first-time account creation) ─────────────
    // Reaching this step means a brand-new account is being created, so the
    // player must read + agree to the Terms before the profile is saved.
    $a("auth-nick-go-btn").addEventListener("click", async () => {
      if (!_authUser) { setAuthMsg("auth-nick-err", "Not signed in.", false); return; }
      const nick = ($a("auth-nick-input").value || "").trim();
      const err  = validateNick(nick);
      if (err) { setAuthMsg("auth-nick-err", err, false); return; }
      ccShowTerms({ mode: "agree", onAgree: () => { void finishNicknameSetup(nick); } });
    });
    async function finishNicknameSetup(nick) {
      if (!_authUser) { setAuthMsg("auth-nick-err", "Not signed in.", false); return; }
      setAuthMsg("auth-nick-err", "Saving…", true);
      try {
        const code = await saveNewProfile(_authUser.uid, nick, _authUser.email || "", "");
        fetch("/api/user/register", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ uid: _authUser.uid }),
        }).catch((e) => {
          ccReport("api_fetch_failed", {
            path: "/api/user/register",
            method: "POST",
            error: e && (e.name || e.message || e)
          }, "warn");
        });
        _playerNickname = nick;
        _friendCode = code;
        _pendingOnboardingUid = "";
        _avatarPromptShownForUid = _authUser.uid;
        _activeProfile = { ...(_activeProfile || {}), uid: _authUser.uid, nickname: nick, friend_code: code, avatar_url: DEFAULT_AVATAR_IMG, terms_version: TERMS_VERSION };
        await applyAvatarSelection(DEFAULT_AVATAR_IMG);
        revealLobby(nick, code);
      } catch (e) {
        ccReport("firebase_profile_save_failed", ccErrDetail(e), "warn");
        setAuthMsg("auth-nick-err", "Could not save nickname. Try again.", false);
      }
    }
    $a("auth-nick-input").addEventListener("keydown", e => { if (e.key === "Enter") $a("auth-nick-go-btn").click(); });

    // ── Launch screen controller (Open / Return / Relaunch / Continue / Sign Out) ──
    (function setupLaunchScreen() {
      const primary = $a("auth-launch-play-btn");
      const second  = $a("auth-launch-secondary-btn");
      const cont    = $a("auth-launch-continue");
      const soBtn   = $a("auth-launch-signout");

      if (primary) primary.addEventListener("click", () => {
        const action = primary.dataset.action || "open";
        if (action === "return") {
          // Focus the running window; if it was closed, relaunch it.
          if (!focusGameWindow()) ccLaunchFromLauncher(_ccLaunchCtx);
        } else {
          ccLaunchFromLauncher(_ccLaunchCtx); // open / retry-after-blocked
        }
      });

      if (second) second.addEventListener("click", () => {
        // Relaunch: drop any stale handle and (re)open the named window.
        _ccGameWin = null;
        ccLaunchFromLauncher(_ccLaunchCtx);
      });

      if (cont) cont.addEventListener("click", () => {
        // Continue in THIS tab: navigate it to the real game-window URL so the
        // launcher tab becomes the dedicated game (reads the saved guest session
        // or finishes Google auth, then lands in the lobby).
        window.location.href = _ccLaunchCtx.gameUrl;
      });

      if (soBtn) soBtn.addEventListener("click", async () => {
        if (_authUser && _auth) {
          try { await _auth.signOut(); } catch (_) {}
        } else {
          clearGuestSessionStorage();
          _guestSessionActive = false;
          _playerNickname = "";
        }
        _ccGameWin = null;
        _ccLaunchCtx = { type: "guest", nick: "", avatarUrl: "", gameUrl: ccGameUrl() };
        showStep("auth-step-choose");
        setAuthMsg("auth-choose-err", "", false);
      });
    })();

    const statsAvatarBtn = $a("stats-avatar");
    if (statsAvatarBtn) {
      statsAvatarBtn.addEventListener("click", () => {
        // Guests are locked to the Mullet — only signed-in players open the gallery.
        if (_authUser) {
          openAvatarGallery();
        } else if (_guestSessionActive && typeof showToast === "function") {
          showToast("Sign in to choose your avatar.", "warn");
        }
      });
      statsAvatarBtn.addEventListener("keydown", (e) => {
        if (!_authUser) return;
        if (e.key === "Enter" || e.key === " ") {
          e.preventDefault();
          openAvatarGallery();
        }
      });
    }

    const avatarModalSaveBtn = $a("avatar-modal-save-btn");
    if (avatarModalSaveBtn) avatarModalSaveBtn.addEventListener("click", saveAvatarSelection);
    const avatarModalCancel = $a("avatar-modal-cancel");
    if (avatarModalCancel) avatarModalCancel.addEventListener("click", closeAvatarPickerModal);
    const avatarModal = $a("avatar-picker-modal");
    if (avatarModal) avatarModal.addEventListener("click", (e) => {
      if (e.target === avatarModal) closeAvatarPickerModal();
    });

    // ── Sign out (game lobby bar) ────────────────────────────────
    $a("auth-signout-btn").addEventListener("click", async () => {
      await cancelQuickMatch(true);
      try { if (typeof stopThemeSong === "function") stopThemeSong(); } catch {}
      clearGuestSessionStorage();
      if (_authUser) stopPresencePing(_authUser.uid);
      if (_reqUnsubscribe) { _reqUnsubscribe(); _reqUnsubscribe = null; }
      _playerNickname = ""; _friendCode = ""; _activeProfile = null;
      if (_auth) { try { await _auth.signOut(); } catch {} }
      _authUser = null;
      _avatarPromptShownForUid = "";
      _avatarSelectionRequired = false;
      _pendingOnboardingUid = "";
      $a("auth-profile-bar").style.display = "none";
      closeAvatarPickerModal();
      setStatsAvatarClickable(false);
      showStep("auth-step-choose");
    });

    // ── Stats lobby buttons ───────────────────────────────────────
    // Quick Play goes directly into the dedicated four-seat queue.
    const _qmBtn = $a("stats-quickmatch-btn");
    if (_qmBtn) _qmBtn.addEventListener("click", () => {
      startQuickMatch();
    });

    $a("stats-create-btn").addEventListener("click", () => {
      openNewCurrentModal();
    });

    $a("stats-join-toggle-btn").addEventListener("click", () => {
      refreshFriendNicks();
      openLobbyBrowser();
    });

    $a("stats-join-go-btn").addEventListener("click", () => {
      refreshFriendNicks();
      openLobbyBrowser();
    });

    $a("stats-join-code").addEventListener("keydown", e => {
      if (e.key === "Enter") $a("stats-join-go-btn").click();
    });

    $a("stats-tutorial-btn").addEventListener("click", () => {
      // New 3-mode tutorial chooser — opens OVER the lobby (kept visible) so the
      // Main Menu Tour can spotlight the real menu. Defined in the tutorial module.
      if (window.__openTutorialChooser) window.__openTutorialChooser();
    });

    // ── Leaderboard button — switches to the in-game leaderboard tab ─
    const lbBtn = $a("stats-leaderboard-btn");
    if (lbBtn) lbBtn.addEventListener("click", () => {
      if (typeof window._switchPhTab === "function") window._switchPhTab("leaderboard");
    });
    $a("lb-close-btn").addEventListener("click", () => $a("leaderboard-modal").classList.remove("open"));
    // Wire all player-count tabs dynamically
    $a("lb-tabs-row").addEventListener("click", (e) => {
      const btn = e.target.closest(".lb-tab");
      if (!btn) return;
      $a("lb-tabs-row").querySelectorAll(".lb-tab").forEach(t => t.classList.remove("active"));
      btn.classList.add("active");
      loadLeaderboard(Number(btn.dataset.size));
    });

    // ── Settings button ───────────────────────────────────────────
    // ── Music volume slider (persisted in localStorage) ────────────
    const MUSIC_VOL_PREF_KEY = "fish_music_volume";
    function _readMusicVol() {
      const raw = localStorage.getItem(MUSIC_VOL_PREF_KEY);
      if (raw === null || raw === "") {
        // Back-compat: map the old on/off flag onto a volume.
        return localStorage.getItem("fish_music_on") === "0" ? 0 : 100;
      }
      const v = parseInt(raw, 10);
      return Number.isFinite(v) ? Math.max(0, Math.min(100, v)) : 100;
    }
    let _musicVol = _readMusicVol();

    // Is the player currently inside the game simulation (not the lobby)?
    function _inGameSimulation() {
      const g = document.getElementById("pv-game");
      return !!(g && g.style.display !== "none" && g.offsetParent !== null);
    }
    function _syncMusicSliderUI() {
      const slider = $a("settings-music-slider");
      const label = $a("settings-music-label");
      if (slider) {
        if (slider.value !== String(_musicVol)) slider.value = String(_musicVol);
        slider.setAttribute("aria-valuenow", String(_musicVol));
        slider.style.setProperty("--fill", _musicVol + "%");
      }
      if (label) label.textContent = _musicVol === 0 ? "Off" : _musicVol + "%";
    }
    function _applyMusicVolume(v, opts) {
      _musicVol = Math.max(0, Math.min(100, Math.round(Number(v) || 0)));
      localStorage.setItem(MUSIC_VOL_PREF_KEY, String(_musicVol));
      // Keep the legacy on/off flag in sync so older code paths still behave.
      localStorage.setItem("fish_music_on", _musicVol > 0 ? "1" : "0");
      _syncMusicSliderUI();
      // Live-apply to the currently playing track (if any).
      if (typeof window.__ccApplyThemeVolume === "function") window.__ccApplyThemeVolume();
      if (_musicVol > 0) {
        // Audio lives ONLY in the game simulation — only (re)start it if we're
        // actually in a game right now. In the lobby, nothing plays.
        if (!(opts && opts.uiOnly) && _inGameSimulation() && typeof startThemeSong === "function") startThemeSong();
      } else {
        // 0 → stop immediately, works in-game and in the lobby.
        if (typeof stopThemeSong === "function") stopThemeSong();
      }
    }

    const musicSlider = $a("settings-music-slider");
    if (musicSlider) {
      _applyMusicVolume(_musicVol, { uiOnly: true }); // initial sync only — never auto-start on load
      // Live while dragging: `input` fires continuously as the mouse/finger
      // moves, so the volume (and start/stop) responds in real time — you don't
      // have to release first. `_inGameSimulation()` inside still prevents any
      // lobby auto-start, so this is safe everywhere. `change` is a harmless
      // backstop for keyboard/edge cases.
      const onSlide = () => _applyMusicVolume(musicSlider.value);
      musicSlider.addEventListener("input", onSlide);
      musicSlider.addEventListener("change", onSlide);
    }

    // ── Settings modal open ─────────────────────────────────────────
    const settingsBtn = $a("stats-settings-btn");
    function _openSettingsModal() {
      const nick = _playerNickname || "—";
      const nickEl = $a("settings-current-nick");
      if (nickEl) nickEl.textContent = nick;
      const statusEl = $a("settings-account-status");
      if (statusEl) statusEl.textContent = _authUser
        ? (_authUser.providerData?.[0]?.providerId === "google.com" ? "Google account" : "Email account")
        : (_guestSessionActive ? "Guest session" : "Not signed in");
      const signoutRow = $a("settings-signout-btn");
      if (signoutRow) signoutRow.style.display = (_authUser || _guestSessionActive) ? "" : "none";
      const nickRow = $a("settings-nick-row");
      if (nickRow) nickRow.style.display = _authUser ? "" : "none";

      // Show cooldown status on open
      if (_authUser && _activeProfile) {
        const lastChange = _activeProfile.nickname_changed_at;
        const cooldownEl = $a("settings-nick-cooldown");
        const editBtn = $a("settings-edit-nick-btn");
        const msLeft = lastChange
          ? (24 * 60 * 60 * 1000) - (Date.now() - new Date(lastChange.toDate ? lastChange.toDate() : lastChange).getTime())
          : 0;
        if (msLeft > 0) {
          const hoursLeft = Math.ceil(msLeft / (60 * 60 * 1000));
          const label = hoursLeft >= 24 ? "tomorrow" : `in ${hoursLeft} hour${hoursLeft !== 1 ? "s" : ""}`;
          if (cooldownEl) { cooldownEl.textContent = `You can change your username again ${label}.`; cooldownEl.style.display = ""; }
          if (editBtn) { editBtn.disabled = true; editBtn.style.opacity = ".45"; editBtn.title = `Available ${label}`; }
        } else {
          if (cooldownEl) cooldownEl.style.display = "none";
          if (editBtn) { editBtn.disabled = false; editBtn.style.opacity = ""; editBtn.title = ""; }
        }
      }

      // Sync music slider UI
      _syncMusicSliderUI();

      $a("settings-modal").classList.add("open");
    }
    if (settingsBtn) settingsBtn.addEventListener("click", _openSettingsModal);
    // Expose so the in-game menu (a different scope) can open the same modal.
    window.__openSettingsModal = _openSettingsModal;

    $a("settings-close-btn").addEventListener("click", () => $a("settings-modal").classList.remove("open"));
    // Terms & Agreement — read-only view from Settings.
    (function wireSettingsTerms() {
      const tBtn = $a("settings-terms-btn");
      if (!tBtn) return;
      const openTerms = () => ccShowTerms({ mode: "view" });
      tBtn.addEventListener("click", openTerms);
      tBtn.addEventListener("keydown", (e) => {
        if (e.key === "Enter" || e.key === " " || e.key === "Spacebar") { e.preventDefault(); openTerms(); }
      });
    })();
    $a("settings-edit-nick-btn").addEventListener("click", () => {
      const form = $a("settings-nick-form");
      if (form) { form.style.display = "flex"; $a("settings-nick-input").focus(); }
    });
    function _cancelSettingsNickEdit() {
      const form = $a("settings-nick-form");
      if (form) form.style.display = "none";
    }
    $a("settings-nick-cancel").addEventListener("click", _cancelSettingsNickEdit);
    $a("settings-nick-cancel").addEventListener("keydown", (e) => {
      if (e.key === "Enter" || e.key === " " || e.key === "Spacebar") {
        e.preventDefault();
        _cancelSettingsNickEdit();
      }
    });
    $a("settings-nick-save-btn").addEventListener("click", async () => {
      if (!_authUser) return;
      const newNick = ($a("settings-nick-input").value || "").trim();
      const err = validateNick(newNick);
      if (err) { setAuthMsg("settings-nick-err", err, false); return; }
      if (newNick === _playerNickname) { setAuthMsg("settings-nick-err", "That's already your username.", false); return; }

      // 1-day cooldown check (re-read from Firestore for accuracy)
      try {
        const docSnap = await _db.collection("users").doc(_authUser.uid).get();
        const data = docSnap.data() || {};
        const lastChange = data.nickname_changed_at;
        if (lastChange) {
          const msLeft = (24 * 60 * 60 * 1000) - (Date.now() - new Date(lastChange.toDate ? lastChange.toDate() : lastChange).getTime());
          if (msLeft > 0) {
            const hoursLeft = Math.ceil(msLeft / (60 * 60 * 1000));
            const label = hoursLeft >= 24 ? "tomorrow" : `in ${hoursLeft} hour${hoursLeft !== 1 ? "s" : ""}`;
            setAuthMsg("settings-nick-err", `You can change your username again ${label}.`, false);
            return;
          }
        }
      } catch { /* proceed if check fails */ }

      // Check the new name isn't already taken
      setAuthMsg("settings-nick-err", "Checking availability…", true);
      try {
        const taken = await _db.collection("users").where("nickname_lower", "==", newNick.toLowerCase()).get();
        if (!taken.empty && taken.docs[0].id !== _authUser.uid) {
          setAuthMsg("settings-nick-err", "That username is already taken.", false); return;
        }
      } catch { /* proceed if check fails */ }

      setAuthMsg("settings-nick-err", "Saving…", true);
      try {
        // Remove old friend_lookup entry (keep same 4-digit code)
        if (_friendCode && _playerNickname) {
          const oldKey = _playerNickname.toLowerCase() + "_" + _friendCode;
          await _db.collection("friend_lookup").doc(oldKey).delete().catch(() => {});
        }
        // Keep the same 4-digit code — only the name changes
        const code = _friendCode || genFriendCode();
        const newKey = newNick.toLowerCase() + "_" + code;
        const now = firebase.firestore.FieldValue.serverTimestamp();
        await _db.collection("users").doc(_authUser.uid).update({
          nickname: newNick,
          nickname_lower: newNick.toLowerCase(),
          friend_code: code,
          nickname_changed_at: now,   // 1-day cooldown timestamp
        });
        // Public lookup doc uses new name + same code
        await _db.collection("friend_lookup").doc(newKey).set({
          uid: _authUser.uid, nickname: newNick, updated_at: now,
        });
        _playerNickname = newNick;
        _friendCode = code;
        _activeProfile = {
          ...(_activeProfile || {}),
          nickname: newNick,
          nickname_lower: newNick.toLowerCase(),
          friend_code: code,
          nickname_changed_at: new Date(),
        };
        setAuthMsg("settings-nick-err", `✓ Username updated! Your friend code is ${code}`, true);
        lockNameInputs(newNick);
        // Refresh ALL public-facing name displays
        syncStatsHeader(_activeProfile);
        if (typeof window.__fishSyncNickname === "function") window.__fishSyncNickname();
        // Update our name in group meta docs we own in our own messages subcollection.
        // (Firestore rules don't allow writing to other users' docs, so we update only our copy.)
        try {
          const myMsgSnap = await _db.collection("users").doc(_authUser.uid)
            .collection("messages").where("meta", "==", true).get();
          for (const mdoc of myMsgSnap.docs) {
            const mdata = mdoc.data() || {};
            const members = Array.isArray(mdata.members) ? mdata.members : [];
            const updatedMembers = members.map(p =>
              (p && p.uid === _authUser.uid) ? { ...p, name: newNick } : p
            );
            if (JSON.stringify(members) !== JSON.stringify(updatedMembers)) {
              mdoc.ref.update({ members: updatedMembers }).catch(() => {});
            }
          }
        } catch { /* best-effort */ }
        const settingsNickEl = $a("settings-current-nick");
        if (settingsNickEl) settingsNickEl.textContent = newNick;
        const form = $a("settings-nick-form");
        if (form) form.style.display = "none";
        // Show cooldown note
        const cooldownEl = $a("settings-nick-cooldown");
        const editBtn = $a("settings-edit-nick-btn");
        if (cooldownEl) { cooldownEl.textContent = "You can change your username again tomorrow."; cooldownEl.style.display = ""; }
        if (editBtn) { editBtn.disabled = true; editBtn.style.opacity = ".45"; }
      } catch(e) {
        setAuthMsg("settings-nick-err", "Could not update username.", false);
      }
    });
    const settingsSignoutBtn = $a("settings-signout-btn");
    if (settingsSignoutBtn) settingsSignoutBtn.addEventListener("click", async () => {
      await cancelQuickMatch(true);
      clearGuestSessionStorage();
      if (_authUser) stopPresencePing(_authUser.uid);
      if (_reqUnsubscribe) { _reqUnsubscribe(); _reqUnsubscribe = null; }
      _playerNickname = ""; _friendCode = ""; _activeProfile = null;
      if (_auth) { try { await _auth.signOut(); } catch {} }
      _authUser = null;
      _avatarPromptShownForUid = "";
      _avatarSelectionRequired = false;
      _pendingOnboardingUid = "";
      $a("settings-modal").classList.remove("open");
      $a("auth-stats-lobby").classList.remove("visible");
      $a("auth-profile-bar").style.display = "none";
      closeAvatarPickerModal();
      setStatsAvatarClickable(false);
      showStep("auth-step-choose");
    });

    const statsSignoutBtn = $a("stats-signout-btn");
    if (statsSignoutBtn) {
      statsSignoutBtn.addEventListener("click", async () => {
        await cancelQuickMatch(true);
        clearGuestSessionStorage();
        if (_authUser) stopPresencePing(_authUser.uid);
        if (_reqUnsubscribe) { _reqUnsubscribe(); _reqUnsubscribe = null; }
        _playerNickname = ""; _friendCode = ""; _activeProfile = null;
        if (_auth) { try { await _auth.signOut(); } catch {} }
        _authUser = null;
        _avatarPromptShownForUid = "";
        _avatarSelectionRequired = false;
        _pendingOnboardingUid = "";
        $a("auth-stats-lobby").classList.remove("visible");
        $a("auth-profile-bar").style.display = "none";
        closeAvatarPickerModal();
        setStatsAvatarClickable(false);
        $a("auth-screen").classList.remove("hidden");
        showStep("auth-step-choose");
      });
    }

    // Mark user offline when tab is closed
    window.addEventListener("beforeunload", () => {
      const queued = _qmSearch;
      if (queued?.roomId && queued?.seatToken && navigator.sendBeacon) {
        try {
          const body = new Blob(
            [JSON.stringify({ seat_token: queued.seatToken })],
            { type: "application/json" }
          );
          navigator.sendBeacon(apiUrl(`/api/rooms/${queued.roomId}/leave`), body);
        } catch (_) {}
      }
      if (_authUser) setOnlineStatus(_authUser.uid, false);
    });

    const statsFriendBtn = $a("stats-friend-btn");
    if (statsFriendBtn) {
      statsFriendBtn.addEventListener("click", () => {
        if (typeof window._switchPhTab === "function") window._switchPhTab("friends");
      });
    }

    // Messaging system — stored under users/{uid}/messages (works under existing rules).
    //  Each message is dual-written: a copy in the sender's subcollection AND
    //  a copy in the recipient's subcollection. We only ever READ our own
    //  subcollection, and writing to another user's subcollection is already
    //  permitted by the rules (the friend-request system does the same).
    //  Schema  users/{uid}/messages/{msgId}:
    //    conv_id, sender, sender_name, receiver, receiver_name, text, ts, read

    let _msgListUnsub = null;       // listener on my messages subcollection
    let _msgAllMessages = [];       // cache of all my message docs
    let _msgConversations = [];     // derived: one entry per conversation
    let _msgOpenConvId = null;
    let _msgOpenPeer = null;        // { uid, name }  (DM only)
    let _msgOpenGroup = null;       // { id, name, members:[{uid,name}] }  (group only)
    let _msgTotalUnread = 0;
    let _msgListRenderGen = 0;      // generation counter — stale async renders bail out
    const _msgChangeCbs = [];       // external subscribers (in-game panel) notified on cache update

    function _convIdFor(a, b) { return [String(a), String(b)].sort().join("__"); }
    // Group conversations live in the SAME users/{uid}/messages subcollection as DMs
    // (so the existing Firestore rule + single listener cover them — no new rules).
    //   group message: { conv_id, group:true, sender, sender_name, text, ts, read }
    //   group meta:    { conv_id, group:true, meta:true, name, members:[{uid,name}],
    //                    owner, ts, read:true }  stored at deterministic id "gm_"+conv_id
    function _newGroupConvId() {
      let h = "";
      for (let i = 0; i < 16; i++) h += Math.floor(Math.random() * 16).toString(16);
      return "g_" + h;
    }
    // Latest metadata doc for a group conv from my cache (null if none).
    function _msgGroupMeta(convId) {
      const metas = _msgAllMessages.filter(m => m && m.conv_id === convId && m.meta);
      if (!metas.length) return null;
      metas.sort((a, b) => _msgTs(a) - _msgTs(b));
      return metas[metas.length - 1];
    }
    function _msgTs(m) { return (m && m.ts && m.ts.toMillis) ? m.ts.toMillis() : Date.now(); }

    function _msgUpdateBadge() {
      const badge = $a("msg-unread-badge");
      if (!badge) return;
      if (_msgTotalUnread > 0) {
        badge.textContent = _msgTotalUnread > 99 ? "99+" : String(_msgTotalUnread);
        badge.style.display = "";
      } else {
        badge.style.display = "none";
      }
    }

    // Format a Firestore timestamp / Date / millis into a short label.
    // Returns "" for a pending serverTimestamp so optimistic sends don't error.
    function _msgTimeLabel(ts) {
      if (!ts) return "";
      let d;
      try { d = ts.toDate ? ts.toDate() : (ts instanceof Date ? ts : new Date(ts)); }
      catch { return ""; }
      if (!d || Number.isNaN(d.getTime())) return "";
      const now = new Date();
      const sameDay = d.toDateString() === now.toDateString();
      return sameDay
        ? d.toLocaleTimeString("en-US", { hour: "numeric", minute: "2-digit" })
        : d.toLocaleDateString("en-US", { month: "short", day: "numeric" });
    }

    // Group my cached messages into per-conversation summaries (newest first).
    // Handles both 2-party DMs and multi-party group chats.
    function _msgRebuildConversations() {
      const byConv = {};
      _msgAllMessages.forEach(m => {
        if (!m || !m.conv_id) return;
        (byConv[m.conv_id] = byConv[m.conv_id] || []).push(m);
      });
      _msgConversations = Object.keys(byConv).map(cid => {
        const all  = byConv[cid];
        const meta = all.filter(m => m.meta).sort((a, b) => _msgTs(a) - _msgTs(b)).pop() || null;
        const isGroup = !!meta || all.some(m => m.group);
        const msgs = all.filter(m => !m.meta).sort((a, b) => _msgTs(a) - _msgTs(b));
        const last = msgs[msgs.length - 1];
        const unread = msgs.filter(m => m.sender !== _authUser.uid && !m.read).length;

        if (isGroup) {
          // Hide groups I've been removed from / left (meta no longer lists me).
          if (meta && Array.isArray(meta.members)
              && !meta.members.some(p => p && p.uid === _authUser.uid)) return null;
          const name    = (meta && meta.name) || "Group";
          const members = (meta && Array.isArray(meta.members)) ? meta.members : [];
          const preview = last
            ? ((last.sender === _authUser.uid ? "You: " : ((last.sender_name || "") + ": ")) + (last.text || ""))
            : "New group";
          return { id: cid, group: true, name, peerName: name, members,
                   last_text: preview, last_ts: (last ? last.ts : (meta && meta.ts)), unread };
        }

        if (!last) return null;            // DM with no surviving messages
        const iSent    = last.sender === _authUser.uid;
        const peerUid  = iSent ? last.receiver : last.sender;
        const peerName = (iSent ? last.receiver_name : last.sender_name) || "Player";
        return { id: cid, peerUid, peerName, last_text: last.text, last_ts: last.ts, unread };
      }).filter(Boolean).sort((a, b) => _msgTs({ ts: b.last_ts }) - _msgTs({ ts: a.last_ts }));
    }

    // Single listener on my own messages subcollection — drives everything.
    function _msgStartListListener() {
      if (!_db || !_authUser) return;
      if (_msgListUnsub) { try { _msgListUnsub(); } catch {} _msgListUnsub = null; }
      try {
        _msgListUnsub = _db.collection("users").doc(_authUser.uid).collection("messages")
          .onSnapshot({ includeMetadataChanges: false }, snap => {
            _msgAllMessages = snap.docs.map(d => ({ id: d.id, ...d.data() }));
            _msgTotalUnread = _msgAllMessages.filter(m => !m.meta && m.sender !== _authUser.uid && !m.read).length;
            _msgUpdateBadge();
            _msgRebuildConversations();
            const drawer = $a("cc-msg-drawer");
            if (drawer && drawer.classList.contains("open")) {
              if (_msgOpenConvId) _msgRenderOpenConversation();
              else _msgRenderList();
            }
            // Notify external subscribers (the in-game iMessage panel) so it
            // re-renders live and keeps its unread badge in sync.
            _msgChangeCbs.forEach(cb => { try { cb(); } catch (_) {} });
          }, err => {
            console.warn("[msg] listener error:", err);
            if (err && err.code === "permission-denied") _msgShowRulesNeeded();
          });
      } catch (e) { console.warn("[msg] listen failed:", e); }
    }

    // Shown when Firestore rules block the messages subcollection.
    function _msgShowRulesNeeded() {
      const listEl = $a("ccm-list");
      const msgsEl = $a("ccm-messages");
      const banner = "<div class=\"ccm-empty\"><div class=\"ccm-empty-ico\">🔒</div>"
        + "<b>Messaging needs one Firestore rule.</b><br><br>"
        + "In Firebase Console &rarr; Firestore &rarr; Rules, inside your "
        + "<code>match /users/{userId}</code> block add:<br><br>"
        + "<code style=\"font-size:11px;background:rgba(0,40,90,.08);padding:6px 8px;border-radius:6px;display:block;text-align:left;\">match /messages/{m} {<br>&nbsp;&nbsp;allow read, write: if request.auth != null;<br>}</code>"
        + "<br>then click Publish and refresh.</div>";
      if (listEl && !_msgOpenConvId) listEl.innerHTML = banner;
      if (msgsEl && _msgOpenConvId) msgsEl.innerHTML = banner;
    }

    // Players picked in the search bar (or [] when empty).
    function _ccmComposeRecipients() {
      return (_ccmComposer && _ccmComposer.getRecipients) ? _ccmComposer.getRecipients() : [];
    }
    // Does conversation c include EVERY player picked in the search bar?
    function _msgConvMatches(c, pickUids) {
      if (!pickUids.length) return true;
      if (c.group) {
        const have = (Array.isArray(c.members) ? c.members : []).map(m => m.uid);
        return pickUids.every(u => have.indexOf(u) !== -1);
      }
      return pickUids.length === 1 && c.peerUid === pickUids[0];
    }

    function _msgRenderList() {
      const listEl    = $a("ccm-list");
      const convView  = $a("ccm-conv-view");
      const searchRow = $a("ccm-search-row");
      const backBtn   = $a("ccm-back-btn");
      const titleEl   = $a("ccm-title");
      if (!listEl) return;

      listEl.classList.remove("hide");
      if (searchRow) searchRow.classList.remove("hide");
      if (convView)  convView.classList.remove("show");
      if (backBtn)   backBtn.classList.remove("show");
      if (titleEl)   { titleEl.textContent = "Friend Messages"; titleEl.classList.remove("editable"); }
      _msgOpenConvId = null; _msgOpenPeer = null; _msgOpenGroup = null;

      // Build / show the search-to-message bar (recipient picker).
      _ccmEnsureComposer();
      const picks    = _ccmComposeRecipients();
      const pickUids = picks.map(r => r.uid);
      const filtering = pickUids.length > 0;

      listEl.innerHTML = "";

      // In-game room-chat bridge entry (hidden while searching for people).
      if (!filtering && typeof roomId !== "undefined" && roomId) {
        const room = document.createElement("div");
        room.className = "ccm-conv room-chat";
        room.innerHTML = "<div class=\"ccm-av\"><span class=\"ccm-av-letter\">🎮</span></div>"
          + "<div class=\"ccm-conv-body\"><div class=\"ccm-conv-top\"><span class=\"ccm-conv-name\">Room Chat</span></div>"
          + "<div class=\"ccm-conv-preview\">Everyone in this game</div></div>";
        room.addEventListener("click", () => {
          _msgCloseDrawer();
          const chatBtn = $a("pv-chat-btn");
          if (chatBtn && !_chatPanelOpen) chatBtn.click();
          else { const p = $a("pv-chat-panel"); if (p) p.classList.add("open"); }
        });
        listEl.appendChild(room);
      }

      if (!_authUser) {
        listEl.insertAdjacentHTML("beforeend",
          "<div class=\"ccm-empty\"><div class=\"ccm-empty-ico\">💬</div>Sign in to message friends.</div>");
        return;
      }

      const convs = _msgConversations.filter(c => _msgConvMatches(c, pickUids));
      if (convs.length) {
        convs.forEach(c => {
          const row = document.createElement("div");
          row.className = "ccm-conv";
          const previewText = escapeHtml(c.last_text || "No messages yet");
          const timeText    = _msgTimeLabel(c.last_ts);
          const unreadHtml  = (c.unread > 0 ? "<span class=\"ccm-conv-unread\">" + (c.unread > 9 ? "9+" : c.unread) + "</span>" : "");
          if (c.group) {
            row.innerHTML = "<div class=\"ccm-av\"><span class=\"ccm-av-letter\">👥</span></div>"
              + "<div class=\"ccm-conv-body\"><div class=\"ccm-conv-top\"><span class=\"ccm-conv-name\">" + escapeHtml(c.name) + "</span>"
              + "<span class=\"ccm-conv-time\">" + timeText + "</span></div>"
              + "<div class=\"ccm-conv-preview\">" + previewText + "</div></div>" + unreadHtml;
            row.addEventListener("click", () => _msgOpenGroupConv(c.id));
            listEl.appendChild(row);
            return;
          }
          const letter = (String(c.peerName || "?")[0] || "?").toUpperCase();
          row.innerHTML = "<div class=\"ccm-av\"><span class=\"ccm-av-letter\">" + escapeHtml(letter) + "</span>"
            + "<span class=\"ccm-online-dot\"></span></div>"
            + "<div class=\"ccm-conv-body\"><div class=\"ccm-conv-top\"><span class=\"ccm-conv-name\">" + escapeHtml(c.peerName) + "</span>"
            + "<span class=\"ccm-conv-time\">" + timeText + "</span></div>"
            + "<div class=\"ccm-conv-preview\">" + previewText + "</div></div>" + unreadHtml;
          row.addEventListener("click", () => _msgOpenConversation(c.peerUid, c.peerName));
          _msgDecorateRow(row, c.peerUid, c.peerName);
          listEl.appendChild(row);
        });
      } else if (filtering) {
        listEl.insertAdjacentHTML("beforeend",
          "<div class=\"ccm-empty\"><div class=\"ccm-empty-ico\">💬</div>"
          + (picks.length >= 2
              ? "No group with these players yet — tap “Create Group” above to start one."
              : "No chat yet — tap “Message” above to start one.")
          + "</div>");
      } else {
        listEl.insertAdjacentHTML("beforeend",
          "<div class=\"ccm-empty\"><div class=\"ccm-empty-ico\">💬</div>Search a player above to start a chat or group.</div>");
      }
    }

    function _msgFriendRow(f) {
      const row = document.createElement("div");
      row.className = "ccm-conv";
      const letter = (String(f.nickname || "?")[0] || "?").toUpperCase();
      row.innerHTML = "<div class=\"ccm-av\"><span class=\"ccm-av-letter\">" + escapeHtml(letter) + "</span></div>"
        + "<div class=\"ccm-conv-body\"><div class=\"ccm-conv-top\"><span class=\"ccm-conv-name\">" + escapeHtml(f.nickname || "Player") + "</span></div>"
        + "<div class=\"ccm-conv-preview\">Start a conversation</div></div>";
      row.addEventListener("click", () => _msgOpenConversation(f.uid, f.nickname || "Player"));
      _msgDecorateRow(row, f.uid, f.nickname);
      return row;
    }

    // Search-result row for any player (not necessarily a friend). Uses the
    // avatar the search already resolved so the correct icon shows immediately.
    function _msgPlayerRow(pl) {
      const row = document.createElement("div");
      row.className = "ccm-conv";
      const avInner = pl.avatar
        ? "<img src=\"" + escapeHtml(window.__fishAvSrc ? window.__fishAvSrc(pl.avatar) : pl.avatar) + "\" alt=\"\" style=\"width:100%;height:100%;object-fit:cover;border-radius:50%;\">"
        : "<span class=\"ccm-av-letter\">" + escapeHtml((String(pl.name || "?")[0] || "?").toUpperCase()) + "</span>";
      row.innerHTML = "<div class=\"ccm-av\">" + avInner + "</div>"
        + "<div class=\"ccm-conv-body\"><div class=\"ccm-conv-top\"><span class=\"ccm-conv-name\">" + escapeHtml(pl.name || "Player") + "</span></div>"
        + "<div class=\"ccm-conv-preview\">Start a conversation</div></div>";
      row.addEventListener("click", () => _msgOpenConversation(pl.uid, pl.name || "Player"));
      return row;
    }

    // New-message composer in the drawer (recipient picker; 1 = DM, 2+ = group).
    // Uses the SAME shared FishCompose + startChat path as the in-game panel.
    let _ccmComposer = null;
    let _ccmBuilding = false;
    function _ccmEnsureComposer() {
      if (_ccmComposer) return _ccmComposer;
      if (_ccmBuilding) return null;             // onChange can fire mid-build — don't recurse
      const host = $a("ccm-compose");
      if (!host || typeof window.FishCompose !== "function") return null;
      _ccmBuilding = true;
      _ccmComposer = window.FishCompose(host, "ccm", async (recipients, name) => {
        const res = await _msgStartChat(recipients, name);
        if (!res || res.error) {
          if (typeof showToast !== "undefined") showToast((res && res.error) || "Could not start the chat.", "err");
          return;
        }
        if (_ccmComposer) _ccmComposer.reset();
        if (res.group) _msgOpenGroupConv(res.convId);
        else _msgOpenConversation(res.peerUid, res.peerName);
      }, () => {                                   // recipients changed → re-filter the list live
        const drawer = $a("cc-msg-drawer");
        if (drawer && drawer.classList.contains("open") && !_msgOpenConvId) _msgRenderList();
      });
      _ccmBuilding = false;
      return _ccmComposer;
    }

    async function _msgDecorateRow(row, peerUid, peerName) {
      try {
        if (typeof window.__fishAvatarForNick === "function" && peerName) {
          const url = await window.__fishAvatarForNick(peerName);
          const avEl = row.querySelector(".ccm-av");
          if (url && avEl) {
            const dotHtml = (avEl.querySelector(".ccm-online-dot") || { outerHTML: "" }).outerHTML;
            avEl.innerHTML = "<img src=\"" + escapeHtml(url) + "\" alt=\"\" style=\"width:100%;height:100%;object-fit:cover;border-radius:50%;\"> " + dotHtml;
          }
        }
        if (_db && peerUid) {
          const snap = await _db.collection("users").doc(peerUid).get();
          const data = (snap && snap.data()) || {};
          const online = !!data.online;
          const dot = row.querySelector(".ccm-online-dot");
          if (dot) dot.classList.toggle("on", online);
          // Update the displayed name with the live nickname (the stored message name may be stale)
          const liveNick = data.nickname || null;
          if (liveNick) {
            const nameSpan = row.querySelector(".ccm-conv-name");
            if (nameSpan) nameSpan.textContent = liveNick;
          }
        }
      } catch {}
    }

    function _msgOpenConversation(peerUid, peerName) {
      if (!_authUser || !peerUid) return;
      if (_ccmComposer) _ccmComposer.reset();      // opening a chat clears the search bar
      _msgOpenPeer   = { uid: peerUid, name: peerName };
      _msgOpenGroup  = null;
      _msgOpenConvId = _convIdFor(_authUser.uid, peerUid);
      _msgShowConvView(peerName || "Conversation");
      _msgRenderOpenConversation();
      // Async refresh: replace stale cached name with the live nickname from Firestore
      if (_db && peerUid) {
        _db.collection("users").doc(peerUid).get().then(snap => {
          const liveNick = (snap && snap.data() && snap.data().nickname) || null;
          if (liveNick && _msgOpenPeer && _msgOpenPeer.uid === peerUid) {
            _msgOpenPeer = { uid: peerUid, name: liveNick };
            const titleEl = $a("ccm-title");
            if (titleEl && !_msgOpenGroup) titleEl.textContent = liveNick;
          }
        }).catch(() => {});
      }
    }

    // Open a group conversation in the drawer.
    function _msgOpenGroupConv(convId) {
      if (!_authUser || !convId) return;
      if (_ccmComposer) _ccmComposer.reset();      // opening a chat clears the search bar
      const meta = _msgGroupMeta(convId);
      _msgOpenGroup  = { id: convId, name: (meta && meta.name) || "Group",
                         members: (meta && meta.members) || [] };
      _msgOpenPeer   = null;
      _msgOpenConvId = convId;
      _msgShowConvView(_msgOpenGroup.name);
      _msgRenderOpenConversation();
    }

    // Shared drawer view switch into the conversation pane.
    function _msgShowConvView(title) {
      const listEl    = $a("ccm-list");
      const convView  = $a("ccm-conv-view");
      const searchRow = $a("ccm-search-row");
      const backBtn   = $a("ccm-back-btn");
      const titleEl   = $a("ccm-title");
      const compose   = $a("ccm-compose");
      if (listEl)    listEl.classList.add("hide");
      if (searchRow) searchRow.classList.add("hide");
      if (compose)   compose.classList.remove("show");
      if (convView)  convView.classList.add("show");
      if (backBtn)   backBtn.classList.add("show");
      if (titleEl)   {
        titleEl.textContent = title || "Conversation";
        titleEl.classList.toggle("editable", !!_msgOpenGroup);   // tap to rename groups
      }

      const guestNote = $a("ccm-guest-note");
      const inputRow  = $a("ccm-input-row");
      const isGuest   = (_guestSessionActive === true);
      if (guestNote) guestNote.style.display = isGuest ? "" : "none";
      if (inputRow)  inputRow.style.display  = isGuest ? "none" : "flex";
    }

    // Rename the open group by tapping its title (inline edit + in-chat notice).
    async function _ccmRenameGroupTitle() {
      if (!_msgOpenGroup || !_msgOpenConvId) return;
      if (_guestSessionActive === true) { if (typeof showToast !== "undefined") showToast("Sign in to rename groups.", "info"); return; }
      const titleEl = $a("ccm-title");
      if (!titleEl || titleEl.dataset.editing === "1") return;
      const cur = _msgOpenGroup.name || "";
      titleEl.dataset.editing = "1";
      const input = document.createElement("input");
      input.type = "text"; input.maxLength = 40; input.value = cur; input.className = "ccm-title-edit";
      titleEl.textContent = ""; titleEl.appendChild(input);
      setTimeout(() => { input.focus(); input.select(); }, 20);
      let done = false;
      const finish = async (commit) => {
        if (done) return; done = true;
        const newName = (input.value || "").trim();
        titleEl.dataset.editing = "";
        if (commit && newName && newName !== cur) {
          const r = await _msgRenameGroup(_msgOpenConvId, newName);
          if (r && r.error) { if (typeof showToast !== "undefined") showToast(r.error, "err"); titleEl.textContent = cur; return; }
          _msgOpenGroup.name = (r && r.name) || newName;
          titleEl.textContent = _msgOpenGroup.name;
          _msgRenderOpenConversation();           // surface the "X changed the name" notice
        } else {
          titleEl.textContent = cur;
        }
      };
      input.addEventListener("click", (e) => e.stopPropagation());
      input.addEventListener("keydown", (e) => {
        if (e.key === "Enter")  { e.preventDefault(); finish(true); }
        else if (e.key === "Escape") { e.preventDefault(); finish(false); }
      });
      input.addEventListener("blur", () => finish(true));
    }

    // Render the currently-open conversation from the cached messages.
    function _msgRenderOpenConversation() {
      const msgsEl = $a("ccm-messages");
      if (!msgsEl || !_msgOpenConvId) return;
      const isGroup = !!_msgOpenGroup;
      const msgs = _msgAllMessages
        .filter(m => m.conv_id === _msgOpenConvId && !m.meta)
        .sort((a, b) => _msgTs(a) - _msgTs(b));
      msgsEl.innerHTML = "";
      if (!msgs.length) {
        msgsEl.innerHTML = "<div class=\"ccm-empty\" style=\"padding:24px;\">No messages yet. Say hi! 🐟</div>";
      } else {
        msgs.forEach(m => {
          if (m.system) {
            const sys = document.createElement("div"); sys.className = "ccm-sys";
            sys.textContent = m.text || ""; msgsEl.appendChild(sys);
            return;
          }
          const mine = m.sender === _authUser.uid;
          const bub  = document.createElement("div");
          bub.className = "ccm-bubble " + (mine ? "mine" : "theirs");
          // Group chats label each non-mine bubble with the sender's icon + name.
          const nm = m.sender_name || "Player";
          const senderTag = (isGroup && !mine)
            ? "<span class=\"ccm-bubble-sender\" data-nick=\"" + escapeHtml(nm) + "\">"
              + "<span class=\"ccm-bubble-av\"><span class=\"ccm-bubble-av-lt\">"
              + escapeHtml((String(nm)[0] || "?").toUpperCase()) + "</span></span>"
              + "<span>" + escapeHtml(nm) + "</span></span>"
            : "";
          bub.innerHTML = senderTag + escapeHtml(m.text || "") + "<span class=\"ccm-bubble-time\">" + _msgTimeLabel(m.ts) + "</span>";
          msgsEl.appendChild(bub);
        });
        // Swap each group sender's letter avatar for their real icon (cached).
        if (isGroup && typeof window.__fishAvatarForNick === "function") {
          msgsEl.querySelectorAll(".ccm-bubble-sender[data-nick]").forEach(el => {
            const nick = el.getAttribute("data-nick");
            if (!nick) return;
            window.__fishAvatarForNick(nick).then(url => {
              if (!url) return;
              const av = el.querySelector(".ccm-bubble-av");
              if (av) av.innerHTML = "<img src=\"" + escapeHtml(window.__fishAvSrc ? window.__fishAvSrc(url) : url) + "\" alt=\"\" style=\"width:100%;height:100%;object-fit:cover;\">";
            }).catch(() => {});
          });
        }
        msgsEl.scrollTop = msgsEl.scrollHeight;
      }
      _msgMarkConvRead(_msgOpenConvId);
    }

    // Mark my received messages in this conversation as read.
    async function _msgMarkConvRead(convId) {
      if (!_db || !_authUser || !convId) return;
      const unread = _msgAllMessages.filter(m =>
        m.conv_id === convId && !m.meta && m.sender !== _authUser.uid && !m.read);
      for (const m of unread) {
        try {
          await _db.collection("users").doc(_authUser.uid)
            .collection("messages").doc(m.id).update({ read: true });
        } catch {}
      }
    }

    // Drawer send button — dispatches to a DM or group based on the open conv.
    async function _msgSend() {
      if (_guestSessionActive === true) return;   // guests cannot send
      const input = $a("ccm-input");
      if (!input) return;
      const text = (input.value || "").trim();
      if (!text || text.length > 500) return;       // block empty / oversized
      input.value = "";
      input.style.height = "";
      if (_msgOpenGroup) await _msgSendGroup(_msgOpenGroup.id, text);
      else if (_msgOpenPeer) await _msgSendTo(_msgOpenPeer.uid, _msgOpenPeer.name, text);
    }

    // Send a direct message to one peer. Returns true on success.
    async function _msgSendTo(peerUid, peerName, text) {
      if (!_db || !_authUser || !peerUid) return false;
      if (_guestSessionActive === true) return false;
      text = (text || "").trim();
      if (!text || text.length > 500) return false;
      text = CC_PROFANITY.clean(text);   // mask swears in direct messages
      const convId = _convIdFor(_authUser.uid, peerUid);
      const msgId = _db.collection("users").doc(_authUser.uid).collection("messages").doc().id;
      const now   = firebase.firestore.FieldValue.serverTimestamp();
      const base  = {
        conv_id:       convId,
        sender:        _authUser.uid,
        sender_name:   _playerNickname || "Player",
        receiver:      peerUid,
        receiver_name: peerName || "Player",
        text:          text,
        ts:            now,
      };
      try {
        await _db.collection("users").doc(_authUser.uid).collection("messages").doc(msgId)
          .set(Object.assign({}, base, { read: true }));
        await _db.collection("users").doc(peerUid).collection("messages").doc(msgId)
          .set(Object.assign({}, base, { read: false }));
        return true;
      } catch (e) {
        console.warn("[msg] send failed:", e);
        if (e && e.code === "permission-denied") { _msgShowRulesNeeded(); return false; }
        if (typeof showToast !== "undefined") showToast("Could not send — " + ((e && e.code) || "error"), "err");
        return false;
      }
    }

    // Send a message to every current member of a group. Returns true on success.
    async function _msgSendGroup(convId, text) {
      if (!_db || !_authUser || !convId) return false;
      if (_guestSessionActive === true) return false;
      text = (text || "").trim();
      if (!text || text.length > 500) return false;
      text = CC_PROFANITY.clean(text);   // mask swears in group messages
      const meta = _msgGroupMeta(convId);
      const members = (meta && Array.isArray(meta.members)) ? meta.members : [];
      if (!members.some(p => p && p.uid === _authUser.uid)) return false;  // not a member
      const msgId = _db.collection("users").doc(_authUser.uid).collection("messages").doc().id;
      const now   = firebase.firestore.FieldValue.serverTimestamp();
      const base  = {
        conv_id:     convId,
        group:       true,
        sender:      _authUser.uid,
        sender_name: _playerNickname || "Player",
        text:        text,
        ts:          now,
      };
      try {
        for (const p of members) {
          if (!p || !p.uid) continue;
          await _db.collection("users").doc(p.uid).collection("messages").doc(msgId)
            .set(Object.assign({}, base, { read: p.uid === _authUser.uid }));
        }
        return true;
      } catch (e) {
        console.warn("[msg] group send failed:", e);
        if (e && e.code === "permission-denied") { _msgShowRulesNeeded(); return false; }
        if (typeof showToast !== "undefined") showToast("Could not send — " + ((e && e.code) || "error"), "err");
        return false;
      }
    }

    // Post a system notice (e.g. "X renamed the group") to every current
    // member. Stored like a group message but flagged system:true so it renders
    // as a centered grey line, and read:true for everyone so it never nags.
    async function _msgPostGroupSystem(convId, text) {
      if (!_db || !_authUser || !convId) return false;
      text = (text || "").trim();
      if (!text) return false;
      const meta = _msgGroupMeta(convId);
      const members = (meta && Array.isArray(meta.members)) ? meta.members : [];
      if (!members.length) return false;
      const msgId = _db.collection("users").doc(_authUser.uid).collection("messages").doc().id;
      const base  = {
        conv_id:     convId,
        group:       true,
        system:      true,
        sender:      _authUser.uid,
        sender_name: _playerNickname || "Player",
        text:        text,
        ts:          firebase.firestore.FieldValue.serverTimestamp(),
      };
      try {
        for (const pm of members) {
          if (!pm || !pm.uid) continue;
          await _db.collection("users").doc(pm.uid).collection("messages").doc(msgId)
            .set(Object.assign({}, base, { read: true }));
        }
        return true;
      } catch (e) {
        console.warn("[msg] system notice failed:", e);
        return false;
      }
    }

    // Resolve a free-text list of player names → uids.
    //   returns { valid:[{uid,name}], invalid:[name…], notFound:[name…] }
    // Self and duplicates are de-duped silently; unknown names are reported.
    async function _msgResolveNames(rawNames) {
      const out = { valid: [], invalid: [], notFound: [] };
      if (!_db || !_authUser) return out;
      const myName = (_playerNickname || "").trim().toLowerCase();
      const seen = {};
      const tokens = String(rawNames || "")
        .split(/[\n,;]+/).map(s => s.trim()).filter(Boolean);
      for (const tok of tokens) {
        const key = tok.toLowerCase();
        if (key === myName) continue;          // creator is always added separately
        if (seen[key]) continue;               // duplicate
        seen[key] = true;
        if (tok.length > 40) { out.invalid.push(tok); continue; }
        try {
          let snap = await _db.collection("users")
            .where("nickname_lower", "==", key).limit(1).get();
          // Fallback for legacy profiles that never stored nickname_lower.
          if (snap.empty) {
            snap = await _db.collection("users")
              .where("nickname", "==", tok).limit(1).get();
          }
          if (snap.empty) { out.notFound.push(tok); continue; }
          const d = snap.docs[0];
          if (d.id === _authUser.uid) continue;   // typed self by a different casing
          if (out.valid.some(p => p.uid === d.id)) continue;  // same player, two names
          out.valid.push({ uid: d.id, name: (d.data() || {}).nickname || tok });
        } catch (_) { out.notFound.push(tok); }
      }
      return out;
    }

    // Live player search by nickname prefix — the data source behind the
    // iMessage-style recipient suggestions (in-game panel AND lobby drawer).
    // Returns [{ uid, name, avatar }] (avatar validated against the known set;
    // null → caller shows the initial). Excludes self and de-dupes.
    async function _msgSearchPlayers(prefix, limit) {
      const term = String(prefix || "").trim().toLowerCase();
      limit = limit || 8;
      if (!_db || !_authUser || !term) return [];
      const out = [], seen = {};
      try {
        const snap = await _db.collection("users")
          .where("nickname_lower", ">=", term)
          .where("nickname_lower", "<", term + "")
          .orderBy("nickname_lower")
          .limit(limit + 8).get();
        snap.forEach(d => {
          if (d.id === _authUser.uid || seen[d.id]) return;
          const data = d.data() || {};
          const name = data.nickname || "";
          if (!name) return;
          seen[d.id] = true;
          const norm = normalizeAvatarUrl(data.avatar_url || "");
          const avatar = (norm && animalByImg(norm)) ? norm : null;
          out.push({ uid: d.id, name, avatar });
        });
      } catch (e) {
        // Missing nickname_lower / index → no suggestions (exact-name start still works).
        console.warn("[msg] searchPlayers failed:", e);
      }
      return out.slice(0, limit);
    }

    // Find an existing group whose member set is EXACTLY {me + recipients}.
    function _msgFindGroupByMembers(uids) {
      const want = uids.slice().sort();
      return _msgConversations.find(c => {
        if (!c.group || !Array.isArray(c.members)) return false;
        const have = c.members.map(m => m.uid).sort();
        return have.length === want.length && have.every((u, i) => u === want[i]);
      }) || null;
    }

    // Unified "start a conversation" used by BOTH the in-game composer and the
    // lobby composer so the two surfaces behave identically.
    //   recipients: [{ uid, name }] (self/dupes dropped here too)
    //   1 recipient  → open/create the DM (deterministic id ⇒ never duplicates)
    //   2+ recipients → open the existing matching group, else create one
    // Returns { ok, group, convId, peerUid, peerName, name } or { error }.
    async function _msgStartChat(recipients, optName) {
      if (!_db || !_authUser) return { error: "Not signed in." };
      if (_guestSessionActive === true) return { error: "Sign in to start a chat." };
      const uniq = [], seen = {};
      (recipients || []).forEach(r => {
        if (!r || !r.uid || r.uid === _authUser.uid || seen[r.uid]) return;
        seen[r.uid] = true;
        uniq.push({ uid: r.uid, name: r.name || "Player" });
      });
      if (!uniq.length) return { error: "Add at least one player." };
      if (uniq.length === 1) {
        const p = uniq[0];
        return { ok: true, group: false, convId: _convIdFor(_authUser.uid, p.uid),
                 peerUid: p.uid, peerName: p.name };
      }
      // Group — reuse the existing group with the same members if there is one.
      const wantUids = [_authUser.uid].concat(uniq.map(p => p.uid));
      const existing = _msgFindGroupByMembers(wantUids);
      if (existing) return { ok: true, group: true, convId: existing.id, name: existing.name };
      const name = CC_PROFANITY.clean(String(optName || "").trim().slice(0, 40))
        || uniq.map(p => p.name).join(", ").slice(0, 40);
      const convId  = _newGroupConvId();
      const members = [{ uid: _authUser.uid, name: _playerNickname || "Player" }].concat(uniq);
      try {
        await _msgWriteMeta(convId, name, members, members);
        // Optimistically seed my cache so the group can be opened immediately
        // (the snapshot listener overwrites _msgAllMessages on its next tick).
        _msgAllMessages.push({ id: "gm_" + convId, conv_id: convId, group: true, meta: true,
                               name, members, owner: _authUser.uid, ts: null, read: true });
        _msgRebuildConversations();
        return { ok: true, group: true, convId, name };
      } catch (e) {
        console.warn("[msg] start group failed:", e);
        if (e && e.code === "permission-denied") { _msgShowRulesNeeded(); }
        return { error: "Could not create the group — " + ((e && e.code) || "error") };
      }
    }

    // Write/overwrite the deterministic meta doc to every listed member.
    async function _msgWriteMeta(convId, name, members, recipients) {
      const meta = {
        conv_id: convId, group: true, meta: true,
        name: name, members: members,
        owner: _authUser.uid,
        ts: firebase.firestore.FieldValue.serverTimestamp(),
        read: true,
      };
      for (const p of recipients) {
        if (!p || !p.uid) continue;
        await _db.collection("users").doc(p.uid).collection("messages")
          .doc("gm_" + convId).set(meta);
      }
    }

    // Create a new group from a free-text list of names.
    //   returns { ok, convId, name, added:[name…] } or { error }
    async function _msgCreateGroup(rawNames, groupName) {
      if (!_db || !_authUser) return { error: "Not signed in." };
      if (_guestSessionActive === true) return { error: "Sign in to create group chats." };
      const name = String(groupName || "").trim();
      if (!name) return { error: "Give the group a name." };
      if (name.length > 40) return { error: "Group name is too long (40 max)." };
      const res = await _msgResolveNames(rawNames);
      if (res.notFound.length || res.invalid.length) {
        const bad = res.notFound.concat(res.invalid);
        return { error: "These players were not found: " + bad.join(", ") };
      }
      if (res.valid.length < 2) {
        return { error: "Add at least 2 other players to start a group." };
      }
      const convId  = _newGroupConvId();
      const members = [{ uid: _authUser.uid, name: _playerNickname || "Player" }].concat(res.valid);
      try {
        await _msgWriteMeta(convId, name, members, members);
        return { ok: true, convId, name, added: res.valid.map(p => p.name) };
      } catch (e) {
        console.warn("[msg] create group failed:", e);
        if (e && e.code === "permission-denied") { _msgShowRulesNeeded(); }
        return { error: "Could not create the group — " + ((e && e.code) || "error") };
      }
    }

    // Rename a group; persists for every current member.
    async function _msgRenameGroup(convId, newName) {
      if (!_db || !_authUser || !convId) return { error: "Not available." };
      let name = String(newName || "").trim();
      if (!name) return { error: "Enter a name." };
      if (name.length > 40) return { error: "Group name is too long (40 max)." };
      name = CC_PROFANITY.clean(name);   // mask swears in group names
      const meta = _msgGroupMeta(convId);
      const members = (meta && Array.isArray(meta.members)) ? meta.members : [];
      if (!members.some(p => p && p.uid === _authUser.uid)) return { error: "You're not in this group." };
      const oldName = (meta && meta.name) || "";
      if (name === oldName) return { ok: true, name };   // nothing actually changed
      try {
        await _msgWriteMeta(convId, name, members, members);
        if (_msgOpenGroup && _msgOpenGroup.id === convId) _msgOpenGroup.name = name;
        // Let everyone know who renamed it (iMessage-style centred notice).
        try { await _msgPostGroupSystem(convId, (_playerNickname || "Someone") + " changed the group name to “" + name + "”"); } catch (_) {}
        return { ok: true, name };
      } catch (e) {
        console.warn("[msg] rename group failed:", e);
        if (e && e.code === "permission-denied") { _msgShowRulesNeeded(); }
        return { error: "Could not rename — " + ((e && e.code) || "error") };
      }
    }

    // Add one or more members (by name) to an existing group.
    async function _msgAddMembers(convId, rawNames) {
      if (!_db || !_authUser || !convId) return { error: "Not available." };
      const meta = _msgGroupMeta(convId);
      const current = (meta && Array.isArray(meta.members)) ? meta.members.slice() : [];
      if (!current.some(p => p && p.uid === _authUser.uid)) return { error: "You're not in this group." };
      const res = await _msgResolveNames(rawNames);
      if (res.notFound.length || res.invalid.length) {
        return { error: "These players were not found: " + res.notFound.concat(res.invalid).join(", ") };
      }
      const added = res.valid.filter(p => !current.some(c => c.uid === p.uid));
      if (!added.length) return { error: "Those players are already in the group." };
      const members = current.concat(added);
      try {
        await _msgWriteMeta(convId, (meta && meta.name) || "Group", members, members);
        if (_msgOpenGroup && _msgOpenGroup.id === convId) _msgOpenGroup.members = members;
        return { ok: true, added: added.map(p => p.name) };
      } catch (e) {
        console.warn("[msg] add members failed:", e);
        if (e && e.code === "permission-denied") { _msgShowRulesNeeded(); }
        return { error: "Could not add members — " + ((e && e.code) || "error") };
      }
    }

    // Leave a group: drop myself from the roster for everyone else, then remove
    // my own copies so it disappears from my list.
    async function _msgLeaveGroup(convId) {
      if (!_db || !_authUser || !convId) return { error: "Not available." };
      const meta = _msgGroupMeta(convId);
      const members = (meta && Array.isArray(meta.members)) ? meta.members : [];
      const remaining = members.filter(p => p && p.uid !== _authUser.uid);
      try {
        if (remaining.length) {
          await _msgWriteMeta(convId, (meta && meta.name) || "Group", remaining, remaining);
        }
        // Delete all my own docs for this conv (meta + messages).
        const mine = _msgAllMessages.filter(m => m.conv_id === convId);
        for (const m of mine) {
          try {
            await _db.collection("users").doc(_authUser.uid)
              .collection("messages").doc(m.id).delete();
          } catch (_) {}
        }
        if (_msgOpenGroup && _msgOpenGroup.id === convId) { _msgOpenGroup = null; _msgOpenConvId = null; }
        return { ok: true };
      } catch (e) {
        console.warn("[msg] leave group failed:", e);
        return { error: "Could not leave — " + ((e && e.code) || "error") };
      }
    }

    function _msgOpenDrawer() {
      const drawer = $a("cc-msg-drawer");
      if (!drawer) return;
      const inGame = (typeof roomId !== "undefined" && !!roomId);
      drawer.classList.toggle("in-game", inGame);
      drawer.classList.add("open");
      if (_authUser) _msgStartListListener();
      _ccmEnsureComposer();
      if (_ccmComposer) _ccmComposer.reset();      // fresh search bar each time the drawer opens
      _msgRenderList();
    }
    function _msgCloseDrawer() {
      const drawer = $a("cc-msg-drawer");
      if (drawer) drawer.classList.remove("open");
      _msgOpenConvId = null; _msgOpenPeer = null; _msgOpenGroup = null;
    }
    window.__fishOpenMessages = _msgOpenDrawer;

    // ── Bridge API for the in-game iMessage panel ────────────────
    // The in-game chat panel lives in the outer game script; it reaches the
    // Firestore messaging layer (DMs + groups) through this single object so
    // both surfaces share ONE data source and stay in sync.
    window.__fishMsg = {
      ready:        () => !!(_db && _authUser),
      isGuest:      () => _guestSessionActive === true,
      myUid:        () => (_authUser ? _authUser.uid : null),
      myName:       () => _playerNickname || "Player",
      ensureListener: () => { if (_authUser) _msgStartListListener(); },
      conversations: () => _msgConversations.slice(),
      totalUnread:  () => _msgTotalUnread,
      unreadFor:    (convId) => _msgAllMessages.filter(m =>
                       m.conv_id === convId && !m.meta && m.sender !== _authUser.uid && !m.read).length,
      messagesFor:  (convId) => _msgAllMessages
                       .filter(m => m.conv_id === convId && !m.meta)
                       .sort((a, b) => _msgTs(a) - _msgTs(b)),
      groupMeta:    (convId) => _msgGroupMeta(convId),
      timeLabel:    (ts) => _msgTimeLabel(ts),
      markRead:     (convId) => _msgMarkConvRead(convId),
      sendDM:       (peerUid, peerName, text) => _msgSendTo(peerUid, peerName, text),
      sendGroup:    (convId, text) => _msgSendGroup(convId, text),
      createGroup:  (rawNames, name) => _msgCreateGroup(rawNames, name),
      renameGroup:  (convId, name) => _msgRenameGroup(convId, name),
      addMembers:   (convId, rawNames) => _msgAddMembers(convId, rawNames),
      leaveGroup:   (convId) => _msgLeaveGroup(convId),
      searchPlayers:(prefix, limit) => _msgSearchPlayers(prefix, limit),
      startChat:    (recipients, name) => _msgStartChat(recipients, name),
      avatarForNick:(nick) => (typeof window.__fishAvatarForNick === "function"
                       ? window.__fishAvatarForNick(nick) : Promise.resolve(null)),
      onChange:     (cb) => { if (typeof cb === "function") { _msgChangeCbs.push(cb);
                       return () => { const i = _msgChangeCbs.indexOf(cb); if (i >= 0) _msgChangeCbs.splice(i, 1); }; }
                       return () => {}; },
    };

    // Wire drawer controls
    const _msgBtn = $a("stats-message-btn");
    if (_msgBtn) _msgBtn.addEventListener("click", _msgOpenDrawer);
    const _ccmClose = $a("ccm-close");
    if (_ccmClose) _ccmClose.addEventListener("click", _msgCloseDrawer);
    const _ccmBack = $a("ccm-back-btn");
    if (_ccmBack) _ccmBack.addEventListener("click", () => { if (_ccmComposer) _ccmComposer.reset(); _msgRenderList(); });
    const _ccmSend = $a("ccm-send");
    if (_ccmSend) _ccmSend.addEventListener("click", _msgSend);
    const _ccmInput = $a("ccm-input");
    if (_ccmInput) _ccmInput.addEventListener("keydown", (e) => {
      if (e.key === "Enter" && !e.shiftKey) { e.preventDefault(); _msgSend(); }
    });
    // The drawer title doubles as a rename control when a group is open.
    const _ccmTitle = $a("ccm-title");
    if (_ccmTitle) _ccmTitle.addEventListener("click", () => {
      if (_msgOpenGroup && _msgOpenConvId) _ccmRenameGroupTitle();
    });
    // Start listening to conversations as soon as we know the user (badge updates)
    if (_authUser) _msgStartListListener();

    // ── Help & Feedback modal ──────────────────────────────────────
    // Top-right help button → friendly ocean-themed modal with three
    // cards. Each card is a link to its own Google Form (Ask a Question /
    // Report a Bug / Suggest an Idea) that the player fills out; the form
    // responses go to the Currents & Critters team. The card <a> tags
    // handle the navigation themselves (target="_blank"); the JS just
    // opens/closes the modal and dismisses it once a form is launched.
    (function wireHelpFeedback() {
      const modal   = $a("ph-help-modal");
      const openBtn = $a("stats-help-btn");
      if (!modal || !openBtn) return;
      const closeBtn = $a("ph-help-close");
      const cards    = Array.from(modal.querySelectorAll(".ph-help-card"));

      function openModal()  { modal.classList.add("open"); }
      function closeModal() { modal.classList.remove("open"); }

      openBtn.addEventListener("click", openModal);
      if (closeBtn) closeBtn.addEventListener("click", closeModal);
      modal.addEventListener("click", (e) => { if (e.target === modal) closeModal(); });
      document.addEventListener("keydown", (e) => {
        if (e.key === "Escape" && modal.classList.contains("open")) closeModal();
      });
      // Once the player opens a form (in a new tab), close the modal so the
      // home screen is clean when they switch back.
      cards.forEach(card => card.addEventListener("click", () => {
        setTimeout(closeModal, 60);
      }));
    })();

    // Guest notice sign-in link
    const guestSigninLink = $a("stats-guest-signin-link");
    if (guestSigninLink) guestSigninLink.addEventListener("click", () => {
      if (window.__fishGoToSignIn) window.__fishGoToSignIn();
    });

    // ── Friends button (legacy lobby) — navigate to friends tab ──
    const _authFriendBtn = $a("auth-friend-btn");
    if (_authFriendBtn) _authFriendBtn.addEventListener("click", () => {
      if (typeof window._switchPhTab === "function") window._switchPhTab("friends");
    });

    // renderFriendsList no-op: modal removed, friends tab uses renderPhFriendsList
    async function renderFriendsList() {}

    // ── Player Home: tab switching ───────────────────────────────
    (function() {
      const tabs = document.querySelectorAll("#ph-tabs .ph-tab");
      const panels = { overview:"ph-panel-overview", normal:"ph-panel-normal", competitive:"ph-panel-competitive", history:"ph-panel-history", friends:"ph-panel-friends", achievements:"ph-panel-achievements", leaderboard:"ph-panel-leaderboard", store:"ph-panel-store" };
      const statsLobby = document.getElementById("auth-stats-lobby");
      // Tabs that require a real account; guests see a "Sign in to…" gate.
      const GUEST_GATE_MSGS = {
        normal:       "Sign in to track your stats",
        competitive:  "Sign in to track your competitive stats",
        history:      "Sign in to view your game history",
        friends:      "Sign in to add friends",
        leaderboard:  "Sign in to view the leaderboards",
        achievements: "Sign in to see Achievements",
      };
      function _ensureGuestGate(panelEl, msg) {
        let gate = panelEl.querySelector(":scope > .ph-guest-gate");
        if (!gate) {
          gate = document.createElement("div");
          gate.className = "ph-guest-gate";
          gate.innerHTML = '<div class="ph-guest-gate-ico">🔒</div>'
            + '<div class="ph-guest-gate-msg"></div>'
            + '<div class="ph-guest-gate-sub">Create a free account to save your progress across devices.</div>'
            + '<button class="ph-guest-gate-btn">Sign In</button>';
          gate.querySelector(".ph-guest-gate-btn").addEventListener("click", () => {
            if (typeof window.__fishGoToSignIn === "function") window.__fishGoToSignIn();
          });
          panelEl.insertBefore(gate, panelEl.firstChild);
        }
        gate.querySelector(".ph-guest-gate-msg").textContent = msg;
      }
      function switchTab(name) {
        // Changing tabs returns every hidden critter to its untouched state.
        try { if (typeof window.__fishResetSecrets === "function") window.__fishResetSecrets(); } catch (_) {}
        if (statsLobby) statsLobby.setAttribute("data-bg-tab", name || "normal");
        tabs.forEach(t => t.classList.toggle("active", t.dataset.tab === name));
        const isGuest = !_authUser;   // guest or not-signed-in
        Object.entries(panels).forEach(([k, id]) => {
          const el = document.getElementById(id);
          if (!el) return;
          el.style.display = k === name ? "" : "none";
          // Apply / clear the guest gate on gated panels
          const gated = isGuest && !!GUEST_GATE_MSGS[k];
          el.classList.toggle("is-guest-gated", gated);
          if (gated) _ensureGuestGate(el, GUEST_GATE_MSGS[k]);
        });
        // Skip data renders for gated panels (content is hidden anyway).
        const gatedNow = isGuest && !!GUEST_GATE_MSGS[name];
        if (gatedNow) return;
        if (name === "friends")      { renderPhFriendsList(); if (_authUser && typeof window.__fishCheckFriendAchievements === "function") window.__fishCheckFriendAchievements(_authUser.uid); }
        if (name === "history")      renderPhHistory();
        if (name === "overview")     renderPhOverview();
        if (name === "achievements") renderPhAchievements();
        if (name === "competitive")  { checkAndApplySeasonReset().then(() => renderPhCompetitive()); }
        if (name === "leaderboard")  renderPhLeaderboard();
        if (name === "store")        renderPhStore();
      }
      window._switchPhTab = switchTab;
      tabs.forEach(t => t.addEventListener("click", () => switchTab(t.dataset.tab)));

      // Sidebar nav — mirror horizontal tab switching + keep active state in sync
      const snavItems = document.querySelectorAll(".ph-snav-item[data-tab]");
      snavItems.forEach(btn => btn.addEventListener("click", () => switchTab(btn.dataset.tab)));
      // Extend switchTab to also update sidebar active state
      const _origSwitchTab = switchTab;
      switchTab = function(name) {
        _origSwitchTab(name);
        snavItems.forEach(b => b.classList.toggle("active", b.dataset.tab === name));
      };
      window._switchPhTab = switchTab;
      // Settings sidebar button → open settings modal
      const snavSettings = document.getElementById("snav-settings");
      if (snavSettings) snavSettings.addEventListener("click", () => {
        if (typeof _openSettingsModal === "function") _openSettingsModal();
        else { const sb = document.getElementById("stats-settings-btn"); if (sb) sb.click(); }
      });

      // ── Store: Stripe-hosted checkout ───────────────────────────────
      // We NEVER collect card details on our site and never build a fake
      // checkout. Every "Buy"/"Become" button hands the player off to a
      // Stripe-hosted Payment Link. After Stripe confirms payment, our Stripe
      // webhook is what actually credits Critter Coins / grants the tier to the
      // account named by client_reference_id (set below).
      (function initStore() {

        // Attach the signed-in Google account to a Payment Link so Stripe (and
        // our webhook) knows exactly which player to fulfill:
        //   • client_reference_id → Firebase uid (the Google sign-in)
        //   • prefilled_email     → account email (fills in Stripe's email box
        //                            and is a fallback match key)
        function _phstStripeUrl(baseUrl) {
          try {
            const u = new URL(baseUrl);
            const uid = _authUser && _authUser.uid;
            const email = _authUser && _authUser.email;
            if (uid) u.searchParams.set("client_reference_id", uid);
            if (email) u.searchParams.set("prefilled_email", email);
            return u.toString();
          } catch (e) {
            return baseUrl; // malformed URL — send them to the raw link rather than break
          }
        }

        // Open a Stripe Payment Link in the SAME tab. Require sign-in first so
        // the purchase is tied to a Google account (otherwise the webhook has
        // no one to credit and the coins/tier can't be delivered).
        function _phstGoToStripe(baseUrl) {
          if (!baseUrl) return;
          if (!_authUser) {
            if (typeof showToast === "function")
              showToast("Sign in with Google first so your purchase is added to your account.", "info");
            return;
          }
          window.location.href = _phstStripeUrl(baseUrl);
        }

        window._phstGoToStripe = _phstGoToStripe;
      })();

      const phstFmtCoins = (n) => Number(n).toLocaleString("en-US");

      // ═══════════════════════════════════════════════════════════════════
      //  STRIPE PAYMENT LINKS
      //  ⚠️ TEST MODE — every URL below is a Stripe TEST Payment Link and only
      //  works with Stripe test cards. BEFORE LAUNCH, replace each `link:` with
      //  the matching LIVE Payment Link from the Stripe Dashboard
      //  (Payments → Payment Links). Do NOT swap these for a custom/fake
      //  checkout — only ever hand off to Stripe-hosted links.
      // ═══════════════════════════════════════════════════════════════════

      // 1) Critter Coins packs — $1 = 1,000 coins, bigger packs add a bonus.
      const PHST_COIN_PACKS = [
        { usd: 1,  coins: 1000,  bonus: 0,             link: "https://buy.stripe.com/test_4gMeVf3JafX86ON4X3bAs03" },
        { usd: 5,  coins: 5250,  bonus: 5,             link: "https://buy.stripe.com/test_5kQ28t4Ne9yKddb1KRbAs04" },
        { usd: 10, coins: 11500, bonus: 15,            link: "https://buy.stripe.com/test_dRm9AVdjKeT43CBgFLbAs05" },
        { usd: 20, coins: 25000, bonus: 25, best: true, link: "https://buy.stripe.com/test_28E8wRbbCdP0a0ZblrbAs06" },
      ];

      // 2) Supporter Tiers — one-time contributions. Perks are cosmetic /
      //    progression only and are granted server-side after Stripe payment.
      const PHST_SUPPORTER_TIERS = [
        {
          name: "Wave Warrior", usd: 15,
          link: "https://buy.stripe.com/test_5kQeVfgvW6mygpn9djbAs00",
          perks: [
            "Supporter email updates",
            "Online simulation access (free now — and free for you when it becomes paid)",
            "Founder Supporter number",
            "Name on the Supporter Reef Wall",
            "Personal thank-you email",
            "+10,000 bonus XP",
          ],
          note: "Cosmetic progression only",
        },
        {
          name: "Ocean Ally", usd: 35,
          link: "https://buy.stripe.com/test_5kQfZj5RicKW6ONcpvbAs01",
          perks: [
            "Supporter email updates",
            "Online simulation access",
            "Founder Supporter number",
            "Name on the Supporter Reef Wall",
            "Personal thank-you email",
            "Unlock all backgrounds",
            "Exclusive Fish Icon",
            "+25,000 bonus XP",
          ],
          note: "Cosmetic progression only",
        },
        {
          name: "Tide Turner", usd: 50, best: true,
          link: "https://buy.stripe.com/test_8x2cN793u6myb5389fbAs02",
          perks: [
            "Supporter email updates",
            "Online simulation access",
            "Founder Supporter number",
            "Name on the Supporter Reef Wall",
            "Personal thank-you email",
            "Unlock all backgrounds",
            "Exclusive Fish Icon",
            "Free physical copy of Currents & Critters",
            "Thank-you postcard",
            "Exclusive Amberjack player icon",
            "+50,000 bonus XP",
          ],
          note: "Cosmetic progression only",
        },
      ];

      // 3) Physical Game — no products yet. When the tabletop copy ships, add
      //    entries here as { name, usd, link: "<LIVE Stripe Payment Link>" }
      //    and the Physical Game section will render Buy buttons automatically.
      const PHST_PHYSICAL = [];

      function renderPhStore() {
        const el = document.getElementById("ph-store-content");
        if (!el) return;
        const esc = (typeof escapeHtml === "function") ? escapeHtml : (s)=>String(s);

        // Reassurance line: Stripe-hosted checkout + account linking.
        let html = `<div class="phst-account-note">
          <span class="phst-account-ico">🔒</span>
          <div>Checkout is hosted securely by <strong>Stripe</strong> — we never see your card. Purchases are linked to your signed-in Google account, and rewards arrive automatically once payment clears.</div>
        </div>`;

        // ── 1) Critter Coins ──────────────────────────────────────────
        html += `<div class="phst-section-title"><img class="cc-coin" src="/critter-coin.png?v=1" alt="Critter Coin" draggable="false"> Critter Coins<span class="phst-sec-rule"></span></div>`;
        html += `<div class="phst-section-sub">In-game currency. Bigger packs include a bonus — $1 = 1,000 coins.</div>`;
        html += `<div class="phst-coin-grid">`;
        for (const p of PHST_COIN_PACKS) {
          html += `<div class="phst-coin-pack${p.best ? " phst-coin-best" : ""}">
            ${p.best ? `<div class="phst-coin-badge">BEST VALUE</div>` : ""}
            <div class="phst-coin-ico"><img class="cc-coin cc-coin-lg" src="/critter-coin.png?v=1" alt="Critter Coin" draggable="false"></div>
            <div class="phst-coin-amt">${phstFmtCoins(p.coins)}</div>
            <div class="phst-coin-amt-label">Critter Coins</div>
            <div class="phst-coin-bonus">${p.bonus > 0 ? `+${p.bonus}% bonus` : "Base rate"}</div>
            <button class="phst-coin-buy" data-stripe="${esc(p.link)}">$${p.usd.toFixed(2)}</button>
          </div>`;
        }
        html += `</div>`;

        // ── 2) Backgrounds — spend Critter Coins (1,000 each) ─────────
        const _bgs = (typeof EXCLUSIVE_BACKGROUNDS !== "undefined") ? EXCLUSIVE_BACKGROUNDS : [];
        if (_bgs.length) {
          const _unlocked = (typeof window.__fishGetUnlockedBackgrounds === "function")
            ? (window.__fishGetUnlockedBackgrounds() || []) : [];
          const _ownedSet = new Set(_unlocked);
          const _bgsrc = (typeof _bgSrc === "function") ? _bgSrc : (u)=>u;
          html += `<div class="phst-section-title">🌊 Backgrounds<span class="phst-sec-rule"></span></div>`;
          html += `<div class="phst-section-sub">Cosmetic ocean scenes behind your avatar. Spend Critter Coins — 1,000 each.</div>`;
          html += `<div class="phst-grid">`;
          for (const bg of _bgs) {
            const owned = _ownedSet.has(bg.img);
            html += `<div class="phst-card">
              <img class="phst-card-img" src="${_bgsrc(bg.img)}" alt="${esc(bg.name)}" loading="lazy">
              <div class="phst-card-body">
                <div class="phst-card-name">${esc(bg.name)}</div>
                <div class="phst-card-fact">${esc(bg.facts || "")}</div>
                <div class="phst-card-footer">
                  <div class="phst-card-price">${phstFmtCoins(1000)} <img class="cc-coin" src="/critter-coin.png?v=1" alt="Critter Coin" draggable="false"></div>
                  ${owned
                    ? `<div class="phst-card-owned">✓ Owned</div>`
                    : `<button class="phst-card-buy" data-bg="${esc(bg.id)}">Buy</button>`}
                </div>
              </div>
            </div>`;
          }
          html += `</div>`;
        }

        // ── 3) Supporter Tiers ────────────────────────────────────────
        html += `<div class="phst-section-title">★ Supporter Tiers<span class="phst-sec-rule"></span></div>`;
        html += `<div class="phst-section-sub">Back the launch and earn permanent founder recognition. Cosmetic &amp; progression rewards only.</div>`;
        html += `<div class="phst-tier-grid">`;
        for (const t of PHST_SUPPORTER_TIERS) {
          html += `<div class="phst-tier${t.best ? " phst-tier-best" : ""}">
            ${t.best ? `<div class="phst-tier-badge">BEST VALUE</div>` : ""}
            <div class="phst-tier-name">${esc(t.name)}</div>
            <div class="phst-tier-price">$${t.usd.toFixed(2)}<span class="phst-tier-once">one-time</span></div>
            <ul class="phst-tier-perks">`;
          for (const perk of t.perks) html += `<li>${esc(perk)}</li>`;
          html += `</ul>
            <div class="phst-tier-fine">${esc(t.note)}</div>
            <button class="phst-tier-buy" data-stripe="${esc(t.link)}">Become a ${esc(t.name)}</button>
          </div>`;
        }
        html += `</div>`;

        // ── 4) Physical Game ──────────────────────────────────────────
        html += `<div class="phst-section-title">📦 Physical Game<span class="phst-sec-rule"></span></div>`;
        html += `<div class="phst-section-sub">The tabletop edition of Currents &amp; Critters.</div>`;
        if (PHST_PHYSICAL.length === 0) {
          html += `<div class="phst-physical-soon">
            <div class="phst-physical-ico">🐢</div>
            <div>
              <div class="phst-physical-title">Coming soon</div>
              <div class="phst-physical-desc">A physical copy of Currents &amp; Critters is on the way. Tide Turner supporters get one free!</div>
            </div>
          </div>`;
        } else {
          html += `<div class="phst-grid">`;
          for (const item of PHST_PHYSICAL) {
            html += `<div class="phst-card">
              <div class="phst-card-body">
                <div class="phst-card-name">${esc(item.name)}</div>
                <div class="phst-card-footer">
                  <div class="phst-card-price">$${Number(item.usd).toFixed(2)}</div>
                  <button class="phst-card-buy" data-stripe="${esc(item.link)}">Buy</button>
                </div>
              </div>
            </div>`;
          }
          html += `</div>`;
        }

        el.innerHTML = html;

        // Wire every coin-pack / tier / physical Buy button to its Stripe-hosted
        // Payment Link. Opens in the SAME tab (window.location.href in _phstGoToStripe).
        el.querySelectorAll("[data-stripe]").forEach((btn) => {
          btn.addEventListener("click", () => window._phstGoToStripe(btn.getAttribute("data-stripe")));
        });
        // Wire every background Buy button to the Critter-Coins spend flow.
        el.querySelectorAll("[data-bg]").forEach((btn) => {
          btn.addEventListener("click", () => window._phstBuyBg(btn.getAttribute("data-bg"), btn));
        });
      }
      window.renderPhStore = renderPhStore;

      // Buy a background with Critter Coins (spends from the wallet, grants the
      // unlock, refreshes the store + header). Safe: the deduction is a server-
      // side Firestore transaction (see __fishBuyBackgroundWithCoins).
      window._phstBuyBg = async function (bgId, btn) {
        const bg = (typeof _BG_BY_ID !== "undefined") ? _BG_BY_ID[bgId] : null;
        if (!bg) return;
        if (!_authUser) { showToast("Sign in with Google first to spend Critter Coins.", "info"); return; }
        if (typeof window.__fishBuyBackgroundWithCoins !== "function") return;
        if (btn) btn.disabled = true;
        try {
          const res = await window.__fishBuyBackgroundWithCoins(bg.img);
          if (res && res.ok) {
            showToast(`Unlocked the ${bg.name} background! 🎉`, "ok");
            renderPhStore();
          } else if (res && res.reason === "coins") {
            showToast(`Not enough Critter Coins — ${bg.name} costs 1,000.`, "err");
          } else if (res && res.reason === "owned") {
            showToast(`You already own the ${bg.name} background.`, "info");
            renderPhStore();
          } else {
            showToast("Purchase failed — try again.", "err");
          }
        } catch {
          showToast("Purchase failed — try again.", "err");
        }
        if (btn) btn.disabled = false;
      };

      // Daily streak XP formula: 75 + (day-1)*0.25, cap at day 730
      (function initStreakCard() {
        const streakDayEl = document.getElementById("ph-ss-days");
        const todayXpEl = document.getElementById("ph-ss-today-xp");
        const tomorrowXpEl = document.getElementById("ph-ss-tomorrow-xp");
        if (!todayXpEl) return;
        // Driven by real streak data via syncStatsHeader → window._updateStreakXp(count).
        function updateStreakXp(day) {
          const d = Math.max(0, Math.min(Number(day) || 0, 730));
          const effDay = Math.max(1, d);
          // Today's bonus = XP for the current streak day (day 1 = 75.00, +0.25/day).
          // At streak 0, "today" previews day 1 (75.00). Always 2 decimals.
          const todayXp = (75 + ((d > 0 ? d : 1) - 1) * 0.25).toFixed(2);
          const tomorrowXp = (75 + (d > 0 ? d : 1) * 0.25).toFixed(2);
          if (streakDayEl) streakDayEl.textContent = d + " Day" + (d !== 1 ? "s" : "");
          if (todayXpEl) todayXpEl.textContent = "+" + todayXp + " XP";
          if (tomorrowXpEl) tomorrowXpEl.textContent = "+" + tomorrowXp + " XP";
        }
        window._updateStreakXp = updateStreakXp;
        updateStreakXp(0); // 0 until real data loads
      })();

      // ── Yearly streak calendar (View Streak Details) ──────────────
      let _scYear = new Date().getFullYear();
      const _SC_MONTHS = ["January","February","March","April","May","June","July","August","September","October","November","December"];
      const _SC_DOW = ["S","M","T","W","T","F","S"];

      function _streakStatsSource() {
        // Signed-in: the active profile's stats. Guest: stats live in
        // localStorage (active profile has no .stats), so fall back to the
        // guest getter — otherwise the calendar + week dots show empty.
        // __fishGetMyStats returns the signed-in profile's stats object (or null
        // when there's no signed-in profile — i.e. a guest). Only fall back to
        // guest stats when there's genuinely no signed-in stats, so a fresh
        // signed-in user with no streak_days yet doesn't read guest data.
        const s = (typeof window.__fishGetMyStats === "function") ? window.__fishGetMyStats() : null;
        if (s && typeof s === "object") return s;
        const g = (typeof window.__fishGuestStatsGet === "function") ? (window.__fishGuestStatsGet() || null) : null;
        if (g && typeof g === "object") return g;
        return {};
      }

      // Paint the 7 sidebar week dots (Mon→Sun) from REAL streak data so the
      // little weekly tracker matches the calendar and the big day counter.
      function _renderStreakWeek() {
        const dots = document.querySelectorAll(".ph-ss-week .ph-ss-day-col .ph-ss-dot");
        if (dots.length !== 7 || typeof _computeStreakInfo !== "function") return;
        const info = _computeStreakInfo(_streakStatsSource().streak_days);
        const now = new Date();
        const todayStr = _streakLocalDateStr(now);
        const offset = (now.getDay() + 6) % 7;            // 0 = Monday
        const monday = new Date(now.getFullYear(), now.getMonth(), now.getDate() - offset);
        for (let i = 0; i < 7; i++) {
          const d = new Date(monday.getFullYear(), monday.getMonth(), monday.getDate() + i);
          const ds = _streakLocalDateStr(d);
          const dot = dots[i];
          dot.className = "ph-ss-dot";
          if (info.set.has(ds)) dot.classList.add("done");
          if (ds === todayStr) dot.classList.add("today");
        }
      }
      window._renderStreakWeek = _renderStreakWeek;

      function _renderStreakCalendar() {
        const stats = _streakStatsSource();
        const info = (typeof _computeStreakInfo === "function")
          ? _computeStreakInfo(stats.streak_days)
          : { set: new Set(), current: 0, longest: 0, total: 0, dayNum: {}, mostRecent: null, alive: false, firstDay: null };

        const setTxt = (id, v) => { const el = $a(id); if (el) el.textContent = v; };
        setTxt("sc-current", info.current);
        setTxt("sc-longest", Math.max(info.longest, Number(stats.streak_longest || 0)));
        setTxt("sc-total", info.total);
        setTxt("sc-year-label", _scYear);

        const avatarUrl = (typeof window.__fishMyAvatarUrl === "function") ? (window.__fishMyAvatarUrl() || "") : "";
        const now       = new Date();
        const todayStr  = (typeof _streakLocalDateStr === "function") ? _streakLocalDateStr(now) : "";
        const curMonth  = now.getMonth();
        const curYear   = now.getFullYear();

        // Update the legend "You are here" dot with the player's real avatar.
        const legAvatarDot = document.querySelector("#streak-cal-legend .sc-leg-dot.avatar");
        if (legAvatarDot) {
          if (avatarUrl) {
            legAvatarDot.innerHTML = `<img src="${_avSrc(avatarUrl)}" alt="" style="width:100%;height:100%;object-fit:cover;border-radius:50%;display:block;" onerror="this.style.display='none'">`;
            legAvatarDot.style.background = "transparent";
            legAvatarDot.style.boxShadow   = "0 0 0 2px rgba(245,166,35,.55)";
          } else {
            legAvatarDot.innerHTML = "🐠";
            legAvatarDot.style.background  = "";
            legAvatarDot.style.boxShadow   = "";
          }
        }

        const grid = $a("streak-cal-grid");
        if (!grid) return;
        grid.innerHTML = "";

        for (let m = 0; m < 12; m++) {
          const monthEl = document.createElement("div");
          monthEl.className = "sc-month" + ((m === curMonth && _scYear === curYear) ? " sc-cur-month" : "");

          const startDow   = new Date(_scYear, m, 1).getDay(); // 0=Sun
          const daysInMonth = new Date(_scYear, m + 1, 0).getDate();

          // Pre-compute date strings for the month so we can look ahead/behind
          const dsArr = [];
          for (let d = 1; d <= daysInMonth; d++) {
            dsArr.push(_scYear + "-" + String(m + 1).padStart(2, "0") + "-" + String(d).padStart(2, "0"));
          }

          let html = "<div class=\"sc-month-name\">" + _SC_MONTHS[m] + "</div>"
            + "<div class=\"sc-dow\">" + _SC_DOW.map(dow => "<span>" + dow + "</span>").join("") + "</div>"
            + "<div class=\"sc-days\">";

          // Leading blank cells to align day 1 to the right weekday column
          for (let i = 0; i < startDow; i++) {
            html += "<div class=\"sc-cell\"><div class=\"sc-day blank\"></div></div>";
          }

          for (let d = 1; d <= daysInMonth; d++) {
            const ds       = dsArr[d - 1];
            const isDone   = info.set.has(ds);
            const isFuture = ds > todayStr;
            const beforeFirst = !info.firstDay || ds < info.firstDay;

            // Column index in the 7-col grid (0=Sun … 6=Sat)
            const col = (startDow + d - 1) % 7;

            let dayCls  = "sc-day";
            let cellCls = "sc-cell";
            let content = "";

            if (isDone) {
              // Avatar on the most-recent streak day (player's current position)
              if (info.alive && ds === info.mostRecent && avatarUrl) {
                dayCls  += " avatar";
                cellCls += " sc-avatar-cell";
                content  = "<img src=\"" + _avSrc(avatarUrl) + "\" alt=\"\" loading=\"lazy\">";
              } else {
                dayCls += " done";
                // Show the day-number within the current streak run
                content = String(info.dayNum[ds] || "");
              }

              // Trail bridges: only connect to adjacent done days in the SAME row
              const prevDone = d > 1 && info.set.has(dsArr[d - 2]) && col > 0;
              const nextDone = d < daysInMonth && info.set.has(dsArr[d])     && col < 6;
              if (prevDone) cellCls += " tl";  // handled via data attr below
              if (nextDone) cellCls += " tr";

              const tl = prevDone ? " data-tl=\"1\"" : "";
              const tr = nextDone ? " data-tr=\"1\"" : "";
              html += "<div class=\"" + cellCls + "\"" + tl + tr + "><div class=\"" + dayCls + "\">" + content + "</div></div>";
            } else {
              if (!isFuture && !beforeFirst && ds !== todayStr) dayCls += " missed";
              else if (ds === todayStr && !isFuture) dayCls += " today-empty";
              html += "<div class=\"" + cellCls + "\"><div class=\"" + dayCls + "\" title=\"" + ds + "\"></div></div>";
            }
          }

          html += "</div>";
          monthEl.innerHTML = html;
          grid.appendChild(monthEl);
        }
      }

      function _openStreakCalendar() {
        _scYear = new Date().getFullYear();
        _renderStreakCalendar();
        const modal = $a("streak-cal-modal");
        if (modal) modal.classList.add("open");
      }
      function _closeStreakCalendar() {
        const modal = $a("streak-cal-modal");
        if (modal) modal.classList.remove("open");
      }
      window.__fishOpenStreakCalendar = _openStreakCalendar;
      window.__fishRenderStreakCalendar = _renderStreakCalendar;

      const _ssDetailsBtn = $a("ph-ss-details-btn");
      if (_ssDetailsBtn) _ssDetailsBtn.addEventListener("click", _openStreakCalendar);
      const _scClose = $a("streak-cal-close");
      if (_scClose) _scClose.addEventListener("click", _closeStreakCalendar);
      const _scModal = $a("streak-cal-modal");
      if (_scModal) _scModal.addEventListener("click", (e) => { if (e.target === _scModal) _closeStreakCalendar(); });
      const _scPrev = $a("sc-year-prev");
      if (_scPrev) _scPrev.addEventListener("click", () => { _scYear--; _renderStreakCalendar(); });
      const _scNext = $a("sc-year-next");
      if (_scNext) _scNext.addEventListener("click", () => { _scYear++; _renderStreakCalendar(); });

      // See-all shortcuts
      const histBtn = $a("ph-hist-btn");
      if (histBtn) histBtn.addEventListener("click", () => switchTab("history"));
      const frBtn = $a("ph-friends-open-btn");
      if (frBtn) frBtn.addEventListener("click", () => switchTab("friends"));
      const ovAchAllBtn = $a("ph-ov-ach-all-btn");
      if (ovAchAllBtn) ovAchAllBtn.addEventListener("click", () => switchTab("achievements"));

      // Competitive tab button wiring (deferred so elements exist)
      setTimeout(() => {
        // "Play Ranked 1v1" → open the competitive overlay (Create tab)
        const playRankedBtn = $a("ph-comp-play-ranked-btn");
        if (playRankedBtn) playRankedBtn.addEventListener("click", () => {
          if (typeof compOpenOverlay === "function") compOpenOverlay();
          if (typeof compSwitchTab === "function") compSwitchTab("create");
        });
        // "Leaderboard" → open competitive overlay on LB tab
        const lbViewBtn = $a("ph-comp-lb-view-btn");
        if (lbViewBtn) lbViewBtn.addEventListener("click", () => {
          if (typeof compOpenOverlay === "function") compOpenOverlay();
          if (typeof compSwitchTab === "function") compSwitchTab("lb");
          if (typeof loadCompLeaderboard === "function") loadCompLeaderboard();
        });
        // "View History" link in competitive tab sidebar
        const compHistLink = $a("ph-comp-hist-link");
        if (compHistLink) compHistLink.addEventListener("click", () => switchTab("history"));
        // "Go to Ranked" link in history tab comp section
        const compTabFromHist = $a("ph-hist-comp-tab-btn");
        if (compTabFromHist) compTabFromHist.addEventListener("click", () => switchTab("competitive"));
        // Competitive is now entered via Quick Match / Create Game → Mode: Competitive
        // (and the "Play Competitive" button in this panel), so there is no standalone
        // Competitive action card / listener to wire here.
      }, 0);
    })();

    // ── Player Home: player-count high score tabs ─────────────────
    let _phStats = null;
    let _phStatsRaw = null;
    let _phSelectedPlayerCount = 4;
    function normalizePhPlayerCount(ps) {
      const n = Number(ps);
      if (!Number.isFinite(n)) return 4;
      const rounded = Math.round(n);
      if (rounded < 2) return 2;
      if (rounded > 8) return 8;
      return rounded;
    }

    function getPhPlayerCountLabel(ps) {
      return `${normalizePhPlayerCount(ps)}P`;
    }

    function setPhCountPrefixedLabels(ps) {
      const prefix = getPhPlayerCountLabel(ps);
      const setLabel = (id, suffix) => {
        const el = $a(id);
        if (el) el.textContent = `${prefix} ${suffix}`;
      };
      setLabel("ph-label-win-pct", "Win %");
      setLabel("ph-label-most-strategy", "Most Played Strategy");
      setLabel("ph-label-avg-pts", "Avg Points Per Game");
      setLabel("ph-label-total-games", "Total Games");
      setLabel("ph-label-wins", "Wins");
      setLabel("ph-label-hours", "Hours Played");
      setLabel("ph-label-recent-games", "Recent Games");
    }

    function getExactNormalGamesByPlayerCount(stats, ps) {
      const size = normalizePhPlayerCount(ps);
      const allGames = Array.isArray(stats?.recent_games) ? stats.recent_games : [];
      return allGames.filter((g) => {
        if (!g || typeof g !== "object") return false;
        const pc = Number(g.pc ?? g.player_count ?? g.total_players ?? 0);
        if (!Number.isFinite(pc) || Math.round(pc) !== size) return false;
        const mode = String(g.mode || "normal").toLowerCase();
        return mode !== "competitive";
      });
    }

    function getPerSizeCards(stats, ps) {
      const size = normalizePhPlayerCount(ps);
      const bySize = stats?.most_played_cards_by_size;
      if (bySize && typeof bySize === "object") {
        const list = bySize[String(size)] ?? bySize[size];
        if (Array.isArray(list)) return list.filter(Boolean);
      }
      const direct = stats?.[`most_played_cards_${size}p`];
      if (Array.isArray(direct)) return direct.filter(Boolean);
      return [];
    }

    function getPerSizeStrategy(stats, ps) {
      const size = normalizePhPlayerCount(ps);
      const bySize = stats?.most_played_strategy_by_size;
      if (bySize && typeof bySize === "object") {
        const strategy = bySize[String(size)] ?? bySize[size];
        if (typeof strategy === "string" && strategy.trim()) return strategy.trim();
      }
      const direct = stats?.[`most_played_strategy_${size}p`];
      if (typeof direct === "string" && direct.trim()) return direct.trim();
      return "";
    }

    function getOverallMostPlayedCard(stats) {
      const source = (stats && typeof stats === "object") ? stats : {};
      const directSingle = String(source.most_played_card || "").trim();
      if (directSingle) return directSingle;

      if (Array.isArray(source.most_played_cards)) {
        const first = source.most_played_cards.find((name) => String(name || "").trim());
        if (first) return String(first).trim();
      }

      const counts = Object.create(null);
      const addCount = (name, count) => {
        const card = String(name || "").trim();
        const inc = Number(count);
        if (!card || !Number.isFinite(inc) || inc <= 0) return;
        counts[card] = (counts[card] || 0) + inc;
      };

      const mergeCountMap = (obj) => {
        if (!obj || typeof obj !== "object") return;
        Object.entries(obj).forEach(([name, count]) => addCount(name, count));
      };

      mergeCountMap(source.card_usage_all);
      mergeCountMap(source.card_usage);
      mergeCountMap(source.card_usage_normal);
      mergeCountMap(source.card_usage_competitive);

      if (source.card_usage_by_mode && typeof source.card_usage_by_mode === "object") {
        Object.values(source.card_usage_by_mode).forEach((modeMap) => mergeCountMap(modeMap));
      }

      const topsByMode = [
        source.most_played_card_normal,
        source.most_played_card_competitive,
      ];
      topsByMode.forEach((name) => {
        const card = String(name || "").trim();
        if (card) addCount(card, 1);
      });

      const topFromCounts = Object.entries(counts).sort((a, b) => b[1] - a[1])[0];
      if (topFromCounts && topFromCounts[0]) return topFromCounts[0];

      if (source.most_played_cards_by_size && typeof source.most_played_cards_by_size === "object") {
        const fallbackCounts = Object.create(null);
        Object.values(source.most_played_cards_by_size).forEach((list) => {
          if (!Array.isArray(list)) return;
          list.forEach((name) => {
            const card = String(name || "").trim();
            if (!card) return;
            fallbackCounts[card] = (fallbackCounts[card] || 0) + 1;
          });
        });
        const topFallback = Object.entries(fallbackCounts).sort((a, b) => b[1] - a[1])[0];
        if (topFallback && topFallback[0]) return topFallback[0];
      }

      return "";
    }

    function getOverallMostPlayedStrategy(stats) {
      const source = (stats && typeof stats === "object") ? stats : {};
      const direct = String(source.most_played_strategy || source.favorite_strategy || "").trim();
      if (direct) return direct;

      const bySize = source.most_played_strategy_by_size;
      if (bySize && typeof bySize === "object") {
        const freq = Object.create(null);
        Object.values(bySize).forEach((value) => {
          const strategy = String(value || "").trim();
          if (!strategy) return;
          freq[strategy] = (freq[strategy] || 0) + 1;
        });
        const top = Object.entries(freq).sort((a, b) => b[1] - a[1])[0];
        if (top && top[0]) return top[0];
      }
      // Fall back to locally-tracked guide activations if server has no data
      try {
        const localFav = (typeof _getMostPlayedStrategyLocal === "function") ? _getMostPlayedStrategyLocal() : "";
        if (localFav) return localFav;
      } catch (_) {}
      return "";
    }

    function getMostPlayedPlayerCountLabel(stats) {
      const source = (stats && typeof stats === "object") ? stats : {};
      const direct = Number(source.most_played_player_count || source.favorite_player_count || 0);
      if (Number.isFinite(direct) && direct >= 2) return `${Math.round(direct)}P`;

      const counts = Object.create(null);
      const absorbCountMap = (obj) => {
        if (!obj || typeof obj !== "object") return;
        Object.entries(obj).forEach(([key, value]) => {
          const pc = Number(key);
          const games = Number(value);
          if (!Number.isFinite(pc) || pc < 2 || !Number.isFinite(games) || games <= 0) return;
          const pKey = String(Math.round(pc));
          counts[pKey] = (counts[pKey] || 0) + games;
        });
      };
      absorbCountMap(source.normal_games_by_size);
      absorbCountMap(source.comp_games_by_size);

      if (!Object.keys(counts).length && Array.isArray(source.recent_games)) {
        source.recent_games.forEach((g) => {
          const pc = Number(g?.pc ?? g?.player_count ?? g?.total_players ?? 0);
          if (!Number.isFinite(pc) || pc < 2) return;
          const pKey = String(Math.round(pc));
          counts[pKey] = (counts[pKey] || 0) + 1;
        });
      }

      const top = Object.entries(counts).sort((a, b) => b[1] - a[1])[0];
      return top && top[0] ? `${top[0]}P` : "";
    }

    let _overviewAchievements = {
      dailyAchievements: [],
      completedAchievements: [],
      uncompletedAchievements: [],
    };

    function normalizeOverviewAchievements(stats) {
      const source = (stats && typeof stats === "object") ? stats : {};
      const root = (source.achievements && typeof source.achievements === "object") ? source.achievements : source;

      const normalizeDaily = (entry, idx) => {
        if (typeof entry === "string") {
          return { id: `daily_${idx}`, name: entry, progress: 0, goal: 3 };
        }
        const item = (entry && typeof entry === "object") ? entry : {};
        const goalVal = Number(item.goal ?? item.target ?? item.total ?? 3);
        const progressVal = Number(item.progress ?? item.current ?? item.done ?? 0);
        const goal = Number.isFinite(goalVal) && goalVal > 0 ? Math.floor(goalVal) : 3;
        const progress = Number.isFinite(progressVal) && progressVal >= 0 ? Math.floor(progressVal) : 0;
        return {
          id: String(item.id || item.key || `daily_${idx}`),
          name: String(item.name || item.title || `Daily challenge ${idx + 1}`),
          progress,
          goal,
        };
      };

      const normalizeBadge = (entry, idx, fallbackIcon) => {
        if (typeof entry === "string") {
          return { id: `badge_${idx}`, name: entry, icon: fallbackIcon };
        }
        const item = (entry && typeof entry === "object") ? entry : {};
        return {
          id: String(item.id || item.key || `badge_${idx}`),
          name: String(item.name || item.title || `Achievement ${idx + 1}`),
          icon: String(item.icon || fallbackIcon),
        };
      };

      const dailyRaw = Array.isArray(root.dailyAchievements) ? root.dailyAchievements : [];
      const completedRaw = Array.isArray(root.completedAchievements) ? root.completedAchievements : [];
      const uncompletedRaw = Array.isArray(root.uncompletedAchievements) ? root.uncompletedAchievements : [];

      return {
        dailyAchievements: (dailyRaw.length ? dailyRaw : DEFAULT_OVERVIEW_ACHIEVEMENTS.dailyAchievements).map(normalizeDaily),
        completedAchievements: (completedRaw.length ? completedRaw : DEFAULT_OVERVIEW_ACHIEVEMENTS.completedAchievements).map((entry, idx) => normalizeBadge(entry, idx, "🏆")),
        uncompletedAchievements: (uncompletedRaw.length ? uncompletedRaw : DEFAULT_OVERVIEW_ACHIEVEMENTS.uncompletedAchievements).map((entry, idx) => normalizeBadge(entry, idx, "🔒")),
      };
    }

    function openAchievementSection(kind, shouldOpen) {
      const item = document.querySelector(`.ph-ach-item[data-ach-kind="${kind}"]`);
      if (!item) return;
      const open = typeof shouldOpen === "boolean" ? shouldOpen : !item.classList.contains("open");
      item.classList.toggle("open", open);
    }

    function renderAchievementPreview(containerId, list, kind) {
      const el = $a(containerId);
      if (!el) return;
      el.innerHTML = "";
      const preview = Array.isArray(list) ? list.slice(0, 3) : [];
      if (!preview.length) {
        const empty = document.createElement("span");
        empty.className = "ph-ach-progress";
        empty.textContent = "0";
        el.appendChild(empty);
        return;
      }
      preview.forEach((item) => {
        const badge = document.createElement("span");
        const styleKind = kind === "daily" ? "progress" : kind;
        badge.className = `ph-ach-mini ${styleKind}`;
        if (kind === "daily") {
          const progress = Math.max(0, Number(item.progress) || 0);
          const goal = Math.max(1, Number(item.goal) || 1);
          badge.textContent = `${progress}/${goal}`;
        } else {
          badge.textContent = String(item.icon || (kind === "completed" ? "🏆" : "🔒"));
        }
        el.appendChild(badge);
      });
    }

    function renderAchievementDetails(containerId, list, kind) {
      const el = $a(containerId);
      if (!el) return;
      if (!Array.isArray(list) || !list.length) {
        el.innerHTML = '<div class="ph-empty" style="padding:10px 4px;">No achievements yet.</div>';
        return;
      }
      el.innerHTML = "";
      list.forEach((item) => {
        const row = document.createElement("div");
        row.className = "ph-ach-detail-row";
        const name = escapeHtml(item.name || "Achievement");
        if (kind === "daily") {
          const progress = Math.max(0, Number(item.progress) || 0);
          const goal = Math.max(1, Number(item.goal) || 1);
          row.innerHTML = `<div class="ph-ach-name">${name}</div><div class="ph-ach-progress">${progress}/${goal}</div>`;
        } else {
          const icon = escapeHtml(item.icon || (kind === "completed" ? "🏆" : "🔒"));
          const badgeClass = kind === "completed" ? "completed" : "uncompleted";
          const status = kind === "completed" ? "Earned" : "Locked";
          row.innerHTML = `<span class="ph-ach-badge-dot ${badgeClass}">${icon}</span><div class="ph-ach-name">${name}</div><div class="ph-ach-progress">${status}</div>`;
        }
        el.appendChild(row);
      });
    }

    function renderOverviewAchievements(stats) {
      _overviewAchievements = normalizeOverviewAchievements(stats);
      const daily = _overviewAchievements.dailyAchievements;
      const completed = _overviewAchievements.completedAchievements;
      const uncompleted = _overviewAchievements.uncompletedAchievements;

      const setCount = (id, value) => {
        const el = $a(id);
        if (el) el.textContent = String(value);
      };
      setCount("ph-ach-daily-count", daily.length);
      setCount("ph-ach-completed-count", completed.length);
      setCount("ph-ach-uncompleted-count", uncompleted.length);

      renderAchievementPreview("ph-ach-daily-preview", daily, "daily");
      renderAchievementPreview("ph-ach-completed-preview", completed, "completed");
      renderAchievementPreview("ph-ach-uncompleted-preview", uncompleted, "uncompleted");

      renderAchievementDetails("ph-ach-daily-details", daily, "daily");
      renderAchievementDetails("ph-ach-completed-details", completed, "completed");
      renderAchievementDetails("ph-ach-uncompleted-details", uncompleted, "uncompleted");
    }

    (function wireOverviewAchievementToggles() {
      ["daily", "completed", "uncompleted"].forEach((kind) => {
        const btn = $a(`ph-ach-${kind}-toggle`);
        if (!btn) return;
        btn.addEventListener("click", () => {
          openAchievementSection(kind);
        });
      });
    })();

    function renderPhAchievements() {
      if (typeof renderAvatarAchievements === "function") renderAvatarAchievements();
      const list = $a("ach-steam-list");
      if (!list) return;
      const userAchs = (typeof window.__fishGetUserAchievements === "function") ? window.__fishGetUserAchievements() : {};
      const filterVal = ($a("ach-filter-select") || {}).value || "all";
      const total = ACHIEVEMENT_DEFS.length;
      const doneCount = ACHIEVEMENT_DEFS.filter(d => userAchs[d.id] && userAchs[d.id].completed).length;
      const pct = total > 0 ? Math.round((doneCount / total) * 100) : 0;
      const setText = (id, v) => { const e = $a(id); if (e) e.textContent = String(v); };
      setText("ach-stat-done", doneCount);
      setText("ach-stat-total", total);
      setText("ach-stat-pct", pct);
      setText("ach-stat-left", total - doneCount);
      const fill = $a("ach-prog-fill");
      if (fill) fill.style.width = pct + "%";

      const defs = ACHIEVEMENT_DEFS.filter(def => {
        const rec = userAchs[def.id] || {};
        const done = !!rec.completed;
        if (filterVal === "completed" && !done) return false;
        if (filterVal === "uncompleted" && done) return false;
        return true;
      });
      // Sort: completed first, uncompleted second, secret locked last
      defs.sort((a, b) => {
        const aRec = userAchs[a.id] || {}, bRec = userAchs[b.id] || {};
        const aDone = !!aRec.completed, bDone = !!bRec.completed;
        const aSecretLocked = !!a.hidden && !aDone;
        const bSecretLocked = !!b.hidden && !bDone;
        if (aDone && !bDone) return -1;
        if (!aDone && bDone) return 1;
        if (aSecretLocked && !bSecretLocked) return 1;
        if (!aSecretLocked && bSecretLocked) return -1;
        return 0;
      });

      if (!defs.length) {
        list.innerHTML = '<div style="color:var(--muted);text-align:center;padding:32px 0;font-size:13px;">No achievements match this filter.</div>';
        return;
      }

      list.innerHTML = "";
      defs.forEach(def => {
        const rec = userAchs[def.id] || {};
        const done = !!rec.completed;
        const isSecret = !!def.hidden && !done;

        const card = document.createElement("div");
        card.className = "ach-steam-card" + (done ? " ach-done" : "") + (isSecret ? " ach-secret" : "");

        let iconHtml, nameHtml, descHtml, progHtml = "";
        if (isSecret) {
          iconHtml = `<div class="ach-icon-wrap ach-icon-locked"><span>?</span></div>`;
          nameHtml = `<div class="ach-name">Secret Achievement</div>`;
          descHtml = `<div class="ach-desc">Unlock this to reveal it.</div>`;
        } else {
          const badgeCls = done ? "ach-icon-done" : "";
          iconHtml = `<div class="ach-icon-wrap ${badgeCls}"><span>${escapeHtml(def.icon)}</span></div>`;
          nameHtml = `<div class="ach-name">${escapeHtml(def.name)}</div>`;
          descHtml = `<div class="ach-desc">${escapeHtml(def.desc)}</div>`;
          if (rec.progress != null && rec.goal != null && !done) {
            const prog = Math.min(Number(rec.progress || 0), Number(rec.goal));
            const goal = Number(rec.goal);
            const pPct = goal > 0 ? Math.round((prog / goal) * 100) : 0;
            progHtml = `<div class="ach-steam-prog-wrap"><div class="ach-steam-prog-bar"><div class="ach-steam-prog-fill" style="width:${pPct}%"></div></div><div class="ach-steam-prog-text">${prog} / ${goal}</div></div>`;
          }
        }

        const xpHtml = isSecret ? `<div class="ach-xp">? XP</div>` : `<div class="ach-xp">+${def.xp} XP</div>`;
        let badgeHtml = "";
        if (done) {
          const dateStr = rec.unlockedAt ? new Date(rec.unlockedAt).toLocaleDateString(undefined, {month:"short",day:"numeric",year:"numeric"}) : "";
          badgeHtml = `<div class="ach-badge ach-badge-done">✓ Unlocked</div>${dateStr ? `<div class="ach-unlock-date">${escapeHtml(dateStr)}</div>` : ""}`;
        } else if (!isSecret) {
          badgeHtml = `<div class="ach-badge ach-badge-locked">Locked</div>`;
        }

        card.innerHTML = `${iconHtml}<div class="ach-info">${nameHtml}${descHtml}${progHtml}</div><div class="ach-right">${xpHtml}${badgeHtml}</div>`;
        list.appendChild(card);
      });

      // Hidden Bobtail Squid easter egg — always pinned to the very end.
      const bob = document.createElement("div");
      bob.className = "ach-steam-card";
      bob.innerHTML = `<div class="ach-icon-wrap"><img src="/avatars/bobtail-squid.png" alt="" draggable="false" style="width:100%;height:100%;object-fit:contain;"></div><div class="ach-info"><div class="ach-name">What's bob doing here</div><div class="ach-desc">Hmm… that's not supposed to be on the list.</div></div><div class="ach-right"></div>`;
      bob.addEventListener("click", () => window.__fishGrantHiddenCeph?.("bobtail-squid", "/avatars/bobtail-squid.png", bob));
      list.appendChild(bob);
    }

    // Wire achievement filter
    (function() {
      const sel = $a("ach-filter-select");
      if (sel) sel.addEventListener("change", () => renderPhAchievements());
    })();

    // ── Avatar Achievements section ─────────────────────────────
    function renderAvatarAchievements() {
      const list   = $a("av-ach-list");
      const barFill = $a("av-ach-bar-fill");
      if (!list) return;

      const { stats, level } = _avatarStatsAndLevel();
      const speciesFilter = ($a("av-species-filter") || {}).value || "all";
      const statusFilter  = ($a("av-status-filter")  || {}).value || "all";

      // Include all avatars (secrets show with a "Hidden" badge, no progress bar).
      const visible = ANIMAL_AVATARS.filter(a => !!a.unlock);

      const totalCount   = visible.length;
      const unlockedCount = visible.filter(a => isAvatarUnlocked(a.img)).length;
      const pct = totalCount > 0 ? Math.round((unlockedCount / totalCount) * 100) : 0;
      const setText = (id, v) => { const e = $a(id); if (e) e.textContent = String(v); };
      setText("av-stat-done",  unlockedCount);
      setText("av-stat-total", totalCount);
      setText("av-stat-pct",   pct);
      setText("av-stat-left",  totalCount - unlockedCount);
      if (barFill) barFill.style.width = pct + "%";

      // Filter by species + status
      let filtered = visible.filter(a => {
        if (speciesFilter !== "all" && a.species !== speciesFilter) return false;
        const unlocked = isAvatarUnlocked(a.img);
        if (statusFilter === "unlocked" && !unlocked) return false;
        if (statusFilter === "locked"   &&  unlocked) return false;
        return true;
      });

      // Sort: unlocked first, then locked by progress descending
      filtered.sort((a, b) => {
        const aU = isAvatarUnlocked(a.img), bU = isAvatarUnlocked(b.img);
        if (aU !== bU) return aU ? -1 : 1;
        // Both locked — sort by progress fraction descending
        const ap = animalUnlockProgress(a, stats, level) || 0;
        const bp = animalUnlockProgress(b, stats, level) || 0;
        return bp - ap;
      });

      if (!filtered.length) {
        list.innerHTML = '<div style="color:var(--muted);text-align:center;padding:24px 0;font-size:13px;">No avatars match this filter.</div>';
        return;
      }

      list.innerHTML = "";
      filtered.forEach(a => {
        const unlocked = isAvatarUnlocked(a.img);
        const u        = a.unlock;
        const prog     = animalUnlockProgress(a, stats, level);  // 0..1 or null
        const progText = animalProgressText(a, stats, level);     // "X / Y ..." or ""

        const card = document.createElement("div");
        card.className = "av-ach-card" + (unlocked ? " av-done" : "");

        // Icon
        const iconWrap = document.createElement("div");
        iconWrap.className = "av-icon-wrap";
        const img = document.createElement("img");
        img.src = a.img; img.alt = a.name; img.loading = "lazy";
        if (!unlocked) img.style.filter = "grayscale(.55)";
        iconWrap.appendChild(img);

        // Info
        const info = document.createElement("div");
        info.className = "av-info";

        const nameEl = document.createElement("div");
        nameEl.className = "av-name";
        nameEl.textContent = a.name;

        const speciesEl = document.createElement("div");
        speciesEl.className = "av-species-tag";
        speciesEl.textContent = a.species || "";

        const reqEl = document.createElement("div");
        reqEl.className = "av-req";
        reqEl.textContent = u.label || "";

        info.appendChild(nameEl);
        info.appendChild(speciesEl);
        info.appendChild(reqEl);

        // Progress bar (for numeric unlock types). Giant Squid hides progress.
        if (!unlocked && prog !== null && prog >= 0 && a.id !== "giant-squid") {
          const progWrap = document.createElement("div");
          progWrap.className = "av-prog-wrap";
          const pct = Math.round(prog * 100);
          progWrap.innerHTML = `<div class="av-prog-bar"><div class="av-prog-fill" style="width:${pct}%"></div></div><div class="av-prog-text">${escapeHtml(progText)}</div>`;
          info.appendChild(progWrap);
        }

        // Right badge
        const right = document.createElement("div");
        right.className = "av-right";
        if (unlocked) {
          right.innerHTML = `<div class="av-badge av-badge-done">✓ Unlocked</div>`;
        } else if (u.type === "secret" || a.id === "giant-squid") {
          right.innerHTML = `<div class="av-badge av-badge-secret">🔮 Hidden</div>`;
        } else if (u.type === "event" || u.type === "achievement") {
          right.innerHTML = `<div class="av-badge av-badge-locked">Challenge</div>`;
        } else {
          // Show numeric progress % in badge for level/stat/rank/comp_wins
          const pctBadge = prog !== null ? Math.round(prog * 100) : 0;
          right.innerHTML = `<div class="av-badge av-badge-locked">${pctBadge}%</div>`;
        }

        card.appendChild(iconWrap);
        card.appendChild(info);
        card.appendChild(right);
        list.appendChild(card);
      });
    }

    // Wire avatar achievement filters
    (function() {
      const sp = $a("av-species-filter");
      const st = $a("av-status-filter");
      if (sp) sp.addEventListener("change", renderAvatarAchievements);
      if (st) st.addEventListener("change", renderAvatarAchievements);
    })();

    function applyPhNormalStatsForPlayerCount(ps) {
      const size = normalizePhPlayerCount(ps);
      _phSelectedPlayerCount = size;
      setPhCountPrefixedLabels(size);

      const statsSource = _phStatsRaw || {};
      const sKey = String(size);

      // Aggregated stats from atomic Firebase increments — most accurate source
      const normalGamesBySize = statsSource.normal_games_by_size || {};
      const normalWinsBySize  = statsSource.normal_wins_by_size  || {};
      const totalScoreBySize  = statsSource.total_score_by_size  || {};

      const totalGamesAgg = Number(normalGamesBySize[sKey] ?? normalGamesBySize[size] ?? 0);
      const rawWinsAgg    = normalWinsBySize[sKey] ?? normalWinsBySize[size];
      const winsAgg       = rawWinsAgg !== undefined && rawWinsAgg !== null ? Number(rawWinsAgg) : null;
      const totalScoreAgg = Number(totalScoreBySize[sKey] ?? totalScoreBySize[size] ?? 0);

      // Recent games filtered by size — used for the games list and as fallback
      const filteredGames = getExactNormalGamesByPlayerCount(statsSource, size);

      // Prefer aggregated totals; fall back to counting recent_games entries
      let totalGames = totalGamesAgg > 0 ? totalGamesAgg : filteredGames.length;
      let wins = winsAgg !== null
        ? winsAgg
        : filteredGames.reduce((acc, g) => acc + (Number(g?.r) === 1 ? 1 : 0), 0);

      // Average score: prefer aggregated total score; fall back to recent_games average
      let avgPts = "—";
      if (totalGames > 0) {
        if (totalScoreAgg > 0) {
          avgPts = Math.round(totalScoreAgg / totalGames);
        } else if (filteredGames.length > 0) {
          const sumScore = filteredGames.reduce((acc, g) => acc + (Number(g?.s) || 0), 0);
          avgPts = Math.round(sumScore / filteredGames.length);
        }
      }

      // If every per-size bucket is empty (old games predate the pc field), fall back to
      // overall totals so players always see their real data rather than a wall of zeros.
      const hasAnySizeData = Object.values(normalGamesBySize).some(n => Number(n) > 0)
        || (Array.isArray(statsSource.recent_games) && statsSource.recent_games.some(g => g?.pc != null));
      if (!hasAnySizeData && totalGames === 0 && Number(statsSource.completed_games || 0) > 0) {
        totalGames = Number(statsSource.completed_games || 0);
        wins       = Number(statsSource.normal_wins || 0);
        const overallScore = Number(statsSource.total_score || 0);
        avgPts = (totalGames > 0 && overallScore > 0) ? Math.round(overallScore / totalGames) : "—";
      }

      const winPct = totalGames > 0 ? `${Math.round((wins / totalGames) * 100)}%` : "—";
      const winSub = totalGames > 0 && wins / totalGames >= 0.6 ? "Great job!" : "";

      // If we have data, make sure the stats block is visible regardless of how it was hidden
      const hasData = totalGames > 0
        || Number(statsSource.completed_games || 0) > 0
        || Number(statsSource.normal_wins || 0) > 0;
      if (hasData) {
        const normalBlock = $a("stats-normal-block");
        const noGamesEl   = $a("stats-no-games");
        if (normalBlock) normalBlock.style.display = "";
        if (noGamesEl)   noGamesEl.style.display   = "none";
      }

      const wpEl = $a("ph-win-pct"); if (wpEl) wpEl.textContent = winPct;
      const wpSub = $a("ph-win-pct-sub"); if (wpSub) wpSub.textContent = winSub;
      const avgEl = $a("ph-avg-pts"); if (avgEl) avgEl.textContent = String(avgPts);
      const completedEl = $a("stat-completed"); if (completedEl) completedEl.textContent = String(totalGames);
      const winsEl = $a("stat-normal-wins"); if (winsEl) winsEl.textContent = String(wins);

      const strategyEl = $a("stat-strategy");
      const strategy = getPerSizeStrategy(statsSource, size);
      if (strategyEl) strategyEl.textContent = strategy || (totalGames > 0 ? "—" : "No games completed yet.");

      // On the 7P tab, replace the strategy icon with the hidden sea sponge.
      // Any other tab restores the original SVG. The sponge is wired as a
      // 3-click secret (reveals the digit 3) once the image is in the DOM.
      const stratIconEl = $a("ph-strategy-icon");
      if (stratIconEl) {
        const _origSvg = `<svg width="24" height="24" viewBox="0 0 24 24" fill="none"><circle cx="12" cy="12" r="7" stroke="#2d86e4" stroke-width="1.8"/><circle cx="12" cy="12" r="3.5" stroke="#2d86e4" stroke-width="1.8"/><path d="M20 4l-5.5 5.5" stroke="#2d86e4" stroke-width="1.8" stroke-linecap="round"/></svg>`;
        if (size === 7) {
          // Only inject once per reset (check for already-wired img)
          if (!stratIconEl.querySelector('img.secret-critter')) {
            stratIconEl.innerHTML = "";
            if (typeof window.__fishPlaceSecretCritter === "function") {
              const wrap = window.__fishPlaceSecretCritter("sponge", stratIconEl);
              // style the img to fit the icon cell nicely
              if (wrap) {
                const img = wrap.querySelector("img");
                if (img) { img.style.width = "38px"; img.style.height = "38px"; }
              }
            }
          }
        } else {
          // Restore original SVG and reset sponge state so it can be triggered again
          if (!stratIconEl.querySelector("svg")) {
            stratIconEl.innerHTML = _origSvg;
            try { if (typeof window.__fishResetSecrets === "function") window.__fishResetSecrets(); } catch (_) {}
          }
        }
      }

      // Hours in THIS player count (casual playtime for the selected size).
      // Falls back to the global hours_played only when no per-size data exists
      // yet (older accounts that predate per-size playtime tracking).
      const hoursEl = $a("stat-hours-played-pc");
      if (hoursEl) {
        const ptBySize = (statsSource.normal_playtime_by_size && typeof statsSource.normal_playtime_by_size === "object") ? statsSource.normal_playtime_by_size : {};
        const hasPerSize = Object.keys(ptBySize).length > 0;
        const sizeHours = Number(ptBySize[sKey] ?? ptBySize[size] ?? 0);
        const h = hasPerSize ? sizeHours : Number(statsSource.hours_played || 0);
        const hr = Math.round(h * 10) / 10; // one decimal so short games still register
        hoursEl.textContent = hr === 1 ? "1 hr" : `${hr} hrs`;
      }

      renderPhRecentGames(filteredGames);
    }

    (function() {
      const pcBtns = document.querySelectorAll(".ph-pc[data-ps]");
      function setActivePs(ps) {
        const size = normalizePhPlayerCount(ps);
        pcBtns.forEach(b => b.classList.toggle("active", b.dataset.ps === String(size)));
        const el = $a("ph-high-score"), lbl = $a("ph-hs-label");
        if (_phStats) {
          const key = `highest_score_${size}p`;
          const val = _phStats[key] ?? (_phStats.highest_score || null);
          if (el) el.textContent = val != null && val > 0 ? String(val) : "—";
          if (lbl) lbl.textContent = val != null && val > 0 ? `${size}P game` : "";
        }
        applyPhNormalStatsForPlayerCount(size);
      }
      pcBtns.forEach(b => b.addEventListener("click", () => {
        setActivePs(Number(b.dataset.ps));
      }));
      window._phSetPs = setActivePs;
    })();

    // ── Player Home: populate extra stats cells ────────────────────
    function updatePhStats(stats) {
      const safeStats = getHomeReferenceStats(stats);
      _phStats = safeStats;
      // Only replace _phStatsRaw if incoming stats have actual content.
      // This prevents a null/empty renderStats call (e.g. mid-reload) from erasing cached data.
      const incomingHasContent = (safeStats.completed_games || 0) > 0
        || Object.values(safeStats.normal_games_by_size || {}).some(n => Number(n) > 0);
      if (incomingHasContent || !_phStatsRaw) {
        _phStatsRaw = safeStats;
      }

      // Total games: prefer completed_games; fall back to summing normal+comp by-size counts.
      const byNormal = Object.values(safeStats.normal_games_by_size || {}).reduce((a, n) => a + Number(n || 0), 0);
      const byComp   = Object.values(safeStats.comp_games_by_size   || {}).reduce((a, n) => a + Number(n || 0), 0);
      const totalGames = Math.max(Number(safeStats.completed_games || 0), byNormal + byComp);

      const normalWins = Number(safeStats.normal_wins || 0);
      const compWins   = Number(safeStats.competitive_wins || 0);
      const explicitTotalWins = Number(safeStats.total_wins);
      const totalWins = Number.isFinite(explicitTotalWins) ? explicitTotalWins : (normalWins + compWins);

      const mostPlayedCard = getOverallMostPlayedCard(safeStats);
      const mostPlayedStrategy = getOverallMostPlayedStrategy(safeStats);
      const mostPlayedPlayerCount = getMostPlayedPlayerCountLabel(safeStats);
      const noGames = totalGames === 0;

      const set = (id, val) => { const el = $a(id); if (el) el.textContent = val; };

      const hoursOv = Number(safeStats.hours_played || 0);
      set("stat-hours-played", hoursOv === 1 ? "1 hr" : `${hoursOv} hrs`);
      set("ph-ov-most-strategy", mostPlayedStrategy || (noGames ? "No games completed yet." : "—"));
      set("ph-ov-total-games",   String(Math.max(0, totalGames)));
      set("ph-ov-total-wins",    String(Math.max(0, totalWins)));
      set("ph-ov-win-rate",      totalGames > 0 ? `${Math.round((totalWins / totalGames) * 100)}%` : "—");
      set("ph-ov-most-pcount",   mostPlayedPlayerCount || (noGames ? "No games completed yet." : "—"));

      // Per-mode overview stats
      const casualTop = safeStats.highest_score_normal || safeStats.highest_score || 0;
      const compTop   = safeStats.highest_score_competitive || 0;
      const recentGames = Array.isArray(safeStats.recent_games) ? safeStats.recent_games : [];
      const recentNormal = recentGames.filter((g) => String(g?.mode || "normal").toLowerCase() !== "competitive");
      const recentComp = recentGames.filter((g) => String(g?.mode || "").toLowerCase() === "competitive");
      const recentNormalScore = recentNormal.reduce((sum, g) => sum + (Number(g?.s) || 0), 0);
      const recentCompScore = recentComp.reduce((sum, g) => sum + (Number(g?.s) || 0), 0);
      const normalScoreBySize = Object.values(safeStats.total_score_by_size || {}).reduce((sum, v) => sum + (Number(v) || 0), 0);
      const overallScore = Number(safeStats.total_score || 0);
      let casualGames = byNormal > 0 ? byNormal : recentNormal.length;
      let compGames = byComp > 0 ? byComp : recentComp.length;
      const inferredCompGames = Math.max(0, totalGames - casualGames);
      const likelyHasCompData = byComp > 0 || recentComp.length > 0 || compWins > 0 || compTop > 0;
      if (compGames === 0 && inferredCompGames > 0 && likelyHasCompData) compGames = inferredCompGames;
      let casualScoreTotal = normalScoreBySize;
      if (!(casualScoreTotal > 0) && recentNormalScore > 0) casualScoreTotal = recentNormalScore;
      if (!(casualScoreTotal > 0) && overallScore > 0 && compGames === 0) casualScoreTotal = overallScore;
      let compScoreTotal = recentCompScore > 0 ? recentCompScore : 0;
      if (!(compScoreTotal > 0) && overallScore > 0 && casualScoreTotal >= 0 && compGames > 0) {
        const inferredCompScore = overallScore - casualScoreTotal;
        if (inferredCompScore > 0) compScoreTotal = inferredCompScore;
      }
      const avgCasual = casualGames > 0
        ? Math.round((casualScoreTotal > 0 ? casualScoreTotal : recentNormalScore) / Math.max(1, casualGames))
        : null;
      const avgComp = compGames > 0
        ? Math.round((compScoreTotal > 0 ? compScoreTotal : recentCompScore) / Math.max(1, compGames))
        : null;
      set("ph-ov-casual-wins", String(normalWins));
      set("ph-ov-casual-top",  casualTop > 0 ? String(casualTop) : "—");
      set("ph-ov-avg-casual", avgCasual != null && Number.isFinite(avgCasual) ? String(avgCasual) : "—");
      // Overview competitive summary (rank, top score, total comp games)
      const compRankLabel = safeStats.rank_competitive || "No rank yet";
      set("ph-ov-comp-rank", compRankLabel);
      set("ph-ov-comp-top",  compTop > 0 ? String(compTop) : "—");
      set("ph-ov-comp-games", compGames > 0 ? String(compGames) : "—");

      // Total XP Earned
      const totalXpVal = Number(safeStats.total_xp || 0);
      set("ph-ov-total-xp", totalXpVal > 0 ? totalXpVal.toLocaleString() : "—");

      // Achievements unlocked
      const userAchs = (typeof window.__fishGetUserAchievements === "function") ? window.__fishGetUserAchievements() : {};
      const achTotal = ACHIEVEMENT_DEFS.length;
      const achDone  = ACHIEVEMENT_DEFS.filter(d => userAchs[d.id] && userAchs[d.id].completed).length;
      set("ph-ov-achievements", `${achDone} / ${achTotal}`);

      // Animals unlocked
      const allUnlockable = ANIMAL_AVATARS.filter(a => !!a.unlock);
      const animalsTotal   = allUnlockable.length;
      const animalsDone    = allUnlockable.filter(a => isAvatarUnlocked(a.img)).length;
      set("ph-ov-animals", `${animalsDone} / ${animalsTotal}`);

      renderOverviewAchievements(safeStats);
      renderChallengeStrip();

      const activePs = document.querySelector(".ph-pc.active[data-ps]");
      const requestedPs = normalizePhPlayerCount(activePs ? Number(activePs.dataset.ps) : _phSelectedPlayerCount);
      if (window._phSetPs) window._phSetPs(requestedPs);

      // Legacy comp block elements are kept hidden; ranked dashboard is managed by renderPhCompetitive().
    }

    // ── Player Home: overview tab ──────────────────────────────────
    function renderPhOverview() {
      renderOverviewAchievements(_phStatsRaw || _phStats || {});
      renderChallengeStrip();
      // Refresh achievement and animal counts when tab is opened
      const set = (id, val) => { const el = $a(id); if (el) el.textContent = val; };
      const userAchs = (typeof window.__fishGetUserAchievements === "function") ? window.__fishGetUserAchievements() : {};
      const achTotal = ACHIEVEMENT_DEFS.length;
      const achDone  = ACHIEVEMENT_DEFS.filter(d => userAchs[d.id] && userAchs[d.id].completed).length;
      set("ph-ov-achievements", `${achDone} / ${achTotal}`);
      const allUnlockable = ANIMAL_AVATARS.filter(a => !!a.unlock);
      const animalsDone   = allUnlockable.filter(a => isAvatarUnlocked(a.img)).length;
      set("ph-ov-animals", `${animalsDone} / ${allUnlockable.length}`);
    }

    // ── Public Profile Modal ──────────────────────────────────────
    // View-only: shows another player's public overview stats + critter collection.
    // Called from Friends list and Leaderboard rows.
    let _pubProfileData = null; // cached profile for critter view

    // Build a single Quick-Stats card. isString → matches the overview's
    // .ph-sc-string variant (used for word-valued cards like strategy/rank).
    function _pubSc(iconHtml, label, value, colorClass, isString) {
      return `<div class="ph-sc${isString ? " ph-sc-string" : ""}">
        <div class="ph-sci ${colorClass || "ph-sci-blue"}">${iconHtml}</div>
        <div class="ph-scl">${escapeHtml(label)}</div>
        <div class="ph-scv">${escapeHtml(String(value))}</div>
      </div>`;
    }

    // Mirrors the real Overview "Quick Stats" grid exactly (same cards, order,
    // icons, and .ph-sc-string classes) — populated with the target player's
    // data. Read-only; touches no global state.
    function _renderPublicStats(profile) {
      const grid = $a("pub-stats-grid");
      if (!grid) return;
      const s = (profile && typeof profile.stats === "object") ? profile.stats : {};

      const byNormal   = Object.values(s.normal_games_by_size || {}).reduce((a, n) => a + Number(n || 0), 0);
      const byComp     = Object.values(s.comp_games_by_size   || {}).reduce((a, n) => a + Number(n || 0), 0);
      const totalGames = Math.max(Number(s.completed_games || 0), byNormal + byComp);
      const normalWins = Number(s.normal_wins || 0);
      const compWins   = Number(s.competitive_wins || 0);
      const expTotal   = Number(s.total_wins);
      const totalWins  = Number.isFinite(expTotal) ? expTotal : normalWins + compWins;
      const winRate    = totalGames > 0 ? `${Math.round((totalWins / totalGames) * 100)}%` : "—";

      const casualTop  = s.highest_score_normal || s.highest_score || 0;
      const compTop    = s.highest_score_competitive || 0;
      const compGames  = byComp;
      const scoreBySize = Object.values(s.total_score_by_size || {}).reduce((sum, v) => sum + (Number(v) || 0), 0);
      const casualGames = byNormal || Math.max(0, totalGames - compGames);
      const avgCasual   = casualGames > 0 && scoreBySize > 0
        ? Math.round(scoreBySize / Math.max(1, casualGames)) : null;

      const hours = Number(s.hours_played || 0);
      let strat = "—";
      try { strat = getOverallMostPlayedStrategy(s) || "—"; }
      catch { strat = s.most_played_strategy || s.favorite_strategy || "—"; }
      let mostPCount = "—";
      try { mostPCount = getMostPlayedPlayerCountLabel(s) || "—"; }
      catch { mostPCount = s.most_played_player_count ? `${s.most_played_player_count}P` : "—"; }
      const compRank   = s.rank_competitive || "No rank yet";

      // Achievements unlocked (from the target's own achievements map).
      const tAch = (profile.achievements && typeof profile.achievements === "object") ? profile.achievements : {};
      const achDone = ACHIEVEMENT_DEFS.filter(d => tAch[d.id] && tAch[d.id].completed).length;

      // Animals unlocked (from the target's own unlocked_icons).
      const animals    = ANIMAL_AVATARS.filter(a => !!a.unlock);
      const theirIcons = Array.isArray(profile.unlocked_icons)
        ? profile.unlocked_icons.filter(p => typeof p === "string" && p.startsWith("/avatars/")) : [];
      const animalsDone = animals.filter(a => theirIcons.includes(a.img)).length;

      const noGames = totalGames === 0;
      // 7×2: row 1 → Hours, Strategy, Total Games, Total Wins, Win Rate, Player Count, Achievements
      //       row 2 → Casual Wins, Casual Top, Avg Casual, Comp Rank, Best Comp, Comp Games, Animals
      grid.innerHTML = [
        _pubSc(`<svg width="24" height="24" viewBox="0 0 24 24" fill="none"><circle cx="12" cy="12" r="9" stroke="#25a57c" stroke-width="1.8"/><path d="M12 7v5l3 3" stroke="#25a57c" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"/></svg>`,
          "Hours Played", hours === 1 ? "1 hr" : `${hours} hrs`, "ph-sci-teal"),
        _pubSc(`<img src="/avatars/common-octopus.png?v=ws12" alt="" draggable="false" style="width:34px;height:34px;object-fit:contain;pointer-events:none;">`,
          "Most Played Strategy", strat !== "—" ? strat : (noGames ? "No games completed yet." : "—"), "ph-sci-blue", true),
        _pubSc("🧮", "Total Games",   totalGames > 0 ? totalGames : "—", "ph-sci-purple"),
        _pubSc("🥇", "Total Wins",    totalWins  > 0 ? totalWins  : "—", "ph-sci-gold"),
        _pubSc("📈", "Win Rate",      winRate,                           "ph-sci-teal"),
        _pubSc("👥", "Most Played Player Count", mostPCount !== "—" ? mostPCount : (noGames ? "No games completed yet." : "—"), "ph-sci-blue", true),
        _pubSc("🏆", "Achievements", `${achDone} / ${ACHIEVEMENT_DEFS.length}`, "ph-sci-gold"),
        _pubSc("🌊", "Casual Wins",   normalWins > 0 ? normalWins : "—", "ph-sci-teal"),
        _pubSc("🏅", "Casual Top Score", casualTop > 0 ? casualTop : "—", "ph-sci-blue"),
        _pubSc("📊", "Average Casual Score",
          avgCasual != null && Number.isFinite(avgCasual) ? avgCasual : "—", "ph-sci-gold"),
        _pubSc("⚔️", "Competitive Rank", compRank, "ph-sci-gold", true),
        _pubSc("🏆", "Best Competitive Score", compTop > 0 ? compTop : "—", "ph-sci-purple"),
        _pubSc("🎮", "Competitive Games", compGames > 0 ? compGames : "—", "ph-sci-blue"),
        _pubSc("🐠", "Animals Unlocked", `${animalsDone} / ${animals.length}`, "ph-sci-teal"),
      ].join("");
    }

    async function openPublicProfile(uid) {
      if (!uid || !_db) return;
      const overlay  = $a("pub-profile-overlay");
      const loading  = $a("pub-loading");
      const errEl    = $a("pub-error");
      const content  = $a("pub-content");
      if (!overlay) return;
      // Show overlay
      overlay.style.display = "";
      loading.style.display  = "";
      errEl.style.display    = "none";
      content.style.display  = "none";
      overlay.scrollTop = 0;
      document.body.style.overflow = "hidden";
      let profile;
      try {
        profile = await loadProfile(uid);
      } catch (e) {
        loading.style.display = "none";
        errEl.style.display   = "";
        errEl.textContent     = "Could not load profile. Please try again.";
        return;
      }
      if (!profile) {
        loading.style.display = "none";
        errEl.style.display   = "";
        errEl.textContent     = "Profile not found.";
        return;
      }
      _pubProfileData = profile;
      // Header
      const avatarUrl = (typeof normalizeAvatarUrl === "function")
        ? (normalizeAvatarUrl(profile.avatar_url || "") || "/avatars/mullet.png")
        : (profile.avatar_url || "/avatars/mullet.png");
      const avatarImg = $a("pub-avatar-img");
      if (avatarImg) {
        avatarImg.src = _avSrc(avatarUrl); avatarImg.alt = (profile.nickname || "Player") + " avatar";
        try { const bgn = normalizeBgUrl(profile.background_url || ""); _applyAvBg(avatarImg.parentElement, (bgn && _BG_BY_IMG[bgn]) ? bgn : ""); } catch {}
      }
      const nick = profile.nickname || "Unknown";
      const nickEl = $a("pub-nick");
      if (nickEl) nickEl.textContent = nick;

      const pStats = (profile && typeof profile.stats === "object") ? profile.stats : {};

      // Friend code — public (you can always accept/decline a request anyway).
      const fcEl = $a("pub-fc");
      if (fcEl) fcEl.textContent = profile.friend_code
        ? formatFriendCodeLabel(nick, String(profile.friend_code).trim()) : "";

      // Level + XP progress bar (mirrors the real profile card).
      let lp = { level: 1, xpCurrent: 0, xpGoal: 50, totalXp: 0 };
      try { lp = getLevelProgressFromTotalXp(getStoredTotalXp(pStats)); } catch {}
      const lvlLabel = $a("pub-level-label");
      if (lvlLabel) lvlLabel.textContent = `Level ${lp.level || 1}`;
      const xpFill = $a("pub-level-xp-fill");
      if (xpFill) {
        const pct = lp.xpGoal > 0 ? Math.max(0, Math.min(100, Math.round((lp.xpCurrent / lp.xpGoal) * 100))) : 100;
        xpFill.style.width = pct + "%";
      }
      const xpText = $a("pub-level-xp-text");
      if (xpText) xpText.textContent = `${Math.round(lp.xpCurrent)} / ${Math.round(lp.xpGoal)} XP`;

      // Total XP chip.
      const totalXpEl = $a("pub-total-xp");
      if (totalXpEl) {
        let tx = 0; try { tx = getStoredTotalXp(pStats); } catch {}
        totalXpEl.textContent = Number(tx || 0).toLocaleString(undefined, { maximumFractionDigits: 0 });
      }

      // Current daily streak chip.
      const streakEl = $a("pub-streak");
      if (streakEl) {
        let cur = 0;
        try { cur = _computeStreakInfo(pStats.streak_days).current || 0; } catch {}
        streakEl.textContent = cur === 1 ? "1 day" : `${cur} days`;
      }

      // Competitive rank badge.
      const compRankEl = $a("pub-comp-rank");
      if (compRankEl) {
        const rankLabel = pStats.rank_competitive;
        compRankEl.textContent = (rankLabel && rankLabel !== "Unranked") ? rankLabel : "No rank yet.";
      }

      // Stats grid (mirrors the real Overview Quick Stats)
      _renderPublicStats(profile);
      loading.style.display = "none";
      content.style.display = "";
    }

    // Wire close button + avatar (→ critter gallery)
    (function() {
      const overlay = $a("pub-profile-overlay");
      const closeBtn = $a("pub-close-btn");
      const avatarBtn = $a("pub-avatar-btn");
      if (closeBtn) closeBtn.addEventListener("click", () => {
        if (overlay) overlay.style.display = "none";
        document.body.style.overflow = "";
        _pubProfileData = null;
      });
      // Avatar → open the real Avatar Gallery in view-only mode for this player
      if (avatarBtn) avatarBtn.addEventListener("click", () => {
        if (!_pubProfileData) return;
        openPublicCritterGallery(_pubProfileData);
      });
      // Close on overlay background click
      if (overlay) overlay.addEventListener("click", e => {
        if (e.target === overlay) {
          overlay.style.display = "none";
          document.body.style.overflow = "";
          _pubProfileData = null;
        }
      });
    })();

